/* Java 高级课程正文注册表（由 frag-adv 碎片自动生成）。
   合并扩展已有 QZ_CONTENT（中级），不覆盖；key = track|stack|lessonName。 */
window.QZ_CONTENT = (function (prev) {
  'use strict';
  var data = {
    "backend|java|把模糊需求变成系统战略": { "body": "<p class=\"lead\">中级教你「把清楚的需求设计好」，高级教你「把不清楚的愿望定义清楚」。这一课不写代码、不选中间件，先学会把管理层一句「六个月建统一 AI 平台」拆成值得解决、能验证、能分阶段投资的问题。</p>\n  \n  <div class=\"journey\">\n    <div class=\"j-step\"><span class=\"n\">1</span><span class=\"t\">退回去</span><span class=\"s\">方案→问题</span></div>\n    <div class=\"j-step\"><span class=\"n\">2</span><span class=\"t\">找对人</span><span class=\"s\">谁拍板</span></div>\n    <div class=\"j-step\"><span class=\"n\">3</span><span class=\"t\">定指标</span><span class=\"s\">北极星+护栏</span></div>\n    <div class=\"j-step\"><span class=\"n\">4</span><span class=\"t\">动手</span><span class=\"s\">两场演练</span></div>\n    <div class=\"j-step\"><span class=\"n\">5</span><span class=\"t\">自测</span><span class=\"s\">六个问题</span></div>\n  </div>\n\n  <section id=\"a\">\n    <h2><span class=\"no\">第 1 步</span>「建统一平台」是方案，不是问题</h2>\n    <p>先讲个故事。病人走进诊室说「我最近不太舒服，给我开点药」。庸医立刻开药；好医生先问：哪儿不舒服、多久了、什么情况下加重、希望恢复到什么程度。因为「不舒服」可能是十种完全不同的病，吃错药不但没用，还会掩盖真症状。</p>\n    <p>管理层丢来一句：<span class=\"term\">「六个月内建设统一 AI 平台，提高各团队用 AI 的效率。」</span>这和「给我开点药」一样，是<b>把问题包装成了方案</b>。如果你立刻接「上 Kubernetes、拆微服务、建网关」，六个月后可能交付了一套很复杂的系统，却没改善任何业务结果。</p>\n    <p>高级的第一动作是<b>连续追问「为什么」</b>，从方案退回到问题：</p>\n    <figure>\n      <svg viewBox=\"0 0 760 210\" role=\"img\" aria-label=\"从方案追问退回问题\">\n        <defs><marker id=\"ara1\" markerWidth=\"8\" markerHeight=\"8\" refX=\"6\" refY=\"3\" orient=\"auto\"><path d=\"M0,0 L6,3 L0,6 Z\" fill=\"#A39B8E\"/></marker></defs>\n        <rect x=\"8\" y=\"20\" width=\"220\" height=\"52\" rx=\"10\" fill=\"#FBEDE9\" stroke=\"#F0CFC6\"/><text x=\"118\" y=\"42\" text-anchor=\"middle\" font-size=\"12.5\" font-weight=\"bold\" fill=\"#B04A35\">「建统一 AI 平台」</text><text x=\"118\" y=\"60\" text-anchor=\"middle\" font-size=\"11\" fill=\"#7C7166\">这是一个方案</text>\n        <rect x=\"270\" y=\"20\" width=\"220\" height=\"52\" rx=\"10\" fill=\"#FBF3E4\" stroke=\"#EDD9B4\"/><text x=\"380\" y=\"42\" text-anchor=\"middle\" font-size=\"12.5\" font-weight=\"bold\" fill=\"#8A5510\">为什么？重复建设</text><text x=\"380\" y=\"60\" text-anchor=\"middle\" font-size=\"11\" fill=\"#7C7166\">接入慢·成本高·风险不可控</text>\n        <rect x=\"532\" y=\"20\" width=\"220\" height=\"52\" rx=\"10\" fill=\"#E9F4F2\" stroke=\"#BFE0DB\"/><text x=\"642\" y=\"42\" text-anchor=\"middle\" font-size=\"12.5\" font-weight=\"bold\" fill=\"#1E7268\">再为什么？缺统一治理</text><text x=\"642\" y=\"60\" text-anchor=\"middle\" font-size=\"11\" fill=\"#7C7166\">密钥·审批·计量各自为政</text>\n        <line x1=\"228\" y1=\"46\" x2=\"268\" y2=\"46\" stroke=\"#A39B8E\" stroke-width=\"2\" marker-end=\"url(#ara1)\"/>\n        <line x1=\"490\" y1=\"46\" x2=\"530\" y2=\"46\" stroke=\"#A39B8E\" stroke-width=\"2\" marker-end=\"url(#ara1)\"/>\n        <rect x=\"8\" y=\"100\" width=\"744\" height=\"56\" rx=\"10\" fill=\"#ECF1FB\" stroke=\"#C9D8F2\"/>\n        <text x=\"380\" y=\"124\" text-anchor=\"middle\" font-size=\"12.5\" font-weight=\"bold\" fill=\"#2F58A8\">真问题：在不降低安全与可靠性的前提下，让团队更快、更可控地用批准的 AI 能力，且成本可归因</text>\n        <text x=\"380\" y=\"144\" text-anchor=\"middle\" font-size=\"11\" fill=\"#7C7166\">这个表述不预设「必须自研大平台」，于是保留了改造网关 / 统一流程 / 采购 / 只统一审计等多种方案</text>\n        <text x=\"380\" y=\"186\" text-anchor=\"middle\" font-size=\"12\" fill=\"#A39B8E\">方案空间要保护到「证据足够」那一刻，再收窄</text>\n      </svg>\n      <figcaption>图 1 · 从一句愿望追问到真问题：先诊断，再开方。</figcaption>\n    </figure>\n    <p>注意「模型费用上涨」只是<b>症状</b>，不是问题本身。根因可能是请求量正常增长、全都用最高价模型、重试重复扣费、上下文没裁剪、测试环境用生产额度……不先定位根因就做缓存、换模型、设预算上限，可能伤了业务却没解决问题。把症状拆成<b>问题树</b>，叶子节点才值得进入验证：</p>\n    <table>\n      <tr><th>症状</th><th>可能的根因（叶子）</th><th>对应动作方向</th></tr>\n      <tr><td>月成本 +45%</td><td>高价模型占比 30%→65%</td><td>模型分层路由</td></tr>\n      <tr><td>月成本 +45%</td><td>无效调用约 12%（重试重复扣费）</td><td>幂等 + 预算护栏</td></tr>\n      <tr><td>接入要 6 周</td><td>每团队重做供应商评估 / 密钥 / 审批</td><td>统一准入 + SDK 模板</td></tr>\n      <tr><td>数据流向不可审计</td><td>无统一身份与审计</td><td>统一身份 / 审计</td></tr>\n    </table>\n    <div class=\"key\"><span class=\"tag\">一句话记住</span>「平台 / 微服务 / Kubernetes」是候选方案；用户、场景、影响、紧迫性才是问题。先写诊断书，再谈上手术台。</div>\n    <div class=\"recap\"><b>收束：</b>把愿望翻译成「谁、在什么场景、遇到什么问题、造成什么影响、为什么现在必须解决」五件套。</div>\n  </section>\n\n  <section id=\"b\">\n    <h2><span class=\"no\">第 2 步</span>平台没有单一用户：先弄清谁拍板</h2>\n    <p>中级任务通常只有一个「客户」。高级的平台至少服务六类人，而且他们的目标<b>天然冲突</b>：业务要「任何模型马上试用」，安全要「没评估的一律禁止」；研发要「接口永远不变」，平台要「持续演进协议」；财务要「最便宜」，产品要「最好」。</p>\n    <p>高级工程师不是让所有人满意，而是<b>把冲突摆到桌面上</b>，定决策原则和责任人。用 <span class=\"term2\">RACI</span> 给每个关键决策标清楚：谁执行(R)、谁最终负责(A，只能有一个)、谁必须被征询(C)、谁只需被告知(I)。</p>\n    <table>\n      <tr><th>决策</th><th>业务</th><th>平台</th><th>SRE</th><th>安全</th><th>财务</th></tr>\n      <tr><td>第一阶段范围</td><td>A</td><td>R</td><td>C</td><td>C</td><td>C</td></tr>\n      <tr><td>模型供应商准入</td><td>C</td><td>R</td><td>C</td><td>A</td><td>C</td></tr>\n      <tr><td>平台 SLO</td><td>C</td><td>R</td><td>A</td><td>I</td><td>C</td></tr>\n      <tr><td>单位成本目标</td><td>C</td><td>R</td><td>I</td><td>I</td><td>A</td></tr>\n    </table>\n    <p>取舍时先把口号变成可比较的场景，再比方案。<b>合规是硬约束，先过滤</b>，不是拿来加权平均的一个分数；剩下的方案才在质量、延迟、成本之间权衡：</p>\n    <table>\n      <tr><th>方案（客服摘要）</th><th>质量≥95%</th><th>P95≤3s</th><th>成本/千次≤20元</th><th>合规</th><th>结论</th></tr>\n      <tr><td>高价通用模型</td><td>高</td><td>中</td><td>高</td><td>满足</td><td>只用于复杂请求</td></tr>\n      <tr><td>小模型</td><td>中</td><td>高</td><td>低</td><td>满足</td><td>用于标准摘要</td></tr>\n      <tr><td>未批准海外模型</td><td>高</td><td>高</td><td>中</td><td>不满足</td><td>直接淘汰</td></tr>\n    </table>\n    <div class=\"key\"><span class=\"tag\">一句话记住</span>一项关键决策若有多个 A，等于出问题时没人真正负责。硬约束先过滤，软目标再权衡。</div>\n    <div class=\"recap\"><b>收束：</b>识别冲突 → 标 RACI → 定决策原则 → 硬约束过滤 → 软目标权衡。</div>\n  </section>\n\n  <section id=\"c\">\n    <h2><span class=\"no\">第 3 步</span>北极星量结果，护栏守红线</h2>\n    <p>「上线 20 个微服务」「建成 K8s 集群」「写完 100 个 API」都<b>不是</b>业务成功指标——它们是产出(Output)，不是效果(Outcome)。就像买了跑步机不等于瘦了。</p>\n    <p><span class=\"term\">北极星指标</span>要量「平台为用户持续创造的核心价值」，例如：<b>每月通过平台完成、且满足质量与安全标准的生产 AI 任务数</b>。它同时要求真在生产用、任务完成、质量达标、通过治理。再拆成指标树解释价值怎么产生（采纳 / 任务价值 / 可靠性 / 安全 / 经济性）。</p>\n    <p>但只盯北极星会诱发局部优化：为冲任务数而放宽安全、用廉价差模型、隐藏失败请求。所以要配<span class=\"term2\">护栏指标</span>——「不许越线」的红线：</p>\n    <table>\n      <tr><th>你想优化</th><th>护栏（不许变坏）</th></tr>\n      <tr><td>缩短接入周期</td><td>高危安全问题 = 0</td></tr>\n      <tr><td>降低模型成本</td><td>质量评测下降 ≤ 1%</td></tr>\n      <tr><td>提高调用量</td><td>请求成功率 ≥ SLO</td></tr>\n      <tr><td>加快发布</td><td>变更失败率 / 平均恢复时间不恶化</td></tr>\n    </table>\n    <p>每个指标还必须<b>可运营</b>：定义、公式、数据源、维度、频率、负责人、目标值、护栏，缺一不可。否则「接入周期下降」只是一句没人能复核的口号。</p>\n    <div class=\"key\"><span class=\"tag\">一句话记住</span>北极星回答「业务有没有变好」，护栏回答「有没有靠伤害别的东西变好」。注册数、调用总量是虚荣指标，不能单独证明价值。</div>\n    <div class=\"recap\"><b>收束：</b>一个北极星 + 指标树 + 一组护栏 + 每个指标有负责人和数据源。</div>\n  </section>\n\n  <section id=\"d\">\n    <h2><span class=\"no\">第 4 步</span>假设、约束、未知分开管；门分双向单向</h2>\n    <p>三样东西常被混在一起，混了就会赌：<span class=\"term\">假设</span>=现在认为真但没验证（「统一 SDK 能缩短接入」）；<span class=\"term2\">约束</span>=当前必须遵守的边界（「敏感数据不出指定地域」）；<b>未知</b>=连可信判断都没有（「明年 Agent 长任务占多少流量」）。把假设当事实会大规模投错；把可改变的条件当永久约束会限制方案空间。</p>\n    <p>假设要登记并<b>优先验证「高影响 + 高不确定」</b>的那条，而不是先验证最容易的。每条写清：验证方式、截止时间、失败后动作。未知项要有消除计划和决策截止点；到点仍未知，就选更可逆的方案、留余量、缩范围。</p>\n    <p>决策还要分<b>双向门 / 单向门</b>：双向门走错能退回来（试用一个供应商、加一个 Dashboard），快速小步试；单向门推开就锁死（全公司统一身份主键、迁到不可导出的 SaaS），才值得花时间反复论证 + 迁移 PoC + 回滚计划。把所有决策当单向门，组织极慢；把单向门当双向门，留下昂贵锁定。</p>\n    <div class=\"key\"><span class=\"tag\">一句话记住</span>假设待验证、约束待确认来源、未知待消除；可逆的先试，不可逆的才重论证。Java 小模拟器是用来「尽快推翻或支持假设」，不是提前建完整平台。</div>\n    <div class=\"recap\"><b>收束：</b>登记假设/约束/未知 → 先验高影响高不确定 → 按门的类型决定论证强度。</div>\n  </section>\n\n  <section id=\"e\">\n    <h2><span class=\"no\">第 5 步</span>管住范围：Now / Next / Later 与非目标</h2>\n    <p>「统一 AI 平台」很容易一口气包含网关、RAG、Agent、微调、GPU 调度、评测、门户、计费、多地域容灾……六人团队六个月不可能全做好。范围管理不是删需求，而是<b>选最小能力组合尽早产生可验证价值</b>：</p>\n    <table>\n      <tr><th>Now（第一阶段必须）</th><th>Next（验证价值后）</th><th>Later（触发条件出现再定）</th></tr>\n      <tr><td>复用现有网关统一访问批准模型</td><td>标准任务模型分层路由</td><td>统一 Workflow 引擎</td></tr>\n      <tr><td>统一身份 / 租户 / 密钥 / 审计</td><td>RAG 能力目录 + 统一评测</td><td>自建推理集群 / 微调平台</td></tr>\n      <tr><td>用量与成本归因 + SDK 模板</td><td>自助申请 / 预算 / 权限工作流</td><td>多地域主动—主动</td></tr>\n      <tr><td>两个真实团队生产迁移</td><td>更完整开发者门户</td><td>全面 K8s 平台化</td></tr>\n    </table>\n    <p><b>非目标是正式承诺</b>，不是文末免责声明：「不重写已稳定的网关」「不自研向量数据库」「不以 K8s 迁移作为成功指标」。它保护团队免受隐性期待。阶段路线要按<b>端到端价值垂直切片</b>（阶段1一个团队跑通一条生产链路 → 阶段2两团队自助接入闭环 → 阶段3路由验证成本质量），而不是「前五月搭基础设施、最后一月统一上线」那种风险集中爆发式横向施工。</p>\n    <p>最后，高级不仅定义开始条件，还定义<b>停止投资条件</b>：三个月仍无第二个生产团队愿迁、接入周期没比标准 SDK 明显改善、自研总成本连续两季高于采购……及时停止错误投资，是对结果负责，不是失败。</p>\n    <div class=\"key\"><span class=\"tag\">一句话记住</span>每阶段都要可独立验收、可调整、可停止；新增需求必须回答「延后或删除什么」，不能只加工作量。</div>\n    <div class=\"recap\"><b>收束：</b>Now/Next/Later + 非目标承诺 + 垂直切片阶段 + 决策门（继续/调整/暂停/停止）。</div>\n  </section>\n\n  <section id=\"lab\">\n    <h2><span class=\"no\">动手</span>两场演练：方案vs问题、路由成本沙盒</h2>\n    <p>演练一看同一句话的「方案口径」和「问题口径」差别。演练二拖动滑块，亲手验证「把标准任务路由到便宜模型能省多少钱、会不会破质量护栏」——体会「用最小模拟验证假设，而不是先建路由平台」。</p>\n    <div class=\"lab\">\n      <div class=\"lab-head\"><b>演练一 · 两种口径</b><span class=\"hint\">点按钮切换</span></div>\n      <div class=\"controls\"><div class=\"seg\" id=\"e1\"><button data-k=\"sol\" class=\"on\">❌ 方案口径</button><button data-k=\"prob\">✅ 问题口径</button></div></div>\n      <div class=\"lab-body\"><div><pre id=\"e1code\" style=\"margin:0;\"></pre></div><div class=\"logcat\"><div class=\"logcat-head\"><span>说明</span><span>live</span></div><div class=\"logcat-body\" id=\"e1log\"></div></div></div>\n      <div class=\"lab-foot\"><span class=\"hint\">同一句愿望，两种命运</span></div>\n    </div>\n    <div class=\"lab\">\n      <div class=\"lab-head\"><b>演练二 · 路由成本沙盒</b><span class=\"hint\">拖滑块，验证省钱假设</span></div>\n      <div class=\"controls\">\n        <div class=\"ctl\"><label>标准任务占比%</label><input type=\"range\" id=\"g1std\" min=\"0\" max=\"100\" value=\"70\"><span class=\"val\" id=\"g1stdV\">70</span></div>\n        <div class=\"ctl\"><label>经济模型质量</label><input type=\"range\" id=\"g1eq\" min=\"80\" max=\"99\" value=\"91\"><span class=\"val\" id=\"g1eqV\">91</span></div>\n        <div class=\"ctl\"><label>任务质量门槛</label><input type=\"range\" id=\"g1th\" min=\"80\" max=\"99\" value=\"90\"><span class=\"val\" id=\"g1thV\">90</span></div>\n        <div class=\"ctl\"><label>经济单价(分)</label><input type=\"range\" id=\"g1ec\" min=\"1\" max=\"10\" value=\"2\"><span class=\"val\" id=\"g1ecV\">2</span></div>\n        <div class=\"ctl\"><label>高价单价(分)</label><input type=\"range\" id=\"g1pc\" min=\"5\" max=\"30\" value=\"10\"><span class=\"val\" id=\"g1pcV\">10</span></div>\n      </div>\n      <div class=\"lab-body\"><div><div class=\"stats\" id=\"g1stats\"></div><div class=\"chips\" id=\"g1chips\"></div><div class=\"key\" id=\"g1hint\"></div></div><div class=\"logcat\"><div class=\"logcat-head\"><span>推导过程</span><span>live</span></div><div class=\"logcat-body\" id=\"g1log\"></div></div></div>\n      <div class=\"lab-foot\"><span class=\"hint\">基线：全部走高价模型。护栏：经济模型质量 ≥ 任务门槛才路由</span></div>\n    </div>\n    <div class=\"key\"><span class=\"tag\">看懂这两场演练</span>问题口径保留方案空间、能验收；路由沙盒告诉你「省 30%」是假设不是事实——质量门槛一提高，省钱空间立刻缩水，这正是先做小模拟的意义。</div>\n  </section>\n\n  <section id=\"quiz\">\n    <h2><span class=\"no\">自测</span>六个问题</h2>\n    <div class=\"card\" id=\"quiz-box\"></div>\n    <p id=\"quiz-done\" style=\"display:none;font-weight:700;color:#1E7268;\">全对。你已经会用「负责」的眼睛看一句需求了。下一课把问题变成可评审的目标架构。</p>\n  </section>\n\n  <section id=\"map\">\n    <h2><span class=\"no\">回顾</span>速查表</h2>\n    <table>\n      <tr><th>概念</th><th>大白话</th><th>要点</th></tr>\n      <tr><td>问题陈述</td><td>把愿望写成诊断书</td><td>谁/场景/问题/影响/为何现在</td></tr>\n      <tr><td>症状 vs 根因</td><td>发烧 vs 感染源</td><td>问题树叶子才值得验证</td></tr>\n      <tr><td>RACI</td><td>谁干活/谁拍板/谁被问/谁被告知</td><td>A 只能有一个</td></tr>\n      <tr><td>北极星指标</td><td>最能代表业务变好的一个数</td><td>量结果不是量交付物</td></tr>\n      <tr><td>护栏指标</td><td>不许变坏的红线</td><td>安全/质量/SLO/成本</td></tr>\n      <tr><td>假设/约束/未知</td><td>待验证/必须遵守/待调查</td><td>分开登记，先验高影响高不确定</td></tr>\n      <tr><td>双向门/单向门</td><td>能退回/推开锁死</td><td>可逆快试，不可逆重论证</td></tr>\n      <tr><td>Now/Next/Later</td><td>现在做/验证后做/条件出现再做</td><td>配非目标承诺管住范围</td></tr>\n    </table>\n    <div class=\"note\"><span class=\"tag\">说明</span>本页为教学整理，星河集团数字为课程场景假设；路由沙盒为模拟推导，非真实压测或评测。口径以高级课程 README 与第一篇底稿为准。</div>\n  </section>\n\n  <section id=\"refs\">\n    <h2><span class=\"no\">依据</span>参考链接</h2>\n    <div class=\"card refs\">\n      <h3 style=\"margin-top:0;\">原始底稿（本仓库）</h3>\n      <ul>\n        <li>《AI 后端开发：Java 实战》高级工程师 · 第一篇-从模糊需求到系统战略 <span class=\"src\">— 本课重写底稿</span></li>\n        <li>高级工程师/README.md <span class=\"src\">— 七类责任、Rubric、课程边界的权威口径</span></li>\n      </ul>\n      <h3>方法与规范</h3>\n      <ul>\n        <li><a href=\"https://adr.github.io/\" target=\"_blank\" rel=\"noopener\">ADR · Architecture Decision Records</a> <span class=\"src\">— 把决策与理由写成可评审记录</span></li>\n        <li><a href=\"https://sre.google/sre-book/embracing-risk/\" target=\"_blank\" rel=\"noopener\">Google SRE · Embracing Risk</a> <span class=\"src\">— 错误预算与护栏思想的来源</span></li>\n        <li><a href=\"https://sre.google/sre-book/service-level-objectives/\" target=\"_blank\" rel=\"noopener\">Google SRE · Service Level Objectives</a> <span class=\"src\">— 指标如何定义到可运营</span></li>\n      </ul>\n      <h3>下一课要用</h3>\n      <ul>\n        <li><a href=\"https://adr.github.io/\" target=\"_blank\" rel=\"noopener\">ADR 模板</a> <span class=\"src\">— A2 架构驱动设计将用 ADR 记录质量属性取舍</span></li>\n      </ul>\n    </div>\n    \n    \n  </section>", "toc": [{"id":"a","title":"方案→问题"},{"id":"b","title":"谁拍板"},{"id":"c","title":"北极星+护栏"},{"id":"d","title":"假设与门"},{"id":"e","title":"范围与非目标"},{"id":"lab","title":"两场演练"},{"id":"quiz","title":"本课自测"},{"id":"map","title":"速查表"},{"id":"refs","title":"参考链接"}], "scripts": "(function(){\n  var SOL=\"// ❌ 方案口径：只有一句方案\\n「六个月建设统一 AI 平台」\\n→ 上 Kubernetes\\n→ 拆微服务\\n→ 建网关 / RAG / Agent\\n→ 选向量库 / 消息队列 / 配置中心\";\n  var PROB=\"// ✅ 问题口径：五件套诊断书\\n谁：各业务 AI 应用团队\\n场景：接入模型/知识库/Agent 时重复做适配/密钥/审批/治理\\n问题：接入中位 6 周、成本无法归因、数据流向不可审计\\n影响：上线速度、预算、合规已受拖累\\n为何现在：应用与费用快速增长，再不治理失控\";\n  function show(k){document.getElementById(\"e1code\").textContent=(k===\"sol\"?SOL:PROB);document.getElementById(\"e1log\").innerHTML=\"<div><span class=\\\"\"+(k===\"sol\"?\"err\":\"ok\")+\"\\\">\"+(k===\"sol\"?\"预设了唯一方案，六个月后可能没改善任何业务结果\":\"不预设自研大平台，保留改造/采购/统一流程等多种方案\")+\"</span></div><div><span class=\\\"c\\\">// \"+(k===\"sol\"?\"无法验收：不知道怎样算成功\":\"可以验收：接入周期/成本归因/审计都有目标值\")+\"</span></div>\";}\n  document.querySelectorAll(\"#e1 button\").forEach(function(b){b.addEventListener(\"click\",function(){document.querySelectorAll(\"#e1 button\").forEach(function(x){x.classList.remove(\"on\");});b.classList.add(\"on\");show(b.getAttribute(\"data-k\"));});});\n  show(\"sol\");\n})();\n\n// 演练二：路由成本沙盒\n(function(){\n  var ids=['std','eq','th','ec','pc'];\n  function val(id){return parseInt(document.getElementById('g1'+id).value,10);}\n  function calc(){\n    ids.forEach(function(id){document.getElementById('g1'+id+'V').textContent=val(id);});\n    var std=val('std')/100, eq=val('eq'), th=val('th'), ec=val('ec'), pc=val('pc');\n    var N=100000; // 月请求数假设\n    var baseline=N*pc;             // 全走高价\n    var routed = (eq>=th) ? std : 0; // 质量护栏：经济模型达标才路由\n    var simCost=N*(routed*ec+(1-routed)*pc);\n    var savePct=(baseline-simCost)/baseline*100;\n    var okQ = eq>=th;\n    var okSave = savePct>=25;\n    document.getElementById('g1stats').innerHTML=\n      '<div class=\"stat-box\"><b>'+(baseline/100).toFixed(0)+'</b><small>基线月成本(元)</small></div>'+\n      '<div class=\"stat-box\"><b>'+(simCost/100).toFixed(0)+'</b><small>模拟月成本(元)</small></div>'+\n      '<div class=\"stat-box '+(okSave?'good':'bad')+'\"><b>'+savePct.toFixed(1)+'%</b><small>节省</small></div>';\n    document.getElementById('g1chips').innerHTML=\n      '<span class=\"chip '+(okQ?'on':'bad')+'\">质量护栏 '+(okQ?'达标':'破线：不路由')+'</span>'+\n      '<span class=\"chip '+(okSave?'on':'bad')+'\">节省 '+(okSave?'≥25% 假设成立':'<25% 假设不成立')+'</span>';\n    document.getElementById('g1hint').innerHTML='<span class=\"tag\">'+(okQ?'推导':'护栏')+'</span>'+\n      (okQ?'经济模型质量 '+eq+' ≥ 门槛 '+th+'，'+(std*100).toFixed(0)+'% 标准任务可路由到便宜模型。':'经济模型质量 '+eq+' < 门槛 '+th+'，护栏生效：一个任务都不路由，节省 0%。提高质量门槛会立刻吃掉省钱空间。');\n    document.getElementById('g1log').innerHTML=[\n      '<div><span class=\"api\">基线 = '+N.toLocaleString()+' 请求 × '+pc+' 分 = '+(baseline/100).toFixed(0)+' 元</span></div>',\n      '<div><span class=\"'+(okQ?'ok':'err')+'\">质量护栏：经济 '+eq+' vs 门槛 '+th+' → '+(okQ?'允许路由':'禁止路由')+'</span></div>',\n      '<div><span class=\"ok\">可路由比例 = '+(routed*100).toFixed(0)+'%</span></div>',\n      '<div><span class=\"ok\">模拟 = '+N.toLocaleString()+' × ('+(routed*100).toFixed(0)+'%×'+ec+' + '+((1-routed)*100).toFixed(0)+'%×'+pc+') = '+(simCost/100).toFixed(0)+' 元</span></div>',\n      '<div><span class=\"c\">// 节省 '+savePct.toFixed(1)+'% → '+(okSave?'支持「降25%」投资假设':'推翻假设，应缩范围或改方案')+'</span></div>'\n    ].join('');\n  }\n  ids.forEach(function(id){document.getElementById('g1'+id).addEventListener('input',calc);});\n  calc();\n})();\n\nconst QUIZ=[{\"q\":\"1. 「六个月建统一 AI 平台」属于？\",\"opts\":[[\"候选方案，不是问题\",true,\"对。先追问为什么，退回真问题。\"],[\"问题陈述\",false,\"它没有用户/影响/成功标准。\"],[\"北极星指标\",false,\"那是量结果的数。\"]]},{\"q\":\"2. 下列哪个是业务结果指标？\",\"opts\":[[\"每月达标完成的生产 AI 任务数\",true,\"对。量效果不是量交付物。\"],[\"上线 20 个微服务\",false,\"那是产出。\"],[\"SDK 下载次数\",false,\"虚荣指标。\"]]},{\"q\":\"3. 护栏指标的作用是？\",\"opts\":[[\"防止靠伤害安全/质量/SLO 来优化北极星\",true,\"对。不许越线的红线。\"],[\"让北极星涨得更快\",false,\"恰恰是限制局部优化。\"],[\"统计交付物数量\",false,\"那是产出计数。\"]]},{\"q\":\"4. 「敏感数据不得出指定地域」属于？\",\"opts\":[[\"约束\",true,\"对。当前必须遵守的边界。\"],[\"假设\",false,\"假设是待验证的猜测。\"],[\"未知项\",false,\"未知是连判断都没有。\"]]},{\"q\":\"5. 全公司统一身份主键属于哪种决策？\",\"opts\":[[\"单向门：需强证据+迁移PoC+回滚计划\",true,\"对。推开就锁死。\"],[\"双向门：快速小步试\",false,\"迁移昂贵不可逆。\"],[\"无需决策\",false,\"恰恰是最该论证的。\"]]},{\"q\":\"6. 非目标（这次不做什么）是？\",\"opts\":[[\"正式承诺，保护团队免受隐性期待\",true,\"对。不是文末免责声明。\"],[\"可有可无的补充\",false,\"它决定阶段能否独立验收。\"],[\"范围失控的借口\",false,\"恰恰是管住范围。\"]]}];" },
    "backend|java|架构取舍与质量属性": { "body": "<p class=\"lead\">A1 把愿望变成了问题，这一课把问题变成「系统在压力、故障、攻击下要做得多好」的可验收场景，再比较几套都可行的架构，说清选谁、放弃什么、哪个风险还没验证。</p>\n  \n  <div class=\"journey\">\n    <div class=\"j-step\"><span class=\"n\">1</span><span class=\"t\">找驱动力</span><span class=\"s\">什么改变架构</span></div>\n    <div class=\"j-step\"><span class=\"n\">2</span><span class=\"t\">写场景</span><span class=\"s\">六要素</span></div>\n    <div class=\"j-step\"><span class=\"n\">3</span><span class=\"t\">比方案</span><span class=\"s\">硬约束+权衡</span></div>\n    <div class=\"j-step\"><span class=\"n\">4</span><span class=\"t\">动手</span><span class=\"s\">两场演练</span></div>\n    <div class=\"j-step\"><span class=\"n\">5</span><span class=\"t\">自测</span><span class=\"s\">六个问题</span></div>\n  </div>\n\n  <section id=\"a\">\n    <h2><span class=\"no\">第 1 步</span>造桥先问「抗几级风」，不是「有哪些部件」</h2>\n    <p>先讲个故事。有人委托你造桥，只说「要结实、要快、要便宜」。你没法开工——得追问：能扛几级风、多少年一遇的洪水、桥面多宽、断一条车道多久恢复、预算上限、哪条绝对不能让步。这些不是形容词，是<b>能写进合同、能测量、能验收</b>的条件。</p>\n    <p>平台也是一座桥。三套系统都能「调用大模型」：业务直连供应商、统一过网关、区域运行时+共享控制面。<b>功能上它们等价</b>；但加上不同质量要求，形态立刻不同：数据不得出地域→要地域路由和阻断；单供应商故障不能断核心客服→要隔离和切换；两周自助接入→要稳定契约和 SDK；团队只有 6 人→不能引入运维不起的基础设施。</p>\n    <p>所以<b>功能回答「做什么」，质量属性回答「在关键条件下做得多好」</b>，真正改变架构的是后者。用三个问题筛选「架构驱动力」：① 它变化时候选架构会不会明显变？② 它失败时业务/合规损失是否重大？③ 团队对满足它是否高度不确定？至少一个「是」才值得进架构评审。把按钮从蓝改绿不算；「策略 5 分钟内生效且运行时不依赖控制面实时可用」算。</p>\n    <div class=\"key\"><span class=\"tag\">一句话记住</span>「高性能 / 高可用 / 安全可靠」不是验收标准。业务说高可用=客服不能停，SRE 说=SLO+错误预算，研发说=多实例，财务说=别为试验付双倍——同一个词六种理解，必须落成场景。</div>\n    <div class=\"recap\"><b>收束：</b>先列质量属性清单防遗漏，再用三问筛出真正驱动架构的少数因素。</div>\n  </section>\n\n  <section id=\"b\">\n    <h2><span class=\"no\">第 2 步</span>把形容词写成六要素场景，用效用树排优先级</h2>\n    <p>一个可验收的质量场景有六要素：<span class=\"term\">来源</span>(谁触发)、<span class=\"term\">刺激</span>(发生什么)、<span class=\"term\">制品</span>(影响哪部分)、<span class=\"term\">环境</span>(什么条件下)、<span class=\"term\">响应</span>(系统该怎么做)、<span class=\"term\">度量</span>(怎么判达标)。套模板：「当【来源】在【环境】下对【制品】施加【刺激】，系统应当【响应】，并满足【可测量标准】」。</p>\n    <table>\n      <tr><th>场景</th><th>环境</th><th>响应</th><th>度量</th></tr>\n      <tr><td>P-01 平台附加延迟</td><td>稳态 500 QPS</td><td>完成校验并转发</td><td>附加 P95≤50ms、P99≤100ms</td></tr>\n      <tr><td>A-01 单供应商故障</td><td>高峰、备用可用</td><td>隔离并切换符合策略的请求</td><td>30 秒内降级/切换</td></tr>\n      <tr><td>S-01 敏感数据错路由</td><td>含新供应商刚上线</td><td>离开受控边界前阻断+可验证审计</td><td>阻断率 100%、不发请求体</td></tr>\n      <tr><td>M-02 团队自助接入</td><td>标准场景无例外</td><td>按 Golden Path 申请测试上线</td><td>中位≤2 周、平台人工≤4h</td></tr>\n    </table>\n    <p>注意两个坑：<b>只写平均值</b>会隐藏长尾（要看 P95/P99/超时率）；<b>没有故障环境</b>等于只在晴天验收。还要区分「端到端体验」（受供应商影响，定义用户护栏）和「平台附加开销」（团队可控，单独承诺）。</p>\n    <p>场景多了用<span class=\"term2\">效用树</span>排优先级：每个叶子标「业务重要性 × 技术风险」。<b>高重要+高风险</b>的先进入方案比较和 PoC，而不是先做最容易的。可用性还要按业务分级投资：Tier1 核心客服 99.95%、Tier2 内容 99.9%、Tier3 试验尽力而为——统一最高浪费钱，统一最低伤核心。</p>\n    <div class=\"key\"><span class=\"tag\">一句话记住</span>没有环境和度量的场景无法证伪。效用树决定「先保护什么」，不是每项都做到最高。</div>\n    <div class=\"recap\"><b>收束：</b>六要素场景 + 效用树(重要性×风险) + 业务分级 + 区分端到端与平台附加。</div>\n  </section>\n\n  <section id=\"c\">\n    <h2><span class=\"no\">第 3 步</span>三套都可行的候选：先硬约束淘汰，再权衡</h2>\n    <p>错误的比较是「A 明显不合规、B 贵到不可能批、C 是我一开始就想选的」——那是为既定答案补材料。正确做法是摆三套<b>都可能落地</b>的候选：</p>\n    <table>\n      <tr><th>候选</th><th>形态</th><th>得到</th><th>付出</th></tr>\n      <tr><td>A 增量平台化</td><td>复用现有 Gateway 加平台能力</td><td>上线快、认知低、适合 6 人</td><td>中央入口爆炸半径大、易成平台巨石</td></tr>\n      <tr><td>B 联邦运行时</td><td>共享控制面 + 区域/业务运行时</td><td>驻留与故障隔离强、可逐步迁移</td><td>策略分发/版本兼容/运维成本高</td></tr>\n      <tr><td>C 集中运行时</td><td>统一大平台运行时</td><td>体验治理最统一</td><td>6 人半年交付不了、爆炸半径大、退出难</td></tr>\n    </table>\n    <figure>\n      <svg viewBox=\"0 0 760 190\" role=\"img\" aria-label=\"硬约束筛选后再权衡\">\n        <defs><marker id=\"ara2\" markerWidth=\"8\" markerHeight=\"8\" refX=\"6\" refY=\"3\" orient=\"auto\"><path d=\"M0,0 L6,3 L0,6 Z\" fill=\"#A39B8E\"/></marker></defs>\n        <rect x=\"8\" y=\"20\" width=\"150\" height=\"52\" rx=\"10\" fill=\"#ECF1FB\" stroke=\"#C9D8F2\"/><text x=\"83\" y=\"42\" text-anchor=\"middle\" font-size=\"12.5\" font-weight=\"bold\" fill=\"#2F58A8\">三套可行候选</text><text x=\"83\" y=\"60\" text-anchor=\"middle\" font-size=\"11\" fill=\"#7C7166\">A 增量 / B 联邦 / C 集中</text>\n        <rect x=\"200\" y=\"20\" width=\"170\" height=\"52\" rx=\"10\" fill=\"#FBEDE9\" stroke=\"#F0CFC6\"/><text x=\"285\" y=\"42\" text-anchor=\"middle\" font-size=\"12.5\" font-weight=\"bold\" fill=\"#B04A35\">硬约束筛选</text><text x=\"285\" y=\"60\" text-anchor=\"middle\" font-size=\"11\" fill=\"#7C7166\">不合规直接淘汰</text>\n        <rect x=\"412\" y=\"20\" width=\"160\" height=\"52\" rx=\"10\" fill=\"#FBF3E4\" stroke=\"#EDD9B4\"/><text x=\"492\" y=\"42\" text-anchor=\"middle\" font-size=\"12.5\" font-weight=\"bold\" fill=\"#8A5510\">权衡矩阵</text><text x=\"492\" y=\"60\" text-anchor=\"middle\" font-size=\"11\" fill=\"#7C7166\">暴露权重与假设</text>\n        <rect x=\"614\" y=\"20\" width=\"138\" height=\"52\" rx=\"10\" fill=\"#E9F4F2\" stroke=\"#BFE0DB\"/><text x=\"683\" y=\"42\" text-anchor=\"middle\" font-size=\"12.5\" font-weight=\"bold\" fill=\"#1E7268\">选中 + 放弃</text><text x=\"683\" y=\"60\" text-anchor=\"middle\" font-size=\"11\" fill=\"#7C7166\">+ 演进触发条件</text>\n        <line x1=\"158\" y1=\"46\" x2=\"198\" y2=\"46\" stroke=\"#A39B8E\" stroke-width=\"2\" marker-end=\"url(#ara2)\"/>\n        <line x1=\"370\" y1=\"46\" x2=\"410\" y2=\"46\" stroke=\"#A39B8E\" stroke-width=\"2\" marker-end=\"url(#ara2)\"/>\n        <line x1=\"572\" y1=\"46\" x2=\"612\" y2=\"46\" stroke=\"#A39B8E\" stroke-width=\"2\" marker-end=\"url(#ara2)\"/>\n        <rect x=\"8\" y=\"100\" width=\"744\" height=\"48\" rx=\"10\" fill=\"#F4F2EC\" stroke=\"#EADFD3\"/>\n        <text x=\"380\" y=\"120\" text-anchor=\"middle\" font-size=\"12\" fill=\"#5B4A2F\">合规失败不能靠加权补回来；分数接近时，胜负取决于几个高风险场景而非总分</text>\n        <text x=\"380\" y=\"138\" text-anchor=\"middle\" font-size=\"11\" fill=\"#A39B8E\">当前：A 起步验证价值，保留向 B 演进的契约；触发条件没出现不提前付复杂度成本</text>\n        <text x=\"380\" y=\"172\" text-anchor=\"middle\" font-size=\"12\" fill=\"#A39B8E\">区分「现在的承诺 / 未来选择权 / 明确不做」</text>\n      </svg>\n      <figcaption>图 1 · 先硬约束淘汰，再权衡暴露假设，最后写清选中与放弃。</figcaption>\n    </figure>\n    <p><b>先过硬约束</b>：敏感数据指定地域、三个月首价值、6 人团队、不停现有 18 应用、可回退。若法规要求多地域独立处理而 A 只能单点，A 直接淘汰，<b>不能用其他优点加权补回来</b>。剩下的才进权衡矩阵打分。</p>\n    <p>分数不是真理，是<b>暴露假设</b>：为什么交付速度权重 20？为什么 B 可运营性只 3？A 比 B 高 10 分不代表「科学胜出」——分数接近说明决策取决于几个高风险场景。当前合理选择：<b>A 起步快速验证价值，同时保留向 B 演进的契约</b>（管理 API 与运行链路分离、策略版本化、审计用量走事件），并写清演进触发条件（多地域驻留、爆炸半径超 Tier1 SLO、≥3 个稳定运行时…）。触发没出现就不提前付联邦的复杂度成本。</p>\n    <div class=\"key\"><span class=\"tag\">一句话记住</span>硬约束先淘汰，加权矩阵不能补偿合规失败；区分「现在的承诺」「未来选择权」「明确不做」。</div>\n    <div class=\"recap\"><b>收束：</b>三套可行候选 → 硬约束筛选 → 权衡矩阵暴露假设 → 选中+放弃+演进触发条件。</div>\n  </section>\n\n  <section id=\"d\">\n    <h2><span class=\"no\">第 4 步</span>ATAM 走查：敏感点、权衡点、风险、非风险</h2>\n    <p>评审不是给架构盖章，是系统地发现四类东西：<span class=\"term\">敏感点</span>=一个小变化就显著影响质量结果（策略快照 TTL：太短控制面故障时大量拒绝，太长旧策略持续生效）；<span class=\"term2\">权衡点</span>=一个决策同时影响多个质量属性且方向冲突（用量同步入账→即时一致但主链路延迟+故障耦合）；<b>风险</b>=当前证据下某决策可能让重要场景失败（策略分发无版本兼容→旧运行时放行受限请求）；<b>非风险</b>=已有足够证据在指定边界内可接受（中级压测证明同硬件同插件 500 QPS，但新增策略后仍需重验）。</p>\n    <p>走查高重要高风险场景要逐步追问故障条件。以「控制面不可用」为例：运行时每请求同步调控制面吗？→缓存如何签名/版本/过期？→过期后普通请求继续还是全拒、敏感请求是否不同？→吊销如何快速生效（长缓存提高可用却延长吊销窗口）？→恢复后跳版本怎么办（要全量快照不只增量）？走查产出敏感点/权衡点/风险/缓解/待验证，而不是会议纪要。</p>\n    <p>每个高风险项必须选一种处理方式：<b>避免 / 缓解 / 转移 / 接受 / 验证</b>。「已知悉」不是处理；接受风险必须有责任人、边界、期限、复审条件。非风险必须写清适用边界，不能把局部证据无限外推。</p>\n    <div class=\"key\"><span class=\"tag\">一句话记住</span>可信方案不会「没有风险」；它让重要风险更早暴露，并说明谁在什么时候用什么证据处理。隐藏风险才是失败。</div>\n    <div class=\"recap\"><b>收束：</b>轻量 ATAM 工作坊 → 走查高风险场景 → 登记四类发现 → 每项风险有处理+责任人+复审。</div>\n  </section>\n\n  <section id=\"e\">\n    <h2><span class=\"no\">第 5 步</span>留下证据包：C4 视图 + ADR + 小 PoC</h2>\n    <p>大而全的架构图回答不了「谁用、边界在哪、敏感数据经过哪、故障怎么传播」。<span class=\"term\">C4</span> 用不同缩放服务不同读者：<b>Context</b>=系统与用户/外部系统/信任边界；<b>Container</b>=可独立运行或存储的主要单元及数据责任；<b>Component</b>=只深入最高风险容器（这里是 Gateway Runtime）；再补<b>动态视图</b>(故障/策略变更时序)和<b>部署视图</b>(故障域+数据驻留)。每个图元素要能追溯到质量场景和 ADR，否则图会变成历史壁纸。</p>\n    <p><span class=\"term2\">ADR</span> 记录「为什么」而不只是结果：背景、驱动力、≥2 个真实备选、决定、<b>负面后果与主动放弃</b>、证据、迁移回滚、复审退出条件。六个月后别人问「为什么不同步查控制面、TTL 为什么是这个值」，代码和图答不了，ADR 能答。</p>\n    <p><b>PoC 不是迷你生产系统</b>。它只验证一个高影响高不确定假设，例如「本地签名策略快照 vs 每次同步远程查询：能否满足延迟预算、隔离控制面故障、且在传播窗口内保持安全新鲜度」。只建可切换的读取器+可注入延迟/中断的模拟控制面+真实分布数据+分位数报告。若 PoC 证明远程查询已足够且更简单，<b>勇于放弃快照方案</b>——PoC 的目标不是证明架构师正确，是减少错误投资。迁移走「影子双读→分级放量 5/25/50/100→Tier1 前故障演练」，每阶段有停止条件（错误放行>0、P99 超护栏、传播>5min…）。</p>\n    <div class=\"key\"><span class=\"tag\">一句话记住</span>交付的不是一张漂亮全景图，而是一套能被业务/安全/SRE/财务共同质疑、验证、调整的证据包。</div>\n    <div class=\"recap\"><b>收束：</b>C4 多视图 + ADR(含负面后果) + 小 PoC(可证伪) + 影子灰度回滚 + 停止投资条件。</div>\n  </section>\n\n  <section id=\"lab\">\n    <h2><span class=\"no\">动手</span>两场演练：形容词vs场景、权衡矩阵沙盒</h2>\n    <p>演练一看「高可用」这句形容词和一条六要素场景的差别。演练二拖动权重滑块、切换硬约束，亲手算三套候选的加权分，体会「硬约束先淘汰、分数只是暴露假设」。</p>\n    <div class=\"lab\">\n      <div class=\"lab-head\"><b>演练一 · 两种写法</b><span class=\"hint\">点按钮切换</span></div>\n      <div class=\"controls\"><div class=\"seg\" id=\"e1\"><button data-k=\"adj\" class=\"on\">❌ 形容词</button><button data-k=\"scn\">✅ 六要素场景</button></div></div>\n      <div class=\"lab-body\"><div><pre id=\"e1code\" style=\"margin:0;\"></pre></div><div class=\"logcat\"><div class=\"logcat-head\"><span>说明</span><span>live</span></div><div class=\"logcat-body\" id=\"e1log\"></div></div></div>\n      <div class=\"lab-foot\"><span class=\"hint\">同一个「高可用」，两种命运</span></div>\n    </div>\n    <div class=\"lab\">\n      <div class=\"lab-head\"><b>演练二 · 权衡矩阵沙盒</b><span class=\"hint\">拖权重、切硬约束</span></div>\n      <div class=\"controls\">\n        <div class=\"ctl\"><label>交付速度权重</label><input type=\"range\" id=\"g1wd\" min=\"0\" max=\"30\" value=\"20\"><span class=\"val\" id=\"g1wdV\">20</span></div>\n        <div class=\"ctl\"><label>数据驻留权重</label><input type=\"range\" id=\"g1wr\" min=\"0\" max=\"30\" value=\"20\"><span class=\"val\" id=\"g1wrV\">20</span></div>\n        <div class=\"ctl\"><label>可运营性权重</label><input type=\"range\" id=\"g1wo\" min=\"0\" max=\"30\" value=\"15\"><span class=\"val\" id=\"g1woV\">15</span></div>\n        <div class=\"ctl\"><label><input type=\"checkbox\" id=\"g1hard\"> 驻留=硬约束(多地域)</label></div>\n      </div>\n      <div class=\"lab-body\"><div><div class=\"stats\" id=\"g1stats\"></div><div class=\"chips\" id=\"g1chips\"></div><div class=\"key\" id=\"g1hint\"></div></div><div class=\"logcat\"><div class=\"logcat-head\"><span>推导过程</span><span>live</span></div><div class=\"logcat-body\" id=\"g1log\"></div></div></div>\n      <div class=\"lab-foot\"><span class=\"hint\">固定其余权重：隔离15 体验15 可逆10 成本5；评分1~5</span></div>\n    </div>\n    <div class=\"key\"><span class=\"tag\">看懂这两场演练</span>形容词无法验收；权衡沙盒里把驻留设成硬约束后 A/C 直接淘汰——合规失败不能靠加权补回来。分数接近时，真正决定胜负的是那几个高风险场景。</div>\n  </section>\n\n  <section id=\"quiz\">\n    <h2><span class=\"no\">自测</span>六个问题</h2>\n    <div class=\"card\" id=\"quiz-box\"></div>\n    <p id=\"quiz-done\" style=\"display:none;font-weight:700;color:#1E7268;\">全对。你已经能指着权衡矩阵说清「为什么选它、放弃了什么、哪个风险没验证」。下一课划领域与团队边界。</p>\n  </section>\n\n  <section id=\"map\">\n    <h2><span class=\"no\">回顾</span>速查表</h2>\n    <table>\n      <tr><th>概念</th><th>大白话</th><th>要点</th></tr>\n      <tr><td>架构驱动力</td><td>真正改变架构形态的少数因素</td><td>三问筛选，不是技术名词清单</td></tr>\n      <tr><td>质量场景六要素</td><td>来源/刺激/制品/环境/响应/度量</td><td>缺环境和度量无法验收</td></tr>\n      <tr><td>效用树</td><td>给质量排优先级</td><td>重要性×风险，高+高先验证</td></tr>\n      <tr><td>硬约束筛选</td><td>不合规直接淘汰</td><td>加权不能补合规失败</td></tr>\n      <tr><td>敏感点/权衡点</td><td>一改牵动全局/按下葫芦浮起瓢</td><td>评审重点追问对象</td></tr>\n      <tr><td>非风险</td><td>有证据在边界内可接受</td><td>必须写适用边界</td></tr>\n      <tr><td>C4</td><td>Context/Container/Component+动态/部署</td><td>Component 只深入最高风险容器</td></tr>\n      <tr><td>ADR / PoC</td><td>决定与理由 / 花小钱验关键假设</td><td>ADR 记负面后果；PoC 可证伪</td></tr>\n    </table>\n    <div class=\"note\"><span class=\"tag\">说明</span>本页为教学整理，权衡评分与权重为课程示例（用于暴露假设，非客观真理）；沙盒为模拟计算，非真实压测。口径以高级 README 与第二篇底稿为准。</div>\n  </section>\n\n  <section id=\"refs\">\n    <h2><span class=\"no\">依据</span>参考链接</h2>\n    <div class=\"card refs\">\n      <h3 style=\"margin-top:0;\">原始底稿（本仓库）</h3>\n      <ul>\n        <li>《AI 后端开发：Java 实战》高级工程师 · 第二篇-架构驱动设计与质量属性 <span class=\"src\">— 本课重写底稿</span></li>\n        <li>高级工程师/README.md <span class=\"src\">— Rubric 与课程边界权威口径</span></li>\n      </ul>\n      <h3>方法与规范</h3>\n      <ul>\n        <li><a href=\"https://c4model.com/\" target=\"_blank\" rel=\"noopener\">The C4 Model</a> <span class=\"src\">— Context/Container/Component 视图的官方定义</span></li>\n        <li><a href=\"https://adr.github.io/\" target=\"_blank\" rel=\"noopener\">ADR · Architecture Decision Records</a> <span class=\"src\">— 决策记录模板与生命周期</span></li>\n        <li><a href=\"https://sre.google/sre-book/service-level-objectives/\" target=\"_blank\" rel=\"noopener\">Google SRE · SLO</a> <span class=\"src\">— 把可用性写成可运营指标</span></li>\n      </ul>\n      <h3>下一课要用</h3>\n      <ul>\n        <li><a href=\"https://c4model.com/\" target=\"_blank\" rel=\"noopener\">C4 Container 视图</a> <span class=\"src\">— A3 将据领域边界合并/拆分候选容器</span></li>\n      </ul>\n    </div>\n    \n    \n  </section>", "toc": [{"id":"a","title":"驱动力"},{"id":"b","title":"六要素场景"},{"id":"c","title":"候选与权衡"},{"id":"d","title":"ATAM 走查"},{"id":"e","title":"C4/ADR/PoC"},{"id":"lab","title":"两场演练"},{"id":"quiz","title":"本课自测"},{"id":"map","title":"速查表"},{"id":"refs","title":"参考链接"}], "scripts": "(function(){\n  var ADJ=\"// ❌ 形容词：无法验收\\n「系统要高可用、高性能、安全可靠」\\n业务理解=客服不能停\\nSRE 理解=SLO+错误预算\\n研发理解=多部署几个实例\\n财务理解=别为试验付双倍成本\";\n  var SCN=\"// ✅ 六要素场景：可验收\\n来源: 主模型供应商\\n刺激: 连续超时/错误率超阈值\\n制品: 核心客服推理链路\\n环境: 业务高峰, 备用供应商可用\\n响应: 隔离故障商, 切换符合策略的请求\\n度量: 30s 内降级/切换, 失败不超错误预算\";\n  function show(k){document.getElementById(\"e1code\").textContent=(k===\"adj\"?ADJ:SCN);document.getElementById(\"e1log\").innerHTML=\"<div><span class=\\\"\"+(k===\"adj\"?\"err\":\"ok\")+\"\\\">\"+(k===\"adj\"?\"六种理解吵不完，没法判断架构够不够\":\"带条件+响应+度量，能拿去压测/演练证伪\")+\"</span></div><div><span class=\\\"c\\\">// \"+(k===\"adj\"?\"评审变成各自表述\":\"评审围绕同一可测量标准\")+\"</span></div>\";}\n  document.querySelectorAll(\"#e1 button\").forEach(function(b){b.addEventListener(\"click\",function(){document.querySelectorAll(\"#e1 button\").forEach(function(x){x.classList.remove(\"on\");});b.classList.add(\"on\");show(b.getAttribute(\"data-k\"));});});\n  show(\"adj\");\n})();\n\n// 演练二：权衡矩阵沙盒\n(function(){\n  // 评分 1~5：[交付,驻留,隔离,体验,运营,可逆,成本]\n  var R={A:[5,3,3,4,5,5,5],B:[3,5,5,4,3,4,3],C:[2,3,3,5,2,2,2]};\n  var FIXED=[15,15,10,5]; // 隔离,体验,可逆,成本\n  function val(id){return parseInt(document.getElementById(id).value,10);}\n  function score(w,r){var num=0,den=0;for(var i=0;i<7;i++){num+=w[i]*r[i];den+=w[i];}return den?num/den*20:0;}\n  function calc(){\n    var wd=val('g1wd'),wr=val('g1wr'),wo=val('g1wo');\n    document.getElementById('g1wdV').textContent=wd;\n    document.getElementById('g1wrV').textContent=wr;\n    document.getElementById('g1woV').textContent=wo;\n    var w=[wd,wr,FIXED[0],FIXED[1],wo,FIXED[2],FIXED[3]];\n    var hard=document.getElementById('g1hard').checked;\n    var elig={A:!hard,B:true,C:!hard}; // 驻留硬约束(多地域)时 A/C 不满足\n    var s={A:score(w,R.A),B:score(w,R.B),C:score(w,R.C)};\n    var win=null;['A','B','C'].forEach(function(k){if(elig[k]&&(win===null||s[k]>s[win]))win=k;});\n    document.getElementById('g1stats').innerHTML=['A','B','C'].map(function(k){\n      var cls=!elig[k]?'bad':(k===win?'good':'');\n      return '<div class=\"stat-box '+cls+'\"><b>'+(!elig[k]?'淘汰':s[k].toFixed(0))+'</b><small>方案'+k+'</small></div>';\n    }).join('');\n    document.getElementById('g1chips').innerHTML=\n      '<span class=\"chip '+(hard?'bad':'on')+'\">驻留 '+(hard?'硬约束：A/C 淘汰':'评分项')+'</span>'+\n      '<span class=\"chip on\">当前领先：方案'+win+'</span>'+\n      '<span class=\"chip '+(Math.abs(s.A-s.B)<8?'bad':'on')+'\">A/B 分差 '+(Math.abs(s.A-s.B)<8?'接近→看高风险场景':'拉开')+'</span>';\n    document.getElementById('g1hint').innerHTML='<span class=\"tag\">'+(hard?'硬约束':'权衡')+'</span>'+\n      (hard?'驻留成为硬约束后，A(单点)/C(需多地域实例) 不满足直接淘汰，只剩 B——合规失败不能加权补回。':'权重只是暴露假设：交付权重调高利好 A，驻留/隔离权重调高利好 B。分数接近时别宣称「科学胜出」。');\n    document.getElementById('g1log').innerHTML=[\n      '<div><span class=\"api\">权重 = [交付'+wd+', 驻留'+wr+', 隔离15, 体验15, 运营'+wo+', 可逆10, 成本5]</span></div>',\n      '<div><span class=\"'+(hard?'err':'ok')+'\">硬约束筛选 → '+(hard?'A/C 淘汰, 仅 B 可行':'三套均进入评分')+'</span></div>',\n      ['A','B','C'].map(function(k){return '<div><span class=\"'+(elig[k]?'ok':'err')+'\">方案'+k+' 加权 = '+s[k].toFixed(1)+(elig[k]?'':' (淘汰)')+'</span></div>';}).join(''),\n      '<div><span class=\"c\">// 领先 = 方案'+win+'；分数用于暴露权重假设，不是客观真理</span></div>'\n    ].join('');\n  }\n  ['g1wd','g1wr','g1wo'].forEach(function(id){document.getElementById(id).addEventListener('input',calc);});\n  document.getElementById('g1hard').addEventListener('change',calc);\n  calc();\n})();\n\nconst QUIZ=[{\"q\":\"1. 真正改变架构形态的通常是？\",\"opts\":[[\"质量属性与硬约束\",true,\"对。功能等价时质量要求决定形态。\"],[\"功能清单\",false,\"三套方案功能等价。\"],[\"按钮颜色\",false,\"那不是驱动力。\"]]},{\"q\":\"2. 质量场景缺哪两要素就无法验收？\",\"opts\":[[\"环境与度量\",true,\"对。什么时候+怎么测。\"],[\"来源与刺激\",false,\"那描述触发。\"],[\"制品与响应\",false,\"那描述对象和行为。\"]]},{\"q\":\"3. 硬约束不满足的候选方案应？\",\"opts\":[[\"直接淘汰，不能加权补回\",true,\"对。合规是过滤不是评分项。\"],[\"扣几分继续比\",false,\"合规失败不可补偿。\"],[\"看其他优点决定\",false,\"那是陪跑式比较。\"]]},{\"q\":\"4. 敏感点指？\",\"opts\":[[\"小变化就显著影响质量结果的参数\",true,\"对。如策略快照 TTL。\"],[\"一个决策影响多个质量属性\",false,\"那是权衡点。\"],[\"已有证据可接受的决策\",false,\"那是非风险。\"]]},{\"q\":\"5. 权衡点指？\",\"opts\":[[\"一个决策同时影响多个质量属性且方向冲突\",true,\"对。如同步入账=一致但延迟。\"],[\"只影响一个属性的参数\",false,\"那是敏感点。\"],[\"没有风险的决策\",false,\"那是非风险。\"]]},{\"q\":\"6. PoC 的正确目的是？\",\"opts\":[[\"验证最高影响最高不确定的假设\",true,\"对。可证伪，不是迷你生产系统。\"],[\"搭完整微服务证明代码能跑\",false,\"那是迷你生产系统。\"],[\"证明架构师选得对\",false,\"PoC 也可能推翻原方案。\"]]}];" },
    "backend|java|划边界：领域、系统与团队": { "body": "<p class=\"lead\">A2 选了架构形态，但图上的框还只是「候选运行责任」。这一课回答：哪些业务规则是同一种语言、哪些数据谁拥有、哪些边界要落到代码/部署/值班表上——以及什么时候根本不该拆服务。</p>\n  \n  <div class=\"journey\">\n    <div class=\"j-step\"><span class=\"n\">1</span><span class=\"t\">分科室</span><span class=\"s\">限界上下文</span></div>\n    <div class=\"j-step\"><span class=\"n\">2</span><span class=\"t\">定权威</span><span class=\"s\">数据谁说了算</span></div>\n    <div class=\"j-step\"><span class=\"n\">3</span><span class=\"t\">拆不拆</span><span class=\"s\">单体vs微服务</span></div>\n    <div class=\"j-step\"><span class=\"n\">4</span><span class=\"t\">动手</span><span class=\"s\">两场演练</span></div>\n    <div class=\"j-step\"><span class=\"n\">5</span><span class=\"t\">自测</span><span class=\"s\">六个问题</span></div>\n  </div>\n\n  <section id=\"a\">\n    <h2><span class=\"no\">第 1 步</span>医院里「病人」是三个东西：限界上下文</h2>\n    <p>先讲个故事。走进医院，「病人」在挂号处是「一个待分配的号」，在检验科是「一份样本编号」，在住院部是「一张床和一套病历」。同一个词，三套含义三套规则。硬让全院共用一个「病人」对象，结果谁都改不动、谁都不满意。</p>\n    <p>星河的「用量」也一样：在网关是<b>实时计数</b>，在计量是<b>不可变事实</b>，在计费是<b>按某费率版本算出的金额</b>。塞进同一张表，等于让挂号处替住院部写病历。<span class=\"term\">限界上下文</span>就是「科室」：科室内用一套<span class=\"term2\">统一语言</span>，跨科室靠「会诊单」（显式契约/映射），不靠强行统一词汇。</p>\n    <figure>\n      <svg viewBox=\"0 0 760 200\" role=\"img\" aria-label=\"同一个词在三个上下文里是三件事\">\n        <defs><marker id=\"ara3\" markerWidth=\"8\" markerHeight=\"8\" refX=\"6\" refY=\"3\" orient=\"auto\"><path d=\"M0,0 L6,3 L0,6 Z\" fill=\"#A39B8E\"/></marker></defs>\n        <rect x=\"8\" y=\"30\" width=\"220\" height=\"70\" rx=\"10\" fill=\"#ECF1FB\" stroke=\"#C9D8F2\"/><text x=\"118\" y=\"56\" text-anchor=\"middle\" font-size=\"12.5\" font-weight=\"bold\" fill=\"#2F58A8\">网关上下文</text><text x=\"118\" y=\"76\" text-anchor=\"middle\" font-size=\"11\" fill=\"#7C7166\">用量 = 实时计数/配额</text><text x=\"118\" y=\"92\" text-anchor=\"middle\" font-size=\"11\" fill=\"#7C7166\">语言：准入、限流</text>\n        <rect x=\"270\" y=\"30\" width=\"220\" height=\"70\" rx=\"10\" fill=\"#E9F4F2\" stroke=\"#BFE0DB\"/><text x=\"380\" y=\"56\" text-anchor=\"middle\" font-size=\"12.5\" font-weight=\"bold\" fill=\"#1E7268\">计量上下文</text><text x=\"380\" y=\"76\" text-anchor=\"middle\" font-size=\"11\" fill=\"#7C7166\">用量 = 不可变事实</text><text x=\"380\" y=\"92\" text-anchor=\"middle\" font-size=\"11\" fill=\"#7C7166\">语言：事件、幂等</text>\n        <rect x=\"532\" y=\"30\" width=\"220\" height=\"70\" rx=\"10\" fill=\"#FBF3E4\" stroke=\"#EDD9B4\"/><text x=\"642\" y=\"56\" text-anchor=\"middle\" font-size=\"12.5\" font-weight=\"bold\" fill=\"#8A5510\">计费上下文</text><text x=\"642\" y=\"76\" text-anchor=\"middle\" font-size=\"11\" fill=\"#7C7166\">用量 = 费率版本×事实</text><text x=\"642\" y=\"92\" text-anchor=\"middle\" font-size=\"11\" fill=\"#7C7166\">语言：账单、对账</text>\n        <line x1=\"228\" y1=\"65\" x2=\"268\" y2=\"65\" stroke=\"#A39B8E\" stroke-width=\"2\" marker-end=\"url(#ara3)\"/>\n        <line x1=\"490\" y1=\"65\" x2=\"530\" y2=\"65\" stroke=\"#A39B8E\" stroke-width=\"2\" marker-end=\"url(#ara3)\"/>\n        <text x=\"248\" y=\"52\" text-anchor=\"middle\" font-size=\"10\" fill=\"#A39B8E\">用量事件</text>\n        <text x=\"510\" y=\"52\" text-anchor=\"middle\" font-size=\"10\" fill=\"#A39B8E\">事实+费率</text>\n        <rect x=\"8\" y=\"124\" width=\"744\" height=\"48\" rx=\"10\" fill=\"#F4F2EC\" stroke=\"#EADFD3\"/>\n        <text x=\"380\" y=\"144\" text-anchor=\"middle\" font-size=\"12\" fill=\"#5B4A2F\">跨上下文靠显式契约（事件/命令/查询）+ 防腐层翻译，不共享内部表、不强行统一词汇</text>\n        <text x=\"380\" y=\"162\" text-anchor=\"middle\" font-size=\"11\" fill=\"#A39B8E\">Container ≠ 限界上下文 ≠ 微服务 ≠ 团队；数据库表 ≠ 领域对象</text>\n      </svg>\n      <figcaption>图 1 · 同一词三含义：科室内统一语言，跨科室靠会诊单。</figcaption>\n    </figure>\n    <div class=\"key\"><span class=\"tag\">一句话记住</span>先划清「谁说了算」，再决定拆不拆服务。只改代码边界，半年后会被组织形状拉回去。</div>\n    <div class=\"recap\"><b>收束：</b>按「业务规则是否同一种语言、是否同一变化原因」聚上下文，跨上下文显式映射。</div>\n  </section>\n\n  <section id=\"b\">\n    <h2><span class=\"no\">第 2 步</span>核心/支撑/通用域，与每类数据的唯一权威</h2>\n    <p>不是所有能力都值得同样投入。分三类：<span class=\"term\">核心域</span>=差异化竞争力（星河的模型路由与成本治理、统一策略）；<span class=\"term2\">支撑域</span>=业务必需但非差异（租户权益、计量账本）；<b>通用域</b>=大家都一样可买可复用（身份认证、观测、消息）。核心域自研深耕，通用域优先采购/复用——呼应 A1 的复用/采购/自研选择。</p>\n    <p>比分类更重要的是<b>数据所有权</b>：每类核心数据只能有一个「业务责任方」，其他上下文通过契约使用，不直接写别人的表。星河候选权威：</p>\n    <table>\n      <tr><th>数据</th><th>唯一权威上下文</th><th>别人怎么用</th><th>不可破坏的规则</th></tr>\n      <tr><td>租户订阅/权益</td><td>Identity/权益</td><td>查询权益快照</td><td>无有效权益不得准入</td></tr>\n      <tr><td>价格费率</td><td>计费</td><td>读版本化费率</td><td>账单必须可追溯费率版本</td></tr>\n      <tr><td>AI 用量事实</td><td>计量</td><td>订阅用量事件</td><td>同一事实不得重复计费</td></tr>\n      <tr><td>最终财务账单</td><td>计费/对账</td><td>读账单+对账差异</td><td>接收记录/供应商账单/账本三方对账</td></tr>\n    </table>\n    <p>「修改模型权限经常同时影响网关、门户、账单、应用」就是<b>边界画错</b>的信号：一个变化原因扯动四个上下文，说明它们其实共享了不该共享的语言/数据。用「共同变更频率」和「事故时谁等谁」来诊断，而不是凭直觉画框。</p>\n    <div class=\"key\"><span class=\"tag\">一句话记住</span>共享表是边界的敌人。每类数据一个权威，其余靠契约+防腐层；一个变化扯动多处=边界待重划。</div>\n    <div class=\"recap\"><b>收束：</b>核心/支撑/通用分类定投入；数据唯一权威定责任；共同变更/事故等待定边界对错。</div>\n  </section>\n\n  <section id=\"c\">\n    <h2><span class=\"no\">第 3 步</span>拆不拆：模块化单体 often 赢，Conway 与认知负载</h2>\n    <p>限界上下文≠微服务。六人团队把每个上下文拆成独立服务，会立刻背上部署、观测、值班、分布式一致性的成本。<b>模块化单体</b>（一个进程内模块边界清楚、独立可测）常常是更优起点：边界先在代码里立住，等变化频率/团队规模/独立发布需求真的出现再拆。</p>\n    <table>\n      <tr><th>形态</th><th>适合</th><th>代价</th></tr>\n      <tr><td>模块化单体</td><td>团队小、边界仍在验证、变化耦合高</td><td>独立发布/扩缩受限</td></tr>\n      <tr><td>微服务</td><td>边界稳定、多团队独立发布/扩缩需求强</td><td>分布式一致性+运维+认知成本</td></tr>\n      <tr><td>Serverless</td><td>事件驱动、流量稀疏、想免运维</td><td>冷启动/锁定/长连接受限</td></tr>\n    </table>\n    <p><span class=\"term\">Conway 定律</span>：系统结构会镜像组织沟通结构。若平台 6 人既开发又值班、长期被接入工单打断，而业务 60 人想自助试验——组织形状会把你「拆好的服务」拉回「中央瓶颈」。所以要用 <span class=\"term2\">Team Topologies</span> 思路：平台团队做「赋能/平台型」提供 Golden Path，业务团队做「流对齐型」自助交付，而不是平台替业务写配置。<b>认知负载</b>是硬约束：一个团队能理解并运营的边界数量有限，超了就合并或减责。</p>\n    <div class=\"key\"><span class=\"tag\">一句话记住</span>先让边界在代码里立住（模块化单体），等真实压力出现再拆；同时改团队交互方式，否则 Conway 把你拉回去。</div>\n    <div class=\"recap\"><b>收束：</b>按变化频率/团队数/独立发布需求/认知负载决定形态；组织与架构共同演进。</div>\n  </section>\n\n  <section id=\"d\">\n    <h2><span class=\"no\">第 4 步</span>上下文映射：上下游、防腐层与契约类型</h2>\n    <p>划好上下文要标关系：谁上游谁下游、谁遵谁的契约。常见模式：<b>客户-供应商</b>(下游提需求上游排期)、<b>遵奉者</b>(下游完全遵上游模型)、<b>防腐层 ACL</b>(下游翻译上游模型保护自己语言)、<b>发布语言</b>(上游提供稳定公开契约如版本化事件)、<b>共享内核</b>(慎用,小范围共享模型)。星河计量→计费用「发布语言」(版本化用量事件)，计费内部用 ACL 翻译供应商账单格式。</p>\n    <p>契约分三种交互：<b>命令</b>(要求对方做某事,需确认)、<b>查询</b>(读对方权威数据,不写)、<b>事件</b>(告知已发生事实,订阅方自治)。跨上下文优先事件+查询,少用同步命令链(耦合故障)。每条契约写清: schema 版本、兼容策略、幂等键、对账方式——这些是 A4 数据一致性的输入。</p>\n    <div class=\"key\"><span class=\"tag\">一句话记住</span>边界之间靠「发布语言+防腐层」协作，不靠共享表；契约类型决定耦合与故障传播。</div>\n    <div class=\"recap\"><b>收束：</b>标上下游+映射模式+命令/查询/事件契约+版本与对账，交给 A4 做一致性。</div>\n  </section>\n\n  <section id=\"e\">\n    <h2><span class=\"no\">第 5 步</span>Strangler 可回退迁移：边界是假设，要验证</h2>\n    <p>本篇的领域划分是<b>教学候选假设</b>，不是调查后的最终事实。正式决策要靠：领域专家访谈、Event Storming、代码共同变更数据、发布协调/事故记录、团队认知负载。边界画错很正常，关键是<b>可回退地演进</b>。</p>\n    <p>用 <span class=\"term\">Strangler Fig</span>（绞杀者模式）：新能力先在旧系统旁长出来，逐步把流量/责任切过去，旧系统最后被「绞杀」移除；每步可回退。不要大爆炸重写。迁移顺序按「价值高+耦合低」先切，共享表先拆权威再拆代码。团队边界同步演进：先改值班表/接口人，再改部署，否则 Conway 反扑。</p>\n    <div class=\"key\"><span class=\"tag\">一句话记住</span>边界假设→小步 Strangler 验证→可回退；代码、数据、团队三条边界一起动，只动一条会被拉回。</div>\n    <div class=\"recap\"><b>收束：</b>候选边界+证据来源+Strangler 分步+三线共同演进+回退条件。</div>\n  </section>\n\n  <section id=\"lab\">\n    <h2><span class=\"no\">动手</span>两场演练：共享表vs边界、拆不拆沙盒</h2>\n    <p>演练一看「用量塞一张共享表」和「三上下文各持权威+事件协作」的差别。演练二拖动滑块（共同变更比例/团队数/独立发布需求/认知负载），看系统建议保持模块化单体还是拆分。</p>\n    <div class=\"lab\">\n      <div class=\"lab-head\"><b>演练一 · 两种数据组织</b><span class=\"hint\">点按钮切换</span></div>\n      <div class=\"controls\"><div class=\"seg\" id=\"e1\"><button data-k=\"share\" class=\"on\">❌ 共享一张表</button><button data-k=\"bound\">✅ 边界+事件</button></div></div>\n      <div class=\"lab-body\"><div><pre id=\"e1code\" style=\"margin:0;\"></pre></div><div class=\"logcat\"><div class=\"logcat-head\"><span>说明</span><span>live</span></div><div class=\"logcat-body\" id=\"e1log\"></div></div></div>\n      <div class=\"lab-foot\"><span class=\"hint\">同一个「用量」，两种命运</span></div>\n    </div>\n    <div class=\"lab\">\n      <div class=\"lab-head\"><b>演练二 · 拆不拆沙盒</b><span class=\"hint\">拖滑块看建议</span></div>\n      <div class=\"controls\">\n        <div class=\"ctl\"><label>共同变更比例%</label><input type=\"range\" id=\"g1cc\" min=\"0\" max=\"100\" value=\"70\"><span class=\"val\" id=\"g1ccV\">70</span></div>\n        <div class=\"ctl\"><label>独立发布需求</label><input type=\"range\" id=\"g1rel\" min=\"0\" max=\"10\" value=\"2\"><span class=\"val\" id=\"g1relV\">2</span></div>\n        <div class=\"ctl\"><label>团队数</label><input type=\"range\" id=\"g1team\" min=\"1\" max=\"10\" value=\"1\"><span class=\"val\" id=\"g1teamV\">1</span></div>\n        <div class=\"ctl\"><label>单团队认知负载</label><input type=\"range\" id=\"g1cog\" min=\"0\" max=\"10\" value=\"8\"><span class=\"val\" id=\"g1cogV\">8</span></div>\n      </div>\n      <div class=\"lab-body\"><div><div class=\"stats\" id=\"g1stats\"></div><div class=\"chips\" id=\"g1chips\"></div><div class=\"key\" id=\"g1hint\"></div></div><div class=\"logcat\"><div class=\"logcat-head\"><span>推导过程</span><span>live</span></div><div class=\"logcat-body\" id=\"g1log\"></div></div></div>\n      <div class=\"lab-foot\"><span class=\"hint\">共同变更高=该合并；独立发布/团队多=该拆；认知超载=减责或合并</span></div>\n    </div>\n    <div class=\"key\"><span class=\"tag\">看懂这两场演练</span>共享表让一个变化扯动全身；拆不拆不是信仰题——共同变更高时拆了反而更耦合，认知超载时拆了没人运营得起。</div>\n  </section>\n\n  <section id=\"quiz\">\n    <h2><span class=\"no\">自测</span>六个问题</h2>\n    <div class=\"card\" id=\"quiz-box\"></div>\n    <p id=\"quiz-done\" style=\"display:none;font-weight:700;color:#1E7268;\">全对。你已经会先问「谁说了算」再问「拆不拆」。下一课处理跨边界的数据一致性。</p>\n  </section>\n\n  <section id=\"map\">\n    <h2><span class=\"no\">回顾</span>速查表</h2>\n    <table>\n      <tr><th>概念</th><th>大白话</th><th>要点</th></tr>\n      <tr><td>限界上下文</td><td>医院科室</td><td>科室内统一语言，跨科室靠会诊单</td></tr>\n      <tr><td>核心/支撑/通用域</td><td>竞争力/必需/可买</td><td>决定自研vs采购投入</td></tr>\n      <tr><td>数据唯一权威</td><td>谁说了算</td><td>别人靠契约用，不写别人表</td></tr>\n      <tr><td>模块化单体</td><td>一个进程内边界清楚</td><td>小团队常优起点</td></tr>\n      <tr><td>Conway 定律</td><td>架构镜像组织</td><td>不改团队交互会被拉回</td></tr>\n      <tr><td>认知负载</td><td>团队能运营多少边界</td><td>硬约束，超了合并/减责</td></tr>\n      <tr><td>防腐层/发布语言</td><td>翻译官/公开契约</td><td>跨上下文不共享内部模型</td></tr>\n      <tr><td>Strangler</td><td>旁路新长逐步绞杀旧</td><td>可回退，不大爆炸重写</td></tr>\n    </table>\n    <div class=\"note\"><span class=\"tag\">说明</span>本页为教学整理，领域划分为候选假设（需访谈/Event Storming/共同变更数据验证）；沙盒为启发式模拟，非真实决策工具。口径以高级 README 与第三篇底稿为准。</div>\n  </section>\n\n  <section id=\"refs\">\n    <h2><span class=\"no\">依据</span>参考链接</h2>\n    <div class=\"card refs\">\n      <h3 style=\"margin-top:0;\">原始底稿（本仓库）</h3>\n      <ul>\n        <li>《AI 后端开发：Java 实战》高级工程师 · 第三篇-领域建模与系统团队边界 <span class=\"src\">— 本课重写底稿</span></li>\n        <li>高级工程师/README.md <span class=\"src\">— 责任模型与课程边界</span></li>\n      </ul>\n      <h3>方法与规范</h3>\n      <ul>\n        <li><a href=\"https://martinfowler.com/bliki/BoundedContext.html\" target=\"_blank\" rel=\"noopener\">Martin Fowler · Bounded Context</a> <span class=\"src\">— 限界上下文与统一语言</span></li>\n        <li><a href=\"https://martinfowler.com/bliki/StranglerFigApplication.html\" target=\"_blank\" rel=\"noopener\">Martin Fowler · Strangler Fig</a> <span class=\"src\">— 可回退渐进迁移</span></li>\n        <li><a href=\"https://martinfowler.com/bliki/ConwaysLaw.html\" target=\"_blank\" rel=\"noopener\">Martin Fowler · Conway's Law</a> <span class=\"src\">— 组织与架构同构</span></li>\n      </ul>\n      <h3>下一课要用</h3>\n      <ul>\n        <li><a href=\"https://microservices.io/patterns/data/transactional-outbox.html\" target=\"_blank\" rel=\"noopener\">Transactional Outbox</a> <span class=\"src\">— A4 跨上下文可靠事件的基础</span></li>\n      </ul>\n    </div>\n    \n    \n  </section>", "toc": [{"id":"a","title":"限界上下文"},{"id":"b","title":"域与数据权威"},{"id":"c","title":"拆不拆"},{"id":"d","title":"上下文映射"},{"id":"e","title":"Strangler"},{"id":"lab","title":"两场演练"},{"id":"quiz","title":"本课自测"},{"id":"map","title":"速查表"},{"id":"refs","title":"参考链接"}], "scripts": "(function(){\n  var SHARE=\"// ❌ 共享一张 usage 表\\n网关写 usage(count++)\\n计量读 usage 当事实\\n计费读 usage 算金额\\n→ 改费率/改计数/改准入 互相牵动\\n→ 一个变化扯动四个上下文\";\n  var BOUND=\"// ✅ 三上下文各持权威\\n网关: 实时配额(自己的表)\\n计量: 不可变用量事实(Outbox 发事件)\\n计费: 订阅事件 × 版本化费率 → 账单\\n→ 跨边界靠事件+查询, 不共享表\\n→ 各改各的, 契约版本兼容\";\n  function show(k){document.getElementById(\"e1code\").textContent=(k===\"share\"?SHARE:BOUND);document.getElementById(\"e1log\").innerHTML=\"<div><span class=\\\"\"+(k===\"share\"?\"err\":\"ok\")+\"\\\">\"+(k===\"share\"?\"挂号处替住院部写病历：谁都改不动\":\"科室各管各的，跨科室靠会诊单\")+\"</span></div><div><span class=\\\"c\\\">// \"+(k===\"share\"?\"共同变更比例高=边界画错\":\"权威清晰+事件协作=可独立演进\")+\"</span></div>\";}\n  document.querySelectorAll(\"#e1 button\").forEach(function(b){b.addEventListener(\"click\",function(){document.querySelectorAll(\"#e1 button\").forEach(function(x){x.classList.remove(\"on\");});b.classList.add(\"on\");show(b.getAttribute(\"data-k\"));});});\n  show(\"share\");\n})();\n\n// 演练二：拆不拆沙盒\n(function(){\n  function val(id){return parseInt(document.getElementById(id).value,10);}\n  function calc(){\n    var cc=val('g1cc'), rel=val('g1rel'), team=val('g1team'), cog=val('g1cog');\n    ['cc','rel','team','cog'].forEach(function(k){document.getElementById('g1'+k+'V').textContent=val('g1'+k);});\n    // 拆分倾向 = 独立发布 + 团队数 - 共同变更耦合\n    var splitScore = rel + team*1.5 - cc/10;\n    var overload = cog>=8;\n    var rec = splitScore>=8 ? '拆微服务' : '保持模块化单体';\n    if(overload && rec==='拆微服务') rec='先减责/合并, 再谈拆';\n    document.getElementById('g1stats').innerHTML=\n      '<div class=\"stat-box\"><b>'+cc+'%</b><small>共同变更</small></div>'+\n      '<div class=\"stat-box\"><b>'+splitScore.toFixed(1)+'</b><small>拆分倾向</small></div>'+\n      '<div class=\"stat-box '+(overload?'bad':'good')+'\"><b>'+cog+'</b><small>认知负载</small></div>';\n    document.getElementById('g1chips').innerHTML=\n      '<span class=\"chip '+(cc>=60?'bad':'on')+'\">耦合 '+(cc>=60?'高→倾向合并':'低')+'</span>'+\n      '<span class=\"chip '+(overload?'bad':'on')+'\">认知 '+(overload?'超载':'可运营')+'</span>'+\n      '<span class=\"chip on\">建议：'+rec+'</span>';\n    document.getElementById('g1hint').innerHTML='<span class=\"tag\">推导</span>'+\n      '共同变更 '+cc+'% 越高越该合（拆了仍一起改）；独立发布 '+rel+' + 团队 '+team+' 越高越该拆；认知 '+cog+(overload?' 已超载，拆了没人运营得起，先减责。':' 尚可。');\n    document.getElementById('g1log').innerHTML=[\n      '<div><span class=\"api\">拆分倾向 = 发布'+rel+' + 团队'+team+'×1.5 - 耦合'+cc+'/10 = '+splitScore.toFixed(1)+'</span></div>',\n      '<div><span class=\"'+(cc>=60?'warn':'ok')+'\">共同变更 '+cc+'% → '+(cc>=60?'边界耦合高, 拆分收益低':'边界较独立')+'</span></div>',\n      '<div><span class=\"'+(overload?'err':'ok')+'\">认知负载 '+cog+' → '+(overload?'超载, 先减责/合并':'可运营')+'</span></div>',\n      '<div><span class=\"c\">// 建议 = '+rec+'（启发式, 非教条）</span></div>'\n    ].join('');\n  }\n  ['g1cc','g1rel','g1team','g1cog'].forEach(function(id){document.getElementById(id).addEventListener('input',calc);});\n  calc();\n})();\n\nconst QUIZ=[{\"q\":\"1. 限界上下文最贴切的比喻是？\",\"opts\":[[\"医院科室：科室内统一语言\",true,\"对。跨科室靠会诊单。\"],[\"全公司一个统一对象\",false,\"那会让谁都改不动。\"],[\"一张共享大表\",false,\"共享表是边界敌人。\"]]},{\"q\":\"2. 「用量」在网关/计量/计费分别是？\",\"opts\":[[\"实时计数/不可变事实/费率×事实\",true,\"对。三含义三权威。\"],[\"同一个对象三处引用\",false,\"那是共享表反模式。\"],[\"三份完全相同拷贝\",false,\"语义不同不是拷贝。\"]]},{\"q\":\"3. 每类核心数据应有几个业务权威？\",\"opts\":[[\"一个\",true,\"对。其余靠契约使用。\"],[\"越多越冗余越安全\",false,\"多权威=不一致根源。\"],[\"无所谓\",false,\"所有权是边界核心。\"]]},{\"q\":\"4. 六人团队、边界仍在验证时通常优选？\",\"opts\":[[\"模块化单体\",true,\"对。边界先在代码立住。\"],[\"立刻全拆微服务\",false,\"运维/认知成本超载。\"],[\"Serverless 全量\",false,\"长连接/锁定受限。\"]]},{\"q\":\"5. Conway 定律提醒我们？\",\"opts\":[[\"不改团队交互, 架构会被组织拉回\",true,\"对。三线边界一起演进。\"],[\"架构与组织无关\",false,\"恰恰同构。\"],[\"拆服务就能解耦组织\",false,\"组织不改会反扑。\"]]},{\"q\":\"6. Strangler Fig 迁移的关键是？\",\"opts\":[[\"旁路新长、逐步切流、可回退\",true,\"对。不大爆炸重写。\"],[\"一次性重写替换\",false,\"风险集中爆发。\"],[\"只改代码不改团队\",false,\"会被 Conway 拉回。\"]]}];" },
    "backend|java|数据一致性与 Saga/Outbox": { "body": "<p class=\"lead\">A3 划清了数据谁说了算，这一课回答跨上下文协作时的一致性：先写业务不变量，按「能损失多少、允许多久差、多久必须追平」选档位，再用 Outbox/Saga/补偿落地，并拿出对账与恢复证据。</p>\n  \n  <div class=\"journey\">\n    <div class=\"j-step\"><span class=\"n\">1</span><span class=\"t\">划红线</span><span class=\"s\">业务不变量</span></div>\n    <div class=\"j-step\"><span class=\"n\">2</span><span class=\"t\">选档位</span><span class=\"s\">一致性光谱</span></div>\n    <div class=\"j-step\"><span class=\"n\">3</span><span class=\"t\">兜可靠</span><span class=\"s\">Outbox/幂等</span></div>\n    <div class=\"j-step\"><span class=\"n\">4</span><span class=\"t\">动手</span><span class=\"s\">两场演练</span></div>\n    <div class=\"j-step\"><span class=\"n\">5</span><span class=\"t\">自测</span><span class=\"s\">六个问题</span></div>\n  </div>\n\n  <section id=\"a\">\n    <h2><span class=\"no\">第 1 步</span>连锁集团对账：现金当场点清，日报次日核</h2>\n    <p>先讲个故事。连锁集团总部要算全国利润，门店各有收银账。要求「所有账本每一秒都一模一样」不现实——网络会断、门店会离线、日结要时间。务实做法是先划线：<b>哪些数字一秒都不能错</b>（已收款不能重复入账、授权不能超发），<b>哪些允许晚点对齐</b>（昨日汇总明早追平），以及<b>多久必须证明已追平</b>。</p>\n    <p>星河把订阅/授权/用量/费率/账单分给不同上下文后就是这道题。<span class=\"term\">强一致不是美德，无边界的最终一致是事故</span>。一致性是一段光谱，档位由「业务能损失多少」倒推，而不是由「用了什么中间件」决定。</p>\n    <figure>\n      <svg viewBox=\"0 0 760 180\" role=\"img\" aria-label=\"一致性光谱\">\n        <defs><marker id=\"ara4\" markerWidth=\"8\" markerHeight=\"8\" refX=\"6\" refY=\"3\" orient=\"auto\"><path d=\"M0,0 L6,3 L0,6 Z\" fill=\"#A39B8E\"/></marker></defs>\n        <rect x=\"8\" y=\"30\" width=\"170\" height=\"64\" rx=\"10\" fill=\"#FBEDE9\" stroke=\"#F0CFC6\"/><text x=\"93\" y=\"56\" text-anchor=\"middle\" font-size=\"12.5\" font-weight=\"bold\" fill=\"#B04A35\">强一致/本地事务</text><text x=\"93\" y=\"76\" text-anchor=\"middle\" font-size=\"11\" fill=\"#7C7166\">准入·权益·配额扣减</text>\n        <rect x=\"200\" y=\"30\" width=\"180\" height=\"64\" rx=\"10\" fill=\"#FBF3E4\" stroke=\"#EDD9B4\"/><text x=\"290\" y=\"56\" text-anchor=\"middle\" font-size=\"12.5\" font-weight=\"bold\" fill=\"#8A5510\">Outbox+最终一致</text><text x=\"290\" y=\"76\" text-anchor=\"middle\" font-size=\"11\" fill=\"#7C7166\">用量事实→计量→账单</text>\n        <rect x=\"402\" y=\"30\" width=\"170\" height=\"64\" rx=\"10\" fill=\"#E9F4F2\" stroke=\"#BFE0DB\"/><text x=\"487\" y=\"56\" text-anchor=\"middle\" font-size=\"12.5\" font-weight=\"bold\" fill=\"#1E7268\">Saga/补偿</text><text x=\"487\" y=\"76\" text-anchor=\"middle\" font-size=\"11\" fill=\"#7C7166\">跨上下文长流程</text>\n        <rect x=\"594\" y=\"30\" width=\"158\" height=\"64\" rx=\"10\" fill=\"#ECF1FB\" stroke=\"#C9D8F2\"/><text x=\"673\" y=\"56\" text-anchor=\"middle\" font-size=\"12.5\" font-weight=\"bold\" fill=\"#2F58A8\">读模型/数据产品</text><text x=\"673\" y=\"76\" text-anchor=\"middle\" font-size=\"11\" fill=\"#7C7166\">报表·分析(可滞后)</text>\n        <line x1=\"178\" y1=\"62\" x2=\"198\" y2=\"62\" stroke=\"#A39B8E\" stroke-width=\"2\" marker-end=\"url(#ara4)\"/>\n        <line x1=\"380\" y1=\"62\" x2=\"400\" y2=\"62\" stroke=\"#A39B8E\" stroke-width=\"2\" marker-end=\"url(#ara4)\"/>\n        <line x1=\"572\" y1=\"62\" x2=\"592\" y2=\"62\" stroke=\"#A39B8E\" stroke-width=\"2\" marker-end=\"url(#ara4)\"/>\n        <rect x=\"8\" y=\"116\" width=\"744\" height=\"44\" rx=\"10\" fill=\"#F4F2EC\" stroke=\"#EADFD3\"/>\n        <text x=\"380\" y=\"134\" text-anchor=\"middle\" font-size=\"12\" fill=\"#5B4A2F\">每档都要回答：哪笔不能差 · 允许多久差 · 凭什么证明补上了（对账+恢复证据）</text>\n        <text x=\"380\" y=\"150\" text-anchor=\"middle\" font-size=\"11\" fill=\"#A39B8E\">把 Offering/Grant/Admission/UsageFact/RatedUsage/Ledger/Invoice 塞一张 usage 表=一致性事故起点</text>\n      </svg>\n      <figcaption>图 1 · 一致性光谱：档位由业务损失倒推，每档配恢复证据。</figcaption>\n    </figure>\n    <div class=\"key\"><span class=\"tag\">一句话记住</span>先写「绝不能短暂违反」的不变量，再给可滞后的数据定可见时限+恢复时限；没有恢复证据的最终一致=相信消息迟早会到=事故。</div>\n    <div class=\"recap\"><b>收束：</b>不变量→一致性分级→每级配可见/恢复时限与对账证据。</div>\n  </section>\n\n  <section id=\"b\">\n    <h2><span class=\"no\">第 2 步</span>业务不变量与一致性分级表</h2>\n    <p>把 A3 的所有权变成<b>可执行不变量</b>：无有效权益不得准入；同一用量事实不得重复计费；账单必须可追溯费率版本；授权不得超发。这些是「一秒都不能错」的红线，用本地事务/原子操作守。其余允许短暂差异但要定时限：</p>\n    <table>\n      <tr><th>数据/规则</th><th>一致性档</th><th>可见时限</th><th>恢复/对账</th></tr>\n      <tr><td>准入/权益/配额扣减</td><td>强(本地原子)</td><td>即时</td><td>Redis 投影可重建,非账本</td></tr>\n      <tr><td>用量事实→计量子账本</td><td>Outbox 最终</td><td>秒~分</td><td>幂等去重+日终对账</td></tr>\n      <tr><td>定价→最终账单</td><td>最终+封账</td><td>账期</td><td>三方对账(接收/供应商/账本)</td></tr>\n      <tr><td>报表/分析读模型</td><td>可滞后</td><td>小时/天</td><td>重建投影+水位标记</td></tr>\n    </table>\n    <p>区分七个概念防合并事故：<span class=\"term\">Offering</span>(可申请什么)、<span class=\"term\">Grant</span>(已授权什么)、<span class=\"term\">Admission</span>(这次允不允许)、<span class=\"term\">UsageFact</span>(实际消耗)、<span class=\"term\">RatedUsage</span>(按哪费率值多少)、<span class=\"term\">Ledger</span>(可追溯分录)、<span class=\"term\">Invoice</span>(正式账单)。把它们塞一张表是大量一致性问题的起点。</p>\n    <div class=\"key\"><span class=\"tag\">一句话记住</span>红线用强一致守，其余给「能差多久+多久追平」；概念不合并，权威不共享。</div>\n    <div class=\"recap\"><b>收束：</b>不变量清单+分级表(档位/可见/恢复)+七概念分离。</div>\n  </section>\n\n  <section id=\"c\">\n    <h2><span class=\"no\">第 3 步</span>Outbox/Inbox 兜可靠，幂等/顺序兜重复乱序</h2>\n    <p>跨上下文不能靠「写完表再发 MQ」两步各自成功——中间崩了就丢事件。<span class=\"term\">Outbox</span>：业务写入和「待发消息」在<b>同一个本地事务</b>里落库，再由投递器可靠发出；消费侧 <span class=\"term2\">Inbox</span>/幂等键去重。这样「本地事实」和「对外告知」原子绑定。</p>\n    <p>消息会<b>重复、乱序、部分失败</b>，所以消费者必须幂等（用业务幂等键而非消息 ID）、能处理乱序（用聚合版本/发生时间）、失败可重试+死信+人工介入。Redis 配额是<b>可重建投影</b>不是最终账本——崩了从账本重建，别把投影当真相。</p>\n    <div class=\"key\"><span class=\"tag\">一句话记住</span>Outbox 保证「写了就一定告知」，幂等保证「告知多次只算一次」；投影可重建，账本才是真相。</div>\n    <div class=\"recap\"><b>收束：</b>Outbox 同事务落库+可靠投递；Inbox 幂等+版本防乱序；死信+人工兜底。</div>\n  </section>\n\n  <section id=\"d\">\n    <h2><span class=\"no\">第 4 步</span>长流程用 Saga/补偿，别把远程调用塞长事务</h2>\n    <p>跨多个上下文的长流程（激活套餐→发授权→准入→计量→定价→封账）不能用一个分布式大事务锁住所有人。用 <span class=\"term\">Saga</span>：一串本地事务，每步配<b>补偿</b>动作，失败时反向补偿回滚语义。编排式(中央协调)vs 协同式(事件驱动)各有取舍：编排易观察但中央耦合，协同松耦合但难追踪。</p>\n    <p><span class=\"term2\">TCC</span>(Try-Confirm-Cancel) 适合需要「预留资源」的强语义场景（如配额预留），但要求三方接口都实现，成本高；多数业务用 Saga+补偿+对账足够。<b>失败语义</b>要写清：每步失败对业务意味着什么、补偿是否幂等、补偿失败怎么办（人工介入+对账）。「最终一致性更高级」是错的——是<b>把不同业务问题放进不同一致性机制</b>。</p>\n    <div class=\"key\"><span class=\"tag\">一句话记住</span>长流程=Saga 本地事务链+幂等补偿；TCC 留给需预留的强语义；补偿失败要有兜底，不是假装不会发生。</div>\n    <div class=\"recap\"><b>收束：</b>Saga 编排/协同取舍+补偿幂等+失败语义矩阵+人工兜底。</div>\n  </section>\n\n  <section id=\"e\">\n    <h2><span class=\"no\">第 5 步</span>对账与恢复证据，双轨迁移可切权可回滚</h2>\n    <p>最终一致必须<b>可证明恢复</b>：消息中断 20 分钟后，积压要在约定时限（如 2 小时）内追平；日终对账使「Gateway 接收记录 / 供应商账单 / 租户账本」三方差异低于阈值；重复事件不得重复计费。给出<b>恢复证据</b>（积压水位、追平时间、对账差异报告），而不是相信「消息迟早会到」。</p>\n    <p>数据迁移走<b>双轨</b>：新旧并行写/读→回填历史→对账一致→切权（权威转移）→旧轨退役；每步可回滚。跨域查询不破坏写边界：用读模型/数据产品（CQRS 投影、搜索索引、湖仓）而非直连别人表；是否分片/搜索/湖仓要用证据（规模/查询模式/成本）决定，不默认上。</p>\n    <div class=\"key\"><span class=\"tag\">一句话记住</span>没有对账和恢复证据的最终一致是事故；迁移双轨+回填+对账+切权+回滚，权威转移才算完成。</div>\n    <div class=\"recap\"><b>收束：</b>恢复时限+三方对账+证据报告；双轨迁移可切权可回滚；读模型不破坏写边界。</div>\n  </section>\n\n  <section id=\"lab\">\n    <h2><span class=\"no\">动手</span>两场演练：全强一致vs分级、积压恢复沙盒</h2>\n    <p>演练一看「所有数据都强一致」和「按业务分级」的差别。演练二模拟消息中断：拖中断时长/产生速率/消费速率，看积压能否在 2 小时护栏内追平，并切换幂等开关看重复计费是否被挡。</p>\n    <div class=\"lab\">\n      <div class=\"lab-head\"><b>演练一 · 两种一致性观</b><span class=\"hint\">点按钮切换</span></div>\n      <div class=\"controls\"><div class=\"seg\" id=\"e1\"><button data-k=\"all\" class=\"on\">❌ 全都强一致</button><button data-k=\"tier\">✅ 按业务分级</button></div></div>\n      <div class=\"lab-body\"><div><pre id=\"e1code\" style=\"margin:0;\"></pre></div><div class=\"logcat\"><div class=\"logcat-head\"><span>说明</span><span>live</span></div><div class=\"logcat-body\" id=\"e1log\"></div></div></div>\n      <div class=\"lab-foot\"><span class=\"hint\">同一个平台，两种命运</span></div>\n    </div>\n    <div class=\"lab\">\n      <div class=\"lab-head\"><b>演练二 · 积压恢复沙盒</b><span class=\"hint\">拖滑块+切幂等</span></div>\n      <div class=\"controls\">\n        <div class=\"ctl\"><label>中断时长(min)</label><input type=\"range\" id=\"g1out\" min=\"0\" max=\"60\" value=\"20\"><span class=\"val\" id=\"g1outV\">20</span></div>\n        <div class=\"ctl\"><label>产生(事件/min)</label><input type=\"range\" id=\"g1prod\" min=\"10\" max=\"200\" value=\"60\"><span class=\"val\" id=\"g1prodV\">60</span></div>\n        <div class=\"ctl\"><label>消费(事件/min)</label><input type=\"range\" id=\"g1cons\" min=\"20\" max=\"400\" value=\"120\"><span class=\"val\" id=\"g1consV\">120</span></div>\n        <div class=\"ctl\"><label><input type=\"checkbox\" id=\"g1idem\" checked> 消费幂等</label></div>\n      </div>\n      <div class=\"lab-body\"><div><div class=\"stats\" id=\"g1stats\"></div><div class=\"chips\" id=\"g1chips\"></div><div class=\"key\" id=\"g1hint\"></div></div><div class=\"logcat\"><div class=\"logcat-head\"><span>推导过程</span><span>live</span></div><div class=\"logcat-body\" id=\"g1log\"></div></div></div>\n      <div class=\"lab-foot\"><span class=\"hint\">护栏：积压 2 小时内追平；重复事件不得重复计费</span></div>\n    </div>\n    <div class=\"key\"><span class=\"tag\">看懂这两场演练</span>全强一致会把远程调用锁进长事务、一断全断；分级+Outbox+幂等+对账才能「断了也能证明追平」。消费速率≤产生速率时积压永远追不平——这就是恢复证据的意义。</div>\n  </section>\n\n  <section id=\"quiz\">\n    <h2><span class=\"no\">自测</span>六个问题</h2>\n    <div class=\"card\" id=\"quiz-box\"></div>\n    <p id=\"quiz-done\" style=\"display:none;font-weight:700;color:#1E7268;\">全对。你已经会问「哪笔不能差、能差多久、怎么证明补回」。下一课把契约治理成平台自助接入。</p>\n  </section>\n\n  <section id=\"map\">\n    <h2><span class=\"no\">回顾</span>速查表</h2>\n    <table>\n      <tr><th>概念</th><th>大白话</th><th>要点</th></tr>\n      <tr><td>业务不变量</td><td>一秒都不能错的红线</td><td>不重复计费/不超发/可追溯费率</td></tr>\n      <tr><td>一致性光谱</td><td>现金当场点清,日报次日核</td><td>档位由业务损失倒推</td></tr>\n      <tr><td>Outbox/Inbox</td><td>写了就一定告知/告知多次只算一次</td><td>同事务落库+幂等去重</td></tr>\n      <tr><td>投影 vs 账本</td><td>可重建缓存 vs 真相</td><td>Redis 配额是投影</td></tr>\n      <tr><td>Saga/补偿</td><td>本地事务链+反向回滚</td><td>补偿幂等+失败兜底</td></tr>\n      <tr><td>TCC</td><td>预留-确认-取消</td><td>留给需预留的强语义</td></tr>\n      <tr><td>对账/恢复证据</td><td>凭什么证明追平了</td><td>三方对账+积压水位+时限</td></tr>\n      <tr><td>双轨迁移</td><td>并行→回填→对账→切权→退役</td><td>每步可回滚</td></tr>\n    </table>\n    <div class=\"note\"><span class=\"tag\">说明</span>本页为教学整理，时限/速率为课程场景假设；沙盒为模拟推导，非真实压测。口径以高级 README 与第四篇底稿为准。</div>\n  </section>\n\n  <section id=\"refs\">\n    <h2><span class=\"no\">依据</span>参考链接</h2>\n    <div class=\"card refs\">\n      <h3 style=\"margin-top:0;\">原始底稿（本仓库）</h3>\n      <ul>\n        <li>《AI 后端开发：Java 实战》高级工程师 · 第四篇-分布式数据与一致性决策 <span class=\"src\">— 本课重写底稿</span></li>\n        <li>高级工程师/README.md <span class=\"src\">— 责任模型与课程边界</span></li>\n      </ul>\n      <h3>方法与规范</h3>\n      <ul>\n        <li><a href=\"https://microservices.io/patterns/data/transactional-outbox.html\" target=\"_blank\" rel=\"noopener\">Transactional Outbox</a> <span class=\"src\">— 本地写+可靠发事件</span></li>\n        <li><a href=\"https://microservices.io/patterns/data/saga.html\" target=\"_blank\" rel=\"noopener\">Saga Pattern</a> <span class=\"src\">— 长流程本地事务链+补偿</span></li>\n        <li><a href=\"https://docs.spring.io/spring-amqp/reference/\" target=\"_blank\" rel=\"noopener\">Spring AMQP</a> <span class=\"src\">— 可靠投递/确认/死信的工程实现</span></li>\n      </ul>\n      <h3>下一课要用</h3>\n      <ul>\n        <li><a href=\"https://microservices.io/patterns/data/transactional-outbox.html\" target=\"_blank\" rel=\"noopener\">Outbox 事件契约</a> <span class=\"src\">— A5 将把事件 schema/版本治理成平台契约</span></li>\n      </ul>\n    </div>\n    \n    \n  </section>", "toc": [{"id":"a","title":"一致性光谱"},{"id":"b","title":"不变量分级"},{"id":"c","title":"Outbox/幂等"},{"id":"d","title":"Saga/补偿"},{"id":"e","title":"对账与迁移"},{"id":"lab","title":"两场演练"},{"id":"quiz","title":"本课自测"},{"id":"map","title":"速查表"},{"id":"refs","title":"参考链接"}], "scripts": "(function(){\n  var ALL=\"// ❌ 全都强一致\\n把 订阅/授权/准入/用量/定价/账单\\n塞进一个分布式大事务\\n→ 远程模型调用锁进长事务\\n→ 任一依赖慢/断, 全链路阻塞\\n→ 报表也要即时一致, 成本爆炸\";\n  var TIER=\"// ✅ 按业务分级\\n准入/权益/配额: 本地原子(强)\\n用量事实: Outbox 最终一致+幂等\\n账单: 账期封账+三方对账\\n报表: 读模型可滞后+水位\\n→ 红线强守, 其余给可见/恢复时限\";\n  function show(k){document.getElementById(\"e1code\").textContent=(k===\"all\"?ALL:TIER);document.getElementById(\"e1log\").innerHTML=\"<div><span class=\\\"\"+(k===\"all\"?\"err\":\"ok\")+\"\\\">\"+(k===\"all\"?\"一断全断, 且为低价值数据付强一致成本\":\"红线强守, 可滞后数据带恢复证据\")+\"</span></div><div><span class=\\\"c\\\">// \"+(k===\"all\"?\"强一致不是美德\":\"无边界最终一致是事故, 有证据才是工程\")+\"</span></div>\";}\n  document.querySelectorAll(\"#e1 button\").forEach(function(b){b.addEventListener(\"click\",function(){document.querySelectorAll(\"#e1 button\").forEach(function(x){x.classList.remove(\"on\");});b.classList.add(\"on\");show(b.getAttribute(\"data-k\"));});});\n  show(\"all\");\n})();\n\n// 演练二：积压恢复沙盒\n(function(){\n  function val(id){return parseInt(document.getElementById(id).value,10);}\n  function calc(){\n    var out=val('g1out'), prod=val('g1prod'), cons=val('g1cons');\n    ['out','prod','cons'].forEach(function(k){document.getElementById('g1'+k+'V').textContent=val('g1'+k);});\n    var idem=document.getElementById('g1idem').checked;\n    var backlog=out*prod;                 // 中断期间积压\n    var net=cons-prod;                    // 恢复期净消费\n    var recover = net>0 ? backlog/net : Infinity;\n    var okR = recover<=120;\n    var dup = idem?0:Math.round(backlog*0.05); // 无幂等时约5%重复计费\n    document.getElementById('g1stats').innerHTML=\n      '<div class=\"stat-box\"><b>'+backlog.toLocaleString()+'</b><small>积压事件</small></div>'+\n      '<div class=\"stat-box '+(okR?'good':'bad')+'\"><b>'+(isFinite(recover)?recover.toFixed(0):'∞')+'</b><small>追平(min)</small></div>'+\n      '<div class=\"stat-box '+(dup===0?'good':'bad')+'\"><b>'+dup+'</b><small>重复计费</small></div>';\n    document.getElementById('g1chips').innerHTML=\n      '<span class=\"chip '+(okR?'on':'bad')+'\">恢复 '+(okR?'≤2h 达标':'>2h 超护栏')+'</span>'+\n      '<span class=\"chip '+(idem?'on':'bad')+'\">幂等 '+(idem?'开:重复=0':'关:重复计费!')+'</span>'+\n      (net<=0?'<span class=\"chip bad\">消费≤产生: 永远追不平</span>':'');\n    document.getElementById('g1hint').innerHTML='<span class=\"tag\">'+(net<=0?'陷阱':'推导')+'</span>'+\n      (net<=0?'消费速率 '+cons+' ≤ 产生 '+prod+'，积压只增不减，永远追不平——必须扩消费或限产生。':'积压 '+backlog+' ÷ 净消费 '+net+' = '+recover.toFixed(0)+' min；'+(okR?'在 2h 护栏内。':'超 2h 护栏, 需扩消费/缩中断/限流。'));\n    document.getElementById('g1log').innerHTML=[\n      '<div><span class=\"api\">积压 = 中断'+out+'min × 产生'+prod+' = '+backlog.toLocaleString()+'</span></div>',\n      '<div><span class=\"'+(net>0?'ok':'err')+'\">净消费 = '+cons+' - '+prod+' = '+net+'/min</span></div>',\n      '<div><span class=\"'+(okR?'ok':'warn')+'\">追平 = '+backlog+' ÷ '+net+' = '+(isFinite(recover)?recover.toFixed(0)+'min':'∞')+'</span></div>',\n      '<div><span class=\"'+(idem?'ok':'err')+'\">幂等 '+(idem?'开 → 重复计费 0':'关 → 重复计费 '+dup)+'</span></div>',\n      '<div><span class=\"c\">// 恢复证据 = 积压水位+追平时间+对账差异, 不是「消息迟早会到」</span></div>'\n    ].join('');\n  }\n  ['g1out','g1prod','g1cons'].forEach(function(id){document.getElementById(id).addEventListener('input',calc);});\n  document.getElementById('g1idem').addEventListener('change',calc);\n  calc();\n})();\n\nconst QUIZ=[{\"q\":\"1. 一致性档位应由什么倒推？\",\"opts\":[[\"业务能损失多少+可见/恢复时限\",true,\"对。不是由中间件决定。\"],[\"用了什么中间件\",false,\"那是实现不是决策。\"],[\"越strong越好\",false,\"强一致不是美德。\"]]},{\"q\":\"2. 「同一用量事实不得重复计费」属于？\",\"opts\":[[\"业务不变量(红线,强一致守)\",true,\"对。一秒都不能错。\"],[\"可滞后的报表数据\",false,\"那是读模型。\"],[\"偏好\",false,\"那是硬不变量。\"]]},{\"q\":\"3. Outbox 解决什么？\",\"opts\":[[\"本地写入与消息发布的原子绑定\",true,\"对。同事务落库再可靠投递。\"],[\"跨服务分布式大事务\",false,\"那是 Saga/2PC 范畴。\"],[\"提高查询速度\",false,\"无关。\"]]},{\"q\":\"4. Redis 配额投影崩了应？\",\"opts\":[[\"从账本重建, 投影非真相\",true,\"对。账本才是权威。\"],[\"当作最终账本接受丢失\",false,\"投影可重建非账本。\"],[\"停止所有服务\",false,\"重建即可。\"]]},{\"q\":\"5. 跨上下文长流程通常用？\",\"opts\":[[\"Saga 本地事务链+幂等补偿\",true,\"对。不锁分布式大事务。\"],[\"一个分布式大事务\",false,\"远程调用塞长事务=耦合故障。\"],[\"不用任何机制\",false,\"会部分失败不一致。\"]]},{\"q\":\"6. 最终一致必须配什么才不是事故？\",\"opts\":[[\"对账+恢复证据(时限/水位/差异)\",true,\"对。证明追平了。\"],[\"相信消息迟早会到\",false,\"那是事故起点。\"],[\"更多中间件\",false,\"证据不是组件。\"]]}];" },
    "backend|java|平台契约与自助接入": { "body": "<p class=\"lead\">A4 定了局部契约语义，这一课把它提升为平台治理：把平台当用户产品运营，用 SDK/模板/目录铺 Golden Path，用自动门禁+限时例外代替口头规范，契约变更是一次有迁移路径的产品迁移。</p>\n  \n  <div class=\"journey\">\n    <div class=\"j-step\"><span class=\"n\">1</span><span class=\"t\">当产品</span><span class=\"s\">不是救火队</span></div>\n    <div class=\"j-step\"><span class=\"n\">2</span><span class=\"t\">写契约</span><span class=\"s\">可执行+兼容</span></div>\n    <div class=\"j-step\"><span class=\"n\">3</span><span class=\"t\">铺路径</span><span class=\"s\">Golden Path</span></div>\n    <div class=\"j-step\"><span class=\"n\">4</span><span class=\"t\">动手</span><span class=\"s\">两场演练</span></div>\n    <div class=\"j-step\"><span class=\"n\">5</span><span class=\"t\">自测</span><span class=\"s\">六个问题</span></div>\n  </div>\n\n  <section id=\"a\">\n    <h2><span class=\"no\">第 1 步</span>港口值钱的是标准集装箱，不是吊机</h2>\n    <p>先讲个故事。港口真正值钱的不是吊机，是「标准集装箱」：尺寸、锁扣、报关单、航线时刻都定死，船公司/货代/卡车各干各的，不用每批货找港务局开协调会。若每批货都要专人量尺寸、临时批条子，港口再大也是瓶颈。</p>\n    <p>星河 60 研发、18 应用团队，若每个接入都要平台手把手，那不是平台是<b>救火队</b>（每周 25 个工单、接入中位 6 周而实际编码不足 5 天）。平台要当<b>产品</b>做：服务目录让人自己找到能力，SDK/模板让人自己接上，契约+自动门禁替代口头规范，弃用能力给迁移路径和截止时间。<b>衡量成功看接入等待时间，不是上线了几个工具</b>。</p>\n    <div class=\"key\"><span class=\"tag\">一句话记住</span>平台成功的标志是「没人需要来找平台团队」；契约变更是一次产品迁移，不是一封邮件。</div>\n    <div class=\"recap\"><b>收束：</b>平台=产品；用户=业务团队/Agent；度量=等待时间/采纳率/工单逃逸率。</div>\n  </section>\n\n  <section id=\"b\">\n    <h2><span class=\"no\">第 2 步</span>契约是可执行承诺：Owner、语义、兼容、弃用</h2>\n    <p>「Wiki + Java DTO + 数据库字段 + 消息示例各自当文档」=没有契约。最近两次字段改名让旧消费者<b>静默丢失用量维度</b>，就是契约缺失的事故。可执行契约四件套：<span class=\"term\">Owner</span>(谁负责)、<span class=\"term\">业务语义</span>(字段/事件到底意味什么)、<span class=\"term\">兼容策略</span>(加字段可选/改语义=破坏)、<span class=\"term\">弃用规则</span>(水位+截止时间+迁移路径)。</p>\n    <table>\n      <tr><th>契约类型</th><th>载体</th><th>兼容检查</th></tr>\n      <tr><td>同步 API</td><td>OpenAPI + 示例</td><td>契约测试+消费者驱动</td></tr>\n      <tr><td>异步事件</td><td>AsyncAPI + Schema Registry</td><td>schema 兼容( backward/forward )</td></tr>\n      <tr><td>数据/读模型</td><td>Schema + 版本</td><td>迁移兼容窗口+水位</td></tr>\n    </table>\n    <p>关键：<b>破坏性变更在合并前被自动阻断</b>，不依赖评审者记忆。知道「谁在消费」靠消费者/依赖目录，而不是群聊询问。Tier1 契约 100% 有 Owner+消费者+兼容策略+弃用规则。</p>\n    <div class=\"key\"><span class=\"tag\">一句话记住</span>契约=可执行承诺；改尺寸的人负责让所有船还装得上；破坏变更门禁阻断，弃用给迁移路径。</div>\n    <div class=\"recap\"><b>收束：</b>Owner+语义+兼容+弃用四件套；OpenAPI/AsyncAPI/Schema 载体；合并前自动阻断破坏。</div>\n    <figure>\n      <svg viewBox=\"0 0 760 180\" role=\"img\" aria-label=\"契约门禁与自助接入闭环\">\n        <defs><marker id=\"ara5\" markerWidth=\"8\" markerHeight=\"8\" refX=\"6\" refY=\"3\" orient=\"auto\"><path d=\"M0,0 L6,3 L0,6 Z\" fill=\"#A39B8E\"/></marker></defs>\n        <rect x=\"8\" y=\"26\" width=\"170\" height=\"56\" rx=\"10\" fill=\"#ECF1FB\" stroke=\"#C9D8F2\"/><text x=\"93\" y=\"48\" text-anchor=\"middle\" font-size=\"12\" font-weight=\"bold\" fill=\"#2F58A8\">可执行契约</text><text x=\"93\" y=\"66\" text-anchor=\"middle\" font-size=\"11\" fill=\"#7C7166\">Owner+语义+兼容+弃用</text>\n        <rect x=\"200\" y=\"26\" width=\"170\" height=\"56\" rx=\"10\" fill=\"#FBEDE9\" stroke=\"#F0CFC6\"/><text x=\"285\" y=\"48\" text-anchor=\"middle\" font-size=\"12\" font-weight=\"bold\" fill=\"#B04A35\">CI 自动门禁</text><text x=\"285\" y=\"66\" text-anchor=\"middle\" font-size=\"11\" fill=\"#7C7166\">破坏变更合并前阻断</text>\n        <rect x=\"392\" y=\"26\" width=\"170\" height=\"56\" rx=\"10\" fill=\"#E9F4F2\" stroke=\"#BFE0DB\"/><text x=\"477\" y=\"48\" text-anchor=\"middle\" font-size=\"12\" font-weight=\"bold\" fill=\"#1E7268\">Golden Path</text><text x=\"477\" y=\"66\" text-anchor=\"middle\" font-size=\"11\" fill=\"#7C7166\">SDK/模板/目录自助接入</text>\n        <rect x=\"584\" y=\"26\" width=\"168\" height=\"56\" rx=\"10\" fill=\"#FBF3E4\" stroke=\"#EDD9B4\"/><text x=\"668\" y=\"48\" text-anchor=\"middle\" font-size=\"12\" font-weight=\"bold\" fill=\"#8A5510\">限时例外</text><text x=\"668\" y=\"66\" text-anchor=\"middle\" font-size=\"11\" fill=\"#7C7166\">到期自动复审/收回</text>\n        <line x1=\"178\" y1=\"54\" x2=\"198\" y2=\"54\" stroke=\"#A39B8E\" stroke-width=\"2\" marker-end=\"url(#ara5)\"/>\n        <line x1=\"370\" y1=\"54\" x2=\"390\" y2=\"54\" stroke=\"#A39B8E\" stroke-width=\"2\" marker-end=\"url(#ara5)\"/>\n        <line x1=\"562\" y1=\"54\" x2=\"582\" y2=\"54\" stroke=\"#A39B8E\" stroke-width=\"2\" marker-end=\"url(#ara5)\"/>\n        <rect x=\"8\" y=\"104\" width=\"744\" height=\"48\" rx=\"10\" fill=\"#F4F2EC\" stroke=\"#EADFD3\"/>\n        <text x=\"380\" y=\"124\" text-anchor=\"middle\" font-size=\"12\" fill=\"#5B4A2F\">规范靠门禁不靠记忆；例外靠限时不靠永久豁免；默认合规是平台内置</text>\n        <text x=\"380\" y=\"142\" text-anchor=\"middle\" font-size=\"11\" fill=\"#A39B8E\">价值度量=首调时间/接入周期/逃逸率/采纳率, 不是工具计数</text>\n      </svg>\n      <figcaption>图 1 · 契约→门禁→Golden Path→限时例外的治理闭环。</figcaption>\n    </figure>\n  </section>\n\n  <section id=\"c\">\n    <h2><span class=\"no\">第 3 步</span>Golden Path：SDK/模板/目录降低外在认知负载</h2>\n    <p><span class=\"term\">Golden Path</span>=港口的标准集装箱+固定航线：一条被支持、默认合规、可观测的推荐接入路径。业务团队走它就能自助完成申请→测试→上线，不用理解平台内部。三个复制粘贴、重试/超时/错误语义各不同的 SDK 是反模式——收敛成<b>一个受支持 SDK</b>+模板+脚手架。</p>\n    <p>认知负载分<b>内在</b>(业务本身复杂度,应保留)和<b>外在</b>(平台强加的接入/配置/排错复杂度,应消除)。Golden Path 消除外在负载：目录能发现能力、模板自带身份/审计/观测/重试、文档按任务组织。目标：新团队获权到测试首调 P50&lt;4h、标准生产接入≤2 周、等待平台人工&lt;1 天、80% 新服务用受支持模板。</p>\n    <div class=\"key\"><span class=\"tag\">一句话记住</span>Golden Path 消除外在认知负载；平台提供路径而非垄断——标准走推荐路，例外有评审+限时。</div>\n    <div class=\"recap\"><b>收束：</b>受支持 SDK+模板+目录+任务文档；度量首调时间/接入周期/模板覆盖。</div>\n  </section>\n\n  <section id=\"d\">\n    <h2><span class=\"no\">第 4 步</span>自动门禁+限时例外，代替口头架构约束</h2>\n    <p>口头规范「记得加审计」「别改字段名」靠人记忆，必然漏。把规范变成<b>自动门禁</b>：CI 里跑契约兼容检查、schema 兼容、敏感字段分类、身份/审计默认开启、SLO/Runbook 完整度检查；不达标合并被阻断。运行证据(而非承诺)证明默认路径可观测可回滚。</p>\n    <p>但业务总有例外。用<b>限时例外</b>机制：申请→评审→批准带<b>到期日</b>→到期自动复审或收回。例外不是永久豁免；到期率是治理健康指标。安全/合规默认开启(租户/审计/数据分类)不是业务可选附加。</p>\n    <div class=\"key\"><span class=\"tag\">一句话记住</span>规范靠门禁不靠记忆；例外靠限时不靠永久豁免；默认合规是平台内置不是业务自选。</div>\n    <div class=\"recap\"><b>收束：</b>CI 自动门禁+运行证据+限时例外(到期复审)+默认合规内置。</div>\n  </section>\n\n  <section id=\"e\">\n    <h2><span class=\"no\">第 5 步</span>演进是产品迁移：灰度/迁移/回滚/废弃+价值度量</h2>\n    <p>契约/能力变更按产品迁移做：发布新版本→消费者目录通知→双版本并行(兼容窗口)→迁移水位跟踪→旧版弃用截止→退役。可灰度、可回滚、可废弃。弃用一条能力必须给迁移路径+截止时间，而不是直接删。</p>\n    <p>平台价值用<b>开发者体验+生产结果</b>证明：首次成功调用时间、接入前置时间、工单逃逸率(业务能自助解决的比例)、契约迁移完成率、采纳率、变更失败率。不是「上线了几个工具/写了多少 API」(产出)，而是「业务交付变快变稳」(结果)——呼应 A1 北极星/护栏。</p>\n    <div class=\"key\"><span class=\"tag\">一句话记住</span>变更=产品迁移(兼容窗口+水位+截止)；价值=等待时间/逃逸率/采纳率, 不是工具计数。</div>\n    <div class=\"recap\"><b>收束：</b>双版本兼容窗口+迁移水位+弃用截止；用体验与生产结果度量平台价值。</div>\n  </section>\n\n  <section id=\"lab\">\n    <h2><span class=\"no\">动手</span>两场演练：口头规范vs门禁、接入负担沙盒</h2>\n    <p>演练一看「口头规范+人肉评审」和「自动门禁+限时例外」的差别。演练二拖模板覆盖率/每周工单/单工单人工时长，看平台支持负担与接入等待，并切换门禁开关看破坏变更是被阻断还是静默事故。</p>\n    <div class=\"lab\">\n      <div class=\"lab-head\"><b>演练一 · 两种治理</b><span class=\"hint\">点按钮切换</span></div>\n      <div class=\"controls\"><div class=\"seg\" id=\"e1\"><button data-k=\"oral\" class=\"on\">❌ 口头规范</button><button data-k=\"gate\">✅ 自动门禁</button></div></div>\n      <div class=\"lab-body\"><div><pre id=\"e1code\" style=\"margin:0;\"></pre></div><div class=\"logcat\"><div class=\"logcat-head\"><span>说明</span><span>live</span></div><div class=\"logcat-body\" id=\"e1log\"></div></div></div>\n      <div class=\"lab-foot\"><span class=\"hint\">同一个「别改字段名」，两种命运</span></div>\n    </div>\n    <div class=\"lab\">\n      <div class=\"lab-head\"><b>演练二 · 接入负担沙盒</b><span class=\"hint\">拖滑块+切门禁</span></div>\n      <div class=\"controls\">\n        <div class=\"ctl\"><label>模板覆盖率%</label><input type=\"range\" id=\"g1cov\" min=\"0\" max=\"100\" value=\"80\"><span class=\"val\" id=\"g1covV\">80</span></div>\n        <div class=\"ctl\"><label>每周工单数</label><input type=\"range\" id=\"g1tick\" min=\"0\" max=\"60\" value=\"25\"><span class=\"val\" id=\"g1tickV\">25</span></div>\n        <div class=\"ctl\"><label>单工单人工(h)</label><input type=\"range\" id=\"g1hr\" min=\"1\" max=\"8\" value=\"2\"><span class=\"val\" id=\"g1hrV\">2</span></div>\n        <div class=\"ctl\"><label><input type=\"checkbox\" id=\"g1gate\" checked> 破坏变更门禁</label></div>\n      </div>\n      <div class=\"lab-body\"><div><div class=\"stats\" id=\"g1stats\"></div><div class=\"chips\" id=\"g1chips\"></div><div class=\"key\" id=\"g1hint\"></div></div><div class=\"logcat\"><div class=\"logcat-head\"><span>推导过程</span><span>live</span></div><div class=\"logcat-body\" id=\"g1log\"></div></div></div>\n      <div class=\"lab-foot\"><span class=\"hint\">目标：平台支持负担低、接入等待短、破坏变更零静默事故</span></div>\n    </div>\n    <div class=\"key\"><span class=\"tag\">看懂这两场演练</span>口头规范靠记忆必漏；门禁把破坏变更挡在合并前。模板覆盖越高、工单越少，平台越像产品越不像救火队。</div>\n  </section>\n\n  <section id=\"quiz\">\n    <h2><span class=\"no\">自测</span>六个问题</h2>\n    <div class=\"card\" id=\"quiz-box\"></div>\n    <p id=\"quiz-done\" style=\"display:none;font-weight:700;color:#1E7268;\">全对。你已经会把平台当产品、把契约当承诺。下一课决定这些能力运行在哪里、怎么弹性。</p>\n  </section>\n\n  <section id=\"map\">\n    <h2><span class=\"no\">回顾</span>速查表</h2>\n    <table>\n      <tr><th>概念</th><th>大白话</th><th>要点</th></tr>\n      <tr><td>平台即产品</td><td>港口标准集装箱</td><td>成功=没人来找平台</td></tr>\n      <tr><td>可执行契约</td><td>Owner+语义+兼容+弃用</td><td>破坏变更合并前阻断</td></tr>\n      <tr><td>Golden Path</td><td>标准集装箱+固定航线</td><td>消除外在认知负载</td></tr>\n      <tr><td>内在/外在认知负载</td><td>业务本身/平台强加</td><td>保留内在消除外在</td></tr>\n      <tr><td>自动门禁</td><td>规范靠 CI 不靠记忆</td><td>契约/schema/合规检查</td></tr>\n      <tr><td>限时例外</td><td>批准带到期日</td><td>到期复审, 非永久豁免</td></tr>\n      <tr><td>契约迁移</td><td>双版本+水位+截止</td><td>变更=产品迁移</td></tr>\n      <tr><td>价值度量</td><td>等待/逃逸率/采纳</td><td>结果不是工具计数</td></tr>\n    </table>\n    <div class=\"note\"><span class=\"tag\">说明</span>本页为教学整理，工单/覆盖率为课程场景假设；沙盒为模拟推导。口径以高级 README 与第五篇底稿为准。</div>\n  </section>\n\n  <section id=\"refs\">\n    <h2><span class=\"no\">依据</span>参考链接</h2>\n    <div class=\"card refs\">\n      <h3 style=\"margin-top:0;\">原始底稿（本仓库）</h3>\n      <ul>\n        <li>《AI 后端开发：Java 实战》高级工程师 · 第五篇-平台工程与契约治理 <span class=\"src\">— 本课重写底稿</span></li>\n        <li>高级工程师/README.md <span class=\"src\">— 责任模型与课程边界</span></li>\n      </ul>\n      <h3>方法与规范</h3>\n      <ul>\n        <li><a href=\"https://spec.openapis.org/oas/latest.html\" target=\"_blank\" rel=\"noopener\">OpenAPI Specification</a> <span class=\"src\">— 同步 API 契约载体</span></li>\n        <li><a href=\"https://www.asyncapi.com/docs/reference/specification/latest\" target=\"_blank\" rel=\"noopener\">AsyncAPI Specification</a> <span class=\"src\">— 异步事件契约载体</span></li>\n        <li><a href=\"https://spring.io/projects/spring-cloud-contract\" target=\"_blank\" rel=\"noopener\">Spring Cloud Contract</a> <span class=\"src\">— 消费者驱动契约测试</span></li>\n      </ul>\n      <h3>下一课要用</h3>\n      <ul>\n        <li><a href=\"https://spec.openapis.org/oas/latest.html\" target=\"_blank\" rel=\"noopener\">OpenAPI 兼容策略</a> <span class=\"src\">— A6 部署形态需保持契约兼容与可回滚</span></li>\n      </ul>\n    </div>\n    \n    \n  </section>", "toc": [{"id":"a","title":"平台即产品"},{"id":"b","title":"可执行契约"},{"id":"c","title":"Golden Path"},{"id":"d","title":"门禁+例外"},{"id":"e","title":"演进与度量"},{"id":"lab","title":"两场演练"},{"id":"quiz","title":"本课自测"},{"id":"map","title":"速查表"},{"id":"refs","title":"参考链接"}], "scripts": "(function(){\n  var ORAL=\"// ❌ 口头规范 + 人肉评审\\nWiki: 「记得加审计」「别改字段名」\\n评审靠记忆 → 漏掉 → 旧消费者静默丢维度\\n例外口头批准 → 永久豁免 → 治理腐化\\nSDK 三个复制粘贴版本, 语义各不同\";\n  var GATE=\"// ✅ 自动门禁 + 限时例外\\nCI: 契约兼容/schema/敏感字段/审计默认 检查\\n破坏变更 → 合并前阻断(不靠记忆)\\n例外: 申请→评审→带到期日→到期复审\\n一个受支持 SDK + 模板 + 目录 = Golden Path\";\n  function show(k){document.getElementById(\"e1code\").textContent=(k===\"oral\"?ORAL:GATE);document.getElementById(\"e1log\").innerHTML=\"<div><span class=\\\"\"+(k===\"oral\"?\"err\":\"ok\")+\"\\\">\"+(k===\"oral\"?\"靠记忆必漏, 静默事故+永久豁免\":\"门禁挡在合并前, 例外限时可复审\")+\"</span></div><div><span class=\\\"c\\\">// \"+(k===\"oral\"?\"平台=救火队\":\"平台=产品, 业务自助\")+\"</span></div>\";}\n  document.querySelectorAll(\"#e1 button\").forEach(function(b){b.addEventListener(\"click\",function(){document.querySelectorAll(\"#e1 button\").forEach(function(x){x.classList.remove(\"on\");});b.classList.add(\"on\");show(b.getAttribute(\"data-k\"));});});\n  show(\"oral\");\n})();\n\n// 演练二：接入负担沙盒\n(function(){\n  function val(id){return parseInt(document.getElementById(id).value,10);}\n  function calc(){\n    var cov=val('g1cov'), tick=val('g1tick'), hr=val('g1hr');\n    ['cov','tick','hr'].forEach(function(k){document.getElementById('g1'+k+'V').textContent=val('g1'+k);});\n    var gate=document.getElementById('g1gate').checked;\n    var supportH=tick*hr;                 // 平台每周支持小时\n    var selfServe=cov/100;                // 自助比例\n    var waitWeeks = 6 - 4*selfServe;      // 接入等待随自助覆盖下降\n    var okSupport = supportH<=20;\n    var okWait = waitWeeks<=2;\n    document.getElementById('g1stats').innerHTML=\n      '<div class=\"stat-box '+(okSupport?'good':'bad')+'\"><b>'+supportH+'</b><small>平台支持h/周</small></div>'+\n      '<div class=\"stat-box '+(okWait?'good':'bad')+'\"><b>'+waitWeeks.toFixed(1)+'</b><small>接入等待(周)</small></div>'+\n      '<div class=\"stat-box '+(gate?'good':'bad')+'\"><b>'+(gate?0:2)+'</b><small>静默事故</small></div>';\n    document.getElementById('g1chips').innerHTML=\n      '<span class=\"chip '+(okSupport?'on':'bad')+'\">支持负担 '+(okSupport?'≤20h':'超载=救火队')+'</span>'+\n      '<span class=\"chip '+(okWait?'on':'bad')+'\">等待 '+(okWait?'≤2周':'>2周')+'</span>'+\n      '<span class=\"chip '+(gate?'on':'bad')+'\">门禁 '+(gate?'开:破坏被阻断':'关:静默丢维度!')+'</span>';\n    document.getElementById('g1hint').innerHTML='<span class=\"tag\">推导</span>'+\n      '模板覆盖 '+cov+'% → 自助 '+ (selfServe*100).toFixed(0)+'% → 等待 '+waitWeeks.toFixed(1)+' 周；工单 '+tick+'×'+hr+'h = '+supportH+'h/周。'+(gate?'门禁开, 破坏变更合并前阻断。':'门禁关, 字段改名静默丢用量维度(已发生2次)。');\n    document.getElementById('g1log').innerHTML=[\n      '<div><span class=\"api\">支持负担 = '+tick+' 工单 × '+hr+'h = '+supportH+'h/周</span></div>',\n      '<div><span class=\"ok\">自助比例 = 模板覆盖 '+cov+'%</span></div>',\n      '<div><span class=\"'+(okWait?'ok':'warn')+'\">接入等待 = 6 - 4×'+selfServe.toFixed(2)+' = '+waitWeeks.toFixed(1)+' 周</span></div>',\n      '<div><span class=\"'+(gate?'ok':'err')+'\">破坏变更门禁 '+(gate?'开 → 静默事故 0':'关 → 静默事故 2')+'</span></div>',\n      '<div><span class=\"c\">// 平台价值 = 等待时间/逃逸率/采纳, 不是工具计数</span></div>'\n    ].join('');\n  }\n  ['g1cov','g1tick','g1hr'].forEach(function(id){document.getElementById(id).addEventListener('input',calc);});\n  document.getElementById('g1gate').addEventListener('change',calc);\n  calc();\n})();\n\nconst QUIZ=[{\"q\":\"1. 平台成功的标志是？\",\"opts\":[[\"没人需要来找平台团队(自助)\",true,\"对。看接入等待不是工具数。\"],[\"上线了多少工具\",false,\"那是产出不是结果。\"],[\"平台团队多忙\",false,\"忙=救火队反模式。\"]]},{\"q\":\"2. 可执行契约四件套不含？\",\"opts\":[[\"评审者记忆\",true,\"对。靠门禁不靠记忆。\"],[\"Owner\",false,\"四件套之一。\"],[\"兼容策略与弃用规则\",false,\"四件套之一。\"]]},{\"q\":\"3. 破坏性变更应何时被阻断？\",\"opts\":[[\"合并前自动门禁\",true,\"对。不依赖评审记忆。\"],[\"上线后靠告警\",false,\"已造成静默事故。\"],[\"靠 Wiki 提醒\",false,\"口头必漏。\"]]},{\"q\":\"4. Golden Path 主要消除？\",\"opts\":[[\"外在认知负载\",true,\"对。保留业务内在复杂度。\"],[\"业务内在复杂度\",false,\"那应保留。\"],[\"所有文档\",false,\"任务文档仍需要。\"]]},{\"q\":\"5. 限时例外的关键是？\",\"opts\":[[\"带到期日, 到期复审或收回\",true,\"对。非永久豁免。\"],[\"口头批准永久有效\",false,\"治理腐化。\"],[\"不需要评审\",false,\"例外需评审+限时。\"]]},{\"q\":\"6. 契约/能力变更应按什么做？\",\"opts\":[[\"产品迁移: 兼容窗口+水位+截止\",true,\"对。可灰度可回滚可废弃。\"],[\"一封邮件通知\",false,\"那是事故起点。\"],[\"直接删除旧版\",false,\"需迁移路径+截止。\"]]}];" },
    "backend|java|部署形态与弹性取舍": { "body": "<p class=\"lead\">A5 定了契约与平台产品，这一课决定这些能力运行在哪里：先给每类工作负载画像，比较 VM/托管容器/K8s/Serverless/托管服务，设计弹性与隔离，且平台复杂度不能超过 6 人团队能运营的上限。</p>\n  \n  <div class=\"journey\">\n    <div class=\"j-step\"><span class=\"n\">1</span><span class=\"t\">画像</span><span class=\"s\">货的脾气</span></div>\n    <div class=\"j-step\"><span class=\"n\">2</span><span class=\"t\">选形态</span><span class=\"s\">车/包/机队</span></div>\n    <div class=\"j-step\"><span class=\"n\">3</span><span class=\"t\">弹性</span><span class=\"s\">背压/隔离</span></div>\n    <div class=\"j-step\"><span class=\"n\">4</span><span class=\"t\">动手</span><span class=\"s\">两场演练</span></div>\n    <div class=\"j-step\"><span class=\"n\">5</span><span class=\"t\">自测</span><span class=\"s\">六个问题</span></div>\n  </div>\n\n  <section id=\"a\">\n    <h2><span class=\"no\">第 1 步</span>物流公司不会因「飞机快」把所有货送飞机</h2>\n    <p>先讲个故事。物流公司先看清每批货：生鲜要冷链不能等、文件可隔夜、整柜矿石走海运、急件才上航班；再算自己有几名调度、养不养得起机队。搞反顺序就会为三箱文件买一架飞机。</p>\n    <p>星河 6 名平台工程师要伺候脾气完全不同的「货」：在线 Gateway(200ms 无状态)、SSE 长连接(30 分钟、怕断连背压)、Broker 消费(怕积压)、批处理(可排队)、Agent 长任务(几小时、要断点续跑)。<b>「这是 Java 服务」不是画像</b>——两个 Spring Boot 程序扩展方式可能完全不同。每项能力至少回答：状态/会话、峰谷比、连接时长、上游并发、取消传播、队列服务时间、冷启动容忍、故障后果。</p>\n    <figure>\n      <svg viewBox=\"0 0 760 190\" role=\"img\" aria-label=\"工作负载画像决定运行形态\">\n        <defs><marker id=\"ara6\" markerWidth=\"8\" markerHeight=\"8\" refX=\"6\" refY=\"3\" orient=\"auto\"><path d=\"M0,0 L6,3 L0,6 Z\" fill=\"#A39B8E\"/></marker></defs>\n        <rect x=\"8\" y=\"24\" width=\"150\" height=\"56\" rx=\"10\" fill=\"#ECF1FB\" stroke=\"#C9D8F2\"/><text x=\"83\" y=\"46\" text-anchor=\"middle\" font-size=\"12\" font-weight=\"bold\" fill=\"#2F58A8\">在线无状态</text><text x=\"83\" y=\"64\" text-anchor=\"middle\" font-size=\"11\" fill=\"#7C7166\">快扩缩·托管容器</text>\n        <rect x=\"176\" y=\"24\" width=\"150\" height=\"56\" rx=\"10\" fill=\"#FBF3E4\" stroke=\"#EDD9B4\"/><text x=\"251\" y=\"46\" text-anchor=\"middle\" font-size=\"12\" font-weight=\"bold\" fill=\"#8A5510\">SSE 长连接</text><text x=\"251\" y=\"64\" text-anchor=\"middle\" font-size=\"11\" fill=\"#7C7166\">怕断连·慎Serverless</text>\n        <rect x=\"344\" y=\"24\" width=\"150\" height=\"56\" rx=\"10\" fill=\"#E9F4F2\" stroke=\"#BFE0DB\"/><text x=\"419\" y=\"46\" text-anchor=\"middle\" font-size=\"12\" font-weight=\"bold\" fill=\"#1E7268\">队列/批处理</text><text x=\"419\" y=\"64\" text-anchor=\"middle\" font-size=\"11\" fill=\"#7C7166\">可排队·看队列年龄</text>\n        <rect x=\"512\" y=\"24\" width=\"150\" height=\"56\" rx=\"10\" fill=\"#FBEDE9\" stroke=\"#F0CFC6\"/><text x=\"587\" y=\"46\" text-anchor=\"middle\" font-size=\"12\" font-weight=\"bold\" fill=\"#B04A35\">Agent 长任务</text><text x=\"587\" y=\"64\" text-anchor=\"middle\" font-size=\"11\" fill=\"#7C7166\">断点续跑·状态外置</text>\n        <rect x=\"8\" y=\"104\" width=\"744\" height=\"48\" rx=\"10\" fill=\"#F4F2EC\" stroke=\"#EADFD3\"/>\n        <text x=\"380\" y=\"124\" text-anchor=\"middle\" font-size=\"12\" fill=\"#5B4A2F\">先画像再选形态；平台复杂度 ≤ 团队能运营上限（6 人养不起自建机队就别买飞机）</text>\n        <text x=\"380\" y=\"142\" text-anchor=\"middle\" font-size=\"11\" fill=\"#A39B8E\">不得从「18 个应用」推「必须 K8s」，也不得从「两个试点」推「已具备多地域」</text>\n        <text x=\"380\" y=\"174\" text-anchor=\"middle\" font-size=\"12\" fill=\"#A39B8E\">K8s=自建机队(要调度+维修)；托管容器=包车(够用省心)；选哪个看货和人</text>\n      </svg>\n      <figcaption>图 1 · 先给货分类，再决定骑车、包车还是自建机队。</figcaption>\n    </figure>\n    <div class=\"key\"><span class=\"tag\">一句话记住</span>先画像再选平台；平台复杂度不能超过团队能运营的上限。技术潮流不是决策依据。</div>\n    <div class=\"recap\"><b>收束：</b>每类负载画像(状态/峰谷/连接/队列/冷启动/故障后果)→最小充分运行形态。</div>\n  </section>\n\n  <section id=\"b\">\n    <h2><span class=\"no\">第 2 步</span>五种形态没有默认答案：何时 K8s、何时 Serverless</h2>\n    <table>\n      <tr><th>形态</th><th>适合</th><th>代价/前提</th></tr>\n      <tr><td>VM</td><td>遗留/强隔离/特定内核</td><td>扩缩慢、运维重</td></tr>\n      <tr><td>托管容器</td><td>在线无状态、想免集群运维</td><td>长连接/自定义网络受限</td></tr>\n      <tr><td>Kubernetes</td><td>多负载混部、需精细调度/多团队平台</td><td>要调度员+维修班(运营能力)</td></tr>\n      <tr><td>Serverless</td><td>事件驱动、流量稀疏、短任务</td><td>冷启动/长连接/锁定受限</td></tr>\n      <tr><td>托管服务(DB/Broker/Registry)</td><td>通用能力不想自运维</td><td>锁定/出口成本/驻留条款</td></tr>\n    </table>\n    <p><b>何时 K8s</b>：确有多种异质负载需统一调度、团队具备 7×24 运营能力、收益大于集群复杂度。<b>何时 Serverless</b>：流量稀疏峰谷大、任务短、能接受冷启动、无长连接。<b>SSE 长连接和几小时 Agent 任务通常不适合纯 Serverless</b>。托管 DB/Broker 优先于自建，除非驻留/成本/控制力有硬理由。不因「未来可能」提前建多集群自研控制面。</p>\n    <div class=\"key\"><span class=\"tag\">一句话记住</span>没有默认答案：K8s 不是先进代名词，Serverless 不是天然免运维，VM 不是天然落后。看货+看人。</div>\n    <div class=\"recap\"><b>收束：</b>五形态比较+何时K8s/Serverless 判据+托管优先+不提前建复杂度。</div>\n  </section>\n\n  <section id=\"c\">\n    <h2><span class=\"no\">第 3 步</span>弹性不是自动扩缩：队列年龄、背压、隔离、冷启动</h2>\n    <p>弹性设计按负载脾气：在线看 P95/饱和点水平扩；SSE 看<b>并发连接+背压+慢客户端隔离</b>(不能因一个慢读拖垮全部)；队列看<b>队列年龄**(积压多久)而非仅队列长度，消费速率要&gt;产生速率(呼应 A4)；批处理看峰值排队+优先级；Agent 看<b>断点续跑+状态外置</b>。扩缩容要设冷却/上限防抖振和成本失控。</p>\n    <p><b>租户隔离</b>：限流/配额/舱壁按租户，防一个租户打爆共享资源；<b>冷启动</b>对 Serverless 要预热/保留实例权衡成本；<b>成本归因</b>按租户/负载打标，否则弹性=账单失控。弹性目标要可验证：扩缩响应时间、积压追平时限、隔离有效性，用 PoC/故障测试证明而非承诺。</p>\n    <div class=\"key\"><span class=\"tag\">一句话记住</span>弹性=按脾气设计(连接/队列年龄/背压/断点)+租户隔离+冷启动权衡+成本归因；要证据不要承诺。</div>\n    <div class=\"recap\"><b>收束：</b>分负载弹性策略+队列年龄+背压隔离+冷启动+成本归因+可验证目标。</div>\n  </section>\n\n  <section id=\"d\">\n    <h2><span class=\"no\">第 4 步</span>三面分离与多 AZ/多地域：先设计降级再承诺高可用</h2>\n    <p>把<b>控制面</b>(策略/配置/目录)、<b>数据面</b>(Gateway 运行时/请求链路)、<b>治理面</b>(契约检查/审计/对账 Worker)分开故障域：控制面挂不应直接断数据面(呼应 A2 本地策略快照)。多 AZ 防单机房故障；多地域防地域级故障+满足驻留，但带来一致性/成本/运维复杂度——<b>先设计降级和退出，再承诺高可用与多地域</b>。</p>\n    <p>数据驻留是硬约束：受限数据不得进未批准地域/模型，部署拓扑要标明数据存储/备份位置、跨信任边界通信、控制面与运行时是否同故障域。是否多地域主动—主动由业务损失(RTO/RPO, 交 A7)和驻留法规触发，不默认上。</p>\n    <div class=\"key\"><span class=\"tag\">一句话记住</span>三面分故障域；多 AZ/多地域由故障后果+驻留触发；先降级退出再承诺高可用。</div>\n    <div class=\"recap\"><b>收束：</b>控制/数据/治理三面隔离+多AZ/多地域判据+驻留拓扑+降级先行。</div>\n  </section>\n\n  <section id=\"e\">\n    <h2><span class=\"no\">第 5 步</span>复杂度≤运营上限，用诚实 PoC 验证再承诺</h2>\n    <p>6 人团队能运营的容器/中间件/集群数量有限。每加一层复杂度问：谁值班、谁升级、谁修故障、认知负载超没超(呼应 A3)。<b>平台复杂度超过团队运营上限=不可持续</b>，宁可托管/简化。决策留 ADR：为什么选这形态、备选、负面后果、退出条件。</p>\n    <p>关键假设用<b>诚实 Java 负载 PoC+故障测试</b>验证：冷启动分布、扩缩响应、SSE 背压隔离、队列追平、AZ 故障恢复。报告分位数+失败记录+局限，不伪造、不用一次压测替代生产证据。未量化的数字标记为假设交 A7 继续验证，不写成既成事实。迁移可灰度可回滚可退出。</p>\n    <div class=\"key\"><span class=\"tag\">一句话记住</span>复杂度≤运营上限；PoC 验证冷启动/扩缩/隔离/恢复；未验证=假设不是事实；留退出条件。</div>\n    <div class=\"recap\"><b>收束：</b>运营能力评估+ADR+诚实PoC+假设标记+灰度回滚退出。</div>\n  </section>\n\n  <section id=\"lab\">\n    <h2><span class=\"no\">动手</span>两场演练：全塞K8s vs 按画像、形态选择沙盒</h2>\n    <p>演练一看「所有负载塞一个 K8s 集群」和「按画像选最小充分形态」的差别。演练二拖流量稀疏度/长连接比例/团队运维能力/峰值倍数，看推荐形态；长连接比例高时 Serverless 会被否。</p>\n    <div class=\"lab\">\n      <div class=\"lab-head\"><b>演练一 · 两种部署观</b><span class=\"hint\">点按钮切换</span></div>\n      <div class=\"controls\"><div class=\"seg\" id=\"e1\"><button data-k=\"allk\" class=\"on\">❌ 全塞 K8s</button><button data-k=\"fit\">✅ 按画像选</button></div></div>\n      <div class=\"lab-body\"><div><pre id=\"e1code\" style=\"margin:0;\"></pre></div><div class=\"logcat\"><div class=\"logcat-head\"><span>说明</span><span>live</span></div><div class=\"logcat-body\" id=\"e1log\"></div></div></div>\n      <div class=\"lab-foot\"><span class=\"hint\">同一个平台，两种命运</span></div>\n    </div>\n    <div class=\"lab\">\n      <div class=\"lab-head\"><b>演练二 · 形态选择沙盒</b><span class=\"hint\">拖滑块看推荐</span></div>\n      <div class=\"controls\">\n        <div class=\"ctl\"><label>流量稀疏度</label><input type=\"range\" id=\"g1sp\" min=\"0\" max=\"10\" value=\"3\"><span class=\"val\" id=\"g1spV\">3</span></div>\n        <div class=\"ctl\"><label>长连接比例%</label><input type=\"range\" id=\"g1lc\" min=\"0\" max=\"100\" value=\"40\"><span class=\"val\" id=\"g1lcV\">40</span></div>\n        <div class=\"ctl\"><label>团队运维能力</label><input type=\"range\" id=\"g1ops\" min=\"0\" max=\"10\" value=\"4\"><span class=\"val\" id=\"g1opsV\">4</span></div>\n        <div class=\"ctl\"><label>峰值倍数</label><input type=\"range\" id=\"g1pk\" min=\"1\" max=\"30\" value=\"10\"><span class=\"val\" id=\"g1pkV\">10</span></div>\n      </div>\n      <div class=\"lab-body\"><div><div class=\"stats\" id=\"g1stats\"></div><div class=\"chips\" id=\"g1chips\"></div><div class=\"key\" id=\"g1hint\"></div></div><div class=\"logcat\"><div class=\"logcat-head\"><span>推导过程</span><span>live</span></div><div class=\"logcat-body\" id=\"g1log\"></div></div></div>\n      <div class=\"lab-foot\"><span class=\"hint\">长连接高→否 Serverless；运维低→否 K8s；稀疏+短任务→Serverless</span></div>\n    </div>\n    <div class=\"key\"><span class=\"tag\">看懂这两场演练</span>全塞 K8s 让 6 人背集群运维；按画像选把长连接留托管容器/VM、稀疏短任务给 Serverless、混部才上 K8s——复杂度匹配人。</div>\n  </section>\n\n  <section id=\"quiz\">\n    <h2><span class=\"no\">自测</span>六个问题</h2>\n    <div class=\"card\" id=\"quiz-box\"></div>\n    <p id=\"quiz-done\" style=\"display:none;font-weight:700;color:#1E7268;\">全对。你已经会先画像再选车。下一课把运行形态变成可量化的 SLO 与容灾。</p>\n  </section>\n\n  <section id=\"map\">\n    <h2><span class=\"no\">回顾</span>速查表</h2>\n    <table>\n      <tr><th>概念</th><th>大白话</th><th>要点</th></tr>\n      <tr><td>工作负载画像</td><td>货的脾气</td><td>状态/峰谷/连接/队列/冷启动</td></tr>\n      <tr><td>K8s vs 托管容器</td><td>自建机队 vs 包车</td><td>看运营能力不看出身</td></tr>\n      <tr><td>Serverless 适用</td><td>稀疏+短任务</td><td>长连接/冷启动受限</td></tr>\n      <tr><td>队列年龄</td><td>积压多久</td><td>比队列长度更贴近业务</td></tr>\n      <tr><td>背压/隔离</td><td>慢客户端不拖垮全部</td><td>租户舱壁+限流</td></tr>\n      <tr><td>三面分离</td><td>控制/数据/治理</td><td>控制面挂不断数据面</td></tr>\n      <tr><td>多AZ/多地域</td><td>防机房/防地域+驻留</td><td>先降级再承诺高可用</td></tr>\n      <tr><td>复杂度上限</td><td>团队养得起吗</td><td>超了托管/简化</td></tr>\n    </table>\n    <div class=\"note\"><span class=\"tag\">说明</span>本页为教学整理，形态推荐为启发式模拟；冷启动/恢复等数字为假设需 PoC 验证。口径以高级 README 与第六篇底稿为准。</div>\n  </section>\n\n  <section id=\"refs\">\n    <h2><span class=\"no\">依据</span>参考链接</h2>\n    <div class=\"card refs\">\n      <h3 style=\"margin-top:0;\">原始底稿（本仓库）</h3>\n      <ul>\n        <li>《AI 后端开发：Java 实战》高级工程师 · 第六篇-云原生与弹性架构决策 <span class=\"src\">— 本课重写底稿</span></li>\n        <li>高级工程师/README.md <span class=\"src\">— 责任模型与课程边界</span></li>\n      </ul>\n      <h3>方法与规范</h3>\n      <ul>\n        <li><a href=\"https://kubernetes.io/docs/concepts/overview/\" target=\"_blank\" rel=\"noopener\">Kubernetes Concepts</a> <span class=\"src\">— 集群能力与运营前提</span></li>\n        <li><a href=\"https://docs.aws.amazon.com/lambda/latest/dg/welcome.html\" target=\"_blank\" rel=\"noopener\">AWS Lambda Docs</a> <span class=\"src\">— Serverless 冷启动/连接限制</span></li>\n        <li><a href=\"https://12factor.net/\" target=\"_blank\" rel=\"noopener\">The Twelve-Factor App</a> <span class=\"src\">— 状态外置/可移植运行形态</span></li>\n      </ul>\n      <h3>下一课要用</h3>\n      <ul>\n        <li><a href=\"https://sre.google/sre-book/service-level-objectives/\" target=\"_blank\" rel=\"noopener\">Google SRE · SLO</a> <span class=\"src\">— A7 将把故障域/容量变成 SLO/RTO/RPO</span></li>\n      </ul>\n    </div>\n    \n    \n  </section>", "toc": [{"id":"a","title":"工作负载画像"},{"id":"b","title":"五种形态"},{"id":"c","title":"弹性与隔离"},{"id":"d","title":"三面与多地域"},{"id":"e","title":"复杂度与PoC"},{"id":"lab","title":"两场演练"},{"id":"quiz","title":"本课自测"},{"id":"map","title":"速查表"},{"id":"refs","title":"参考链接"}], "scripts": "(function(){\n  var ALLK=\"// ❌ 全塞一个 K8s 集群\\n在线+SSE+Broker+批处理+Agent 全混部\\n6 人背集群调度/升级/值班/维修\\nSSE 长连接被滚动更新断连\\nAgent 几小时任务被驱逐重跑\\n复杂度 > 运营上限 = 不可持续\";\n  var FIT=\"// ✅ 按画像选最小充分形态\\n在线无状态 → 托管容器(快扩缩)\\nSSE 长连接 → 托管容器/VM(保连接)\\n稀疏短任务 → Serverless(免运维)\\n混部+多团队调度需求 → 才上 K8s\\nDB/Broker/Registry → 托管优先\";\n  function show(k){document.getElementById(\"e1code\").textContent=(k===\"allk\"?ALLK:FIT);document.getElementById(\"e1log\").innerHTML=\"<div><span class=\\\"\"+(k===\"allk\"?\"err\":\"ok\")+\"\\\">\"+(k===\"allk\"?\"为三箱文件买一架飞机\":\"生鲜冷链/矿石海运/急件航班, 各得其所\")+\"</span></div><div><span class=\\\"c\\\">// \"+(k===\"allk\"?\"复杂度超过 6 人运营上限\":\"复杂度匹配团队能力\")+\"</span></div>\";}\n  document.querySelectorAll(\"#e1 button\").forEach(function(b){b.addEventListener(\"click\",function(){document.querySelectorAll(\"#e1 button\").forEach(function(x){x.classList.remove(\"on\");});b.classList.add(\"on\");show(b.getAttribute(\"data-k\"));});});\n  show(\"allk\");\n})();\n\n// 演练二：形态选择沙盒\n(function(){\n  function val(id){return parseInt(document.getElementById(id).value,10);}\n  function calc(){\n    var sp=val('g1sp'), lc=val('g1lc'), ops=val('g1ops'), pk=val('g1pk');\n    ['sp','lc','ops','pk'].forEach(function(k){document.getElementById('g1'+k+'V').textContent=val('g1'+k);});\n    var longConn = lc>=30;\n    var sparse = sp>=7 && !longConn;\n    var canK8s = ops>=7;\n    var rec;\n    if(sparse) rec='Serverless';\n    else if(longConn && !canK8s) rec='托管容器/VM';\n    else if(canK8s && pk>=10) rec='Kubernetes';\n    else rec='托管容器';\n    document.getElementById('g1stats').innerHTML=\n      '<div class=\"stat-box\"><b>'+lc+'%</b><small>长连接</small></div>'+\n      '<div class=\"stat-box\"><b>'+ops+'</b><small>运维能力</small></div>'+\n      '<div class=\"stat-box good\"><b>'+rec+'</b><small>推荐形态</small></div>';\n    document.getElementById('g1chips').innerHTML=\n      '<span class=\"chip '+(longConn?'bad':'on')+'\">长连接 '+(longConn?'高→否Serverless':'低')+'</span>'+\n      '<span class=\"chip '+(canK8s?'on':'bad')+'\">运维 '+(canK8s?'够→可K8s':'不足→否K8s')+'</span>'+\n      '<span class=\"chip '+(sparse?'on':'')+'\">稀疏 '+(sparse?'+短任务→Serverless':'否')+'</span>';\n    document.getElementById('g1hint').innerHTML='<span class=\"tag\">推导</span>'+\n      '长连接 '+lc+'%'+(longConn?'(≥30%) 使 Serverless 不适(断连/冷启动)。':'。')+' 运维 '+ops+(canK8s?'(≥7) 才养得起 K8s。':'(<7) 养不起集群, 选托管。')+' 稀疏 '+sp+(sparse?' 且无长连接 → Serverless。':'。');\n    document.getElementById('g1log').innerHTML=[\n      '<div><span class=\"api\">画像: 稀疏'+sp+' 长连接'+lc+'% 运维'+ops+' 峰值'+pk+'×</span></div>',\n      '<div><span class=\"'+(longConn?'err':'ok')+'\">长连接约束 → '+(longConn?'否 Serverless':'Serverless 可选')+'</span></div>',\n      '<div><span class=\"'+(canK8s?'ok':'warn')+'\">运营能力 → '+(canK8s?'可 K8s':'否 K8s, 托管')+'</span></div>',\n      '<div><span class=\"c\">// 推荐 = '+rec+'（最小充分, 复杂度≤运营上限）</span></div>'\n    ].join('');\n  }\n  ['g1sp','g1lc','g1ops','g1pk'].forEach(function(id){document.getElementById(id).addEventListener('input',calc);});\n  calc();\n})();\n\nconst QUIZ=[{\"q\":\"1. 选运行形态的第一步是？\",\"opts\":[[\"给工作负载画像\",true,\"对。先看清货的脾气。\"],[\"直接上 K8s\",false,\"那是技术潮流驱动。\"],[\"选最先进的\",false,\"先进不是依据。\"]]},{\"q\":\"2. SSE 长连接通常不适合纯 Serverless 因为？\",\"opts\":[[\"冷启动/连接时长/断连受限\",true,\"对。长连接怕断怕冷启动。\"],[\"Serverless 太贵\",false,\"主因是连接语义。\"],[\"K8s 更快\",false,\"无关。\"]]},{\"q\":\"3. 队列弹性更应看？\",\"opts\":[[\"队列年龄(积压多久)\",true,\"对。比长度更贴近业务。\"],[\"仅队列长度\",false,\"长度不反映等待时间。\"],[\"CPU 温度\",false,\"无关。\"]]},{\"q\":\"4. 控制面故障时数据面应？\",\"opts\":[[\"靠本地快照继续服务(三面分离)\",true,\"对。控制面挂不断数据面。\"],[\"一起停\",false,\"那是耦合故障。\"],[\"无限重试控制面\",false,\"会拖垮链路。\"]]},{\"q\":\"5. 多地域主动—主动应由什么触发？\",\"opts\":[[\"业务损失(RTO/RPO)+驻留法规\",true,\"对。不默认上。\"],[\"听起来更高级\",false,\"复杂度成本巨大。\"],[\"未来可能需求\",false,\"不提前建。\"]]},{\"q\":\"6. 平台复杂度的上限是？\",\"opts\":[[\"团队能运营的上限\",true,\"对。超了托管/简化。\"],[\"预算无限\",false,\"运营能力是硬约束。\"],[\"技术潮流\",false,\"看人不看潮流。\"]]}];" },
    "backend|java|SLO、容灾与业务连续性": { "body": "<p class=\"lead\">A6 选了运行形态，这一课把它变成可经营的可靠性：SLI/SLO/SLA 与错误预算、按旅程分级与降级矩阵、由业务损失倒推 RTO/RPO、用 GameDay 演练证明恢复、事故指挥与无责复盘闭环。</p>\n  \n  <div class=\"journey\">\n    <div class=\"j-step\"><span class=\"n\">1</span><span class=\"t\">定额度</span><span class=\"s\">SLO/错误预算</span></div>\n    <div class=\"j-step\"><span class=\"n\">2</span><span class=\"t\">分旅程</span><span class=\"s\">Tier/降级</span></div>\n    <div class=\"j-step\"><span class=\"n\">3</span><span class=\"t\">算损失</span><span class=\"s\">RTO/RPO</span></div>\n    <div class=\"j-step\"><span class=\"n\">4</span><span class=\"t\">动手</span><span class=\"s\">两场演练</span></div>\n    <div class=\"j-step\"><span class=\"n\">5</span><span class=\"t\">自测</span><span class=\"s\">六个问题</span></div>\n  </div>\n\n  <section id=\"a\">\n    <h2><span class=\"no\">第 1 步</span>电网不承诺永不停电，承诺「全年停电≤X 分钟」</h2>\n    <p>先讲个故事。城市电网不承诺「永不停电」，它承诺「全年累计停电不超过 X 分钟」。这个额度<b>是可以花的</b>：本月检修用掉大半就别再排高风险作业；额度烧光先停新项目、把可靠性补回来。真出事算两笔账：多久恢复供电(RTO)、停电前最后一批没同步的数据能丢多少(RPO)。备份不是「存了一份」，而是「演练过、真能拉起来」。</p>\n    <p>三个概念别混：<span class=\"term\">SLI</span>=温度计读数(某用户可观察事件的测量,含分子/分母/排除条件)；<span class=\"term\">SLO</span>=内部盯的那条线(窗口内目标,用于发布/排班/投资)；<span class=\"term2\">SLA</span>=写进合同的赔付条款(可低于 SLO,需法务/销售/运营签字)。<span class=\"term\">错误预算</span>=窗口内允许不合格的份额：月 SLO 99.9% → 30 天约 <b>43.2 分钟</b>。预算是风险消费额度，不是允许制造故障的配额。</p>\n    <figure>\n      <svg viewBox=\"0 0 760 180\" role=\"img\" aria-label=\"SLO 与错误预算\">\n        <defs><marker id=\"ara7\" markerWidth=\"8\" markerHeight=\"8\" refX=\"6\" refY=\"3\" orient=\"auto\"><path d=\"M0,0 L6,3 L0,6 Z\" fill=\"#A39B8E\"/></marker></defs>\n        <rect x=\"8\" y=\"26\" width=\"170\" height=\"56\" rx=\"10\" fill=\"#ECF1FB\" stroke=\"#C9D8F2\"/><text x=\"93\" y=\"48\" text-anchor=\"middle\" font-size=\"12\" font-weight=\"bold\" fill=\"#2F58A8\">SLI 测量</text><text x=\"93\" y=\"66\" text-anchor=\"middle\" font-size=\"11\" fill=\"#7C7166\">合格首Token/有效请求</text>\n        <rect x=\"200\" y=\"26\" width=\"170\" height=\"56\" rx=\"10\" fill=\"#E9F4F2\" stroke=\"#BFE0DB\"/><text x=\"285\" y=\"48\" text-anchor=\"middle\" font-size=\"12\" font-weight=\"bold\" fill=\"#1E7268\">SLO 内部线</text><text x=\"285\" y=\"66\" text-anchor=\"middle\" font-size=\"11\" fill=\"#7C7166\">月≥99.9%</text>\n        <rect x=\"392\" y=\"26\" width=\"170\" height=\"56\" rx=\"10\" fill=\"#FBF3E4\" stroke=\"#EDD9B4\"/><text x=\"477\" y=\"48\" text-anchor=\"middle\" font-size=\"12\" font-weight=\"bold\" fill=\"#8A5510\">错误预算</text><text x=\"477\" y=\"66\" text-anchor=\"middle\" font-size=\"11\" fill=\"#7C7166\">≈43.2 min/月, 可花完</text>\n        <rect x=\"584\" y=\"26\" width=\"168\" height=\"56\" rx=\"10\" fill=\"#FBEDE9\" stroke=\"#F0CFC6\"/><text x=\"668\" y=\"48\" text-anchor=\"middle\" font-size=\"12\" font-weight=\"bold\" fill=\"#B04A35\">SLA 合同赔付</text><text x=\"668\" y=\"66\" text-anchor=\"middle\" font-size=\"11\" fill=\"#7C7166\">可低于 SLO, 需签字</text>\n        <line x1=\"178\" y1=\"54\" x2=\"198\" y2=\"54\" stroke=\"#A39B8E\" stroke-width=\"2\" marker-end=\"url(#ara7)\"/>\n        <line x1=\"370\" y1=\"54\" x2=\"390\" y2=\"54\" stroke=\"#A39B8E\" stroke-width=\"2\" marker-end=\"url(#ara7)\"/>\n        <rect x=\"8\" y=\"104\" width=\"744\" height=\"48\" rx=\"10\" fill=\"#F4F2EC\" stroke=\"#EADFD3\"/>\n        <text x=\"380\" y=\"124\" text-anchor=\"middle\" font-size=\"12\" fill=\"#5B4A2F\">预算烧光 → 停高风险发布、先还可靠性债；ADR 记「为什么选」, 演练才证明「真能做到」</text>\n        <text x=\"380\" y=\"142\" text-anchor=\"middle\" font-size=\"11\" fill=\"#A39B8E\">别用平均延迟替代体验, 别把 HTTP 200 当成功(SSE 空流/拒答/计量丢失都算失败)</text>\n      </svg>\n      <figcaption>图 1 · SLI→SLO→错误预算→SLA：额度可花完，花完先还债。</figcaption>\n    </figure>\n    <div class=\"key\"><span class=\"tag\">一句话记住</span>没演练过的备份不算能恢复；错误预算是经营额度不是故障配额；SLO≠SLA。</div>\n    <div class=\"recap\"><b>收束：</b>SLI(测量)→SLO(内部线)→错误预算(额度)→SLA(合同)；预算烧光冻结高风险变更。</div>\n  </section>\n\n  <section id=\"b\">\n    <h2><span class=\"no\">第 2 步</span>按用户旅程拆 SLI 与 Tier，配容量与降级矩阵</h2>\n    <p>同一事件可服务多个 SLI 但分母语义独立：拆开「决策是否响应」「允许请求是否被接受」「策略是否正确」「生成是否完成」。<b>正确拒绝≠生成成功</b>；可重试错误仍是不合格。SSE 连接建立后空流、模型拒答、计量丢失都让用户旅程失败——别把 HTTP 200 当成功。</p>\n    <p>按业务后果分 Tier：Tier1=Admission/Gateway REST+SSE/Grant 撤销/UsageFact 接收(关键旅程)；Tier2=Portal/Catalog/Registry/治理 Worker/Rating；Tier3=RAG 索引/离线分析/文档生成(可排队可重算)。Broker 是跨 Tier 依赖不能给单一静态 Tier。<b>容量模型</b>推导可承诺吞吐/连接/队列年龄/资源水位；<b>降级矩阵</b>写清每种故障下谁被限流、谁被隔离、退到什么程度、多久恢复——不是「加了熔断器」就算可靠。</p>\n    <div class=\"key\"><span class=\"tag\">一句话记住</span>按旅程而非按组件定级；降级矩阵约束故障行为；容量余量+弹性滞后纳入阈值。</div>\n    <div class=\"recap\"><b>收束：</b>旅程 SLI(独立分母)+Tier 分级+容量模型+降级矩阵(谁限流/隔离/恢复时限)。</div>\n  </section>\n\n  <section id=\"c\">\n    <h2><span class=\"no\">第 3 步</span>RTO/RPO 由业务损失倒推，灾备等级不默认最高</h2>\n    <p><span class=\"term\">RTO</span>=多久必须恢复(恢复时间目标)；<span class=\"term\">RPO</span>=能丢多少数据(恢复点目标)。两者由<b>业务损失</b>倒推：核心客服停 1 小时损失多少？丢 5 分钟用量损失多少？据此选灾备等级：备份恢复(小时级)→主备切换(分钟级)→多 AZ 高可用→多地域主动—主动(秒级但贵且复杂)。<b>不是所有数据都值得最高档</b>——Tier3 离线分析可排队重算，配昂贵双活是浪费。</p>\n    <table>\n      <tr><th>灾备等级</th><th>RTO 量级</th><th>RPO 量级</th><th>成本/复杂度</th></tr>\n      <tr><td>备份+恢复</td><td>小时</td><td>上次备份点</td><td>低</td></tr>\n      <tr><td>主备切换</td><td>分钟</td><td>复制延迟</td><td>中</td></tr>\n      <tr><td>多 AZ 高可用</td><td>秒~分钟</td><td>同步≈0</td><td>中高</td></tr>\n      <tr><td>多地域主动—主动</td><td>秒</td><td>≈0(需一致性设计)</td><td>高</td></tr>\n    </table>\n    <div class=\"key\"><span class=\"tag\">一句话记住</span>RTO/RPO 是业务损失换算来的，不是技术炫耀；按 Tier 配档，别给离线分析买双活。</div>\n    <div class=\"recap\"><b>收束：</b>业务损失→RTO/RPO→灾备等级→按 Tier 投资；多地域需一致性+驻留设计。</div>\n  </section>\n\n  <section id=\"d\">\n    <h2><span class=\"no\">第 4 步</span>备份与切换：演练过、有证据，才算「能恢复」</h2>\n    <p>「我们存了一份备份」≠能恢复。要<b>定期演练恢复</b>：真从备份拉起、校验数据完整性、记录恢复耗时(对 RTO)、确认丢失窗口(对 RPO)。多地域切换同理：数据资产×主地域×合法备援地域矩阵、复制延迟、切换权限都要<b>tested</b>；法规驻留是 declared 约束，切换能力必须演练证明。ADR 写「选了主备切换」只说明为什么选，<b>不证明切得动</b>。</p>\n    <p>证据状态五档：<span class=\"term\">observed</span>(生产遥测)、<span class=\"term\">tested</span>(标明边界的测试/演练)、<span class=\"term2\">declared</span>(合同/法规声明)、<span class=\"term2\">candidate</span>(ADR/课堂假设)、<b>unknown</b>(缺来源)。状态只能由新证据升级；评审通过不能把 candidate 自动变 tested。未演练的故障域/切换/容量一律 candidate/unknown，进待验证计划而非承诺。</p>\n    <div class=\"key\"><span class=\"tag\">一句话记住</span>恢复能力=演练证据不是备份存在；candidate≠tested；未验证的数字是假设不是承诺。</div>\n    <div class=\"recap\"><b>收束：</b>恢复/切换演练+证据五档+状态只升不降+未验证进待验证计划。</div>\n  </section>\n\n  <section id=\"e\">\n    <h2><span class=\"no\">第 5 步</span>GameDay、事故指挥与无责复盘：闭环经营可靠性</h2>\n    <p><span class=\"term\">GameDay</span>=主动注入故障演练(供应商断、AZ 挂、Broker 积压、控制面不可用)，验证降级矩阵/切换/恢复时限真的生效，暴露隐藏耦合。演练记录是 tested 证据来源。</p>\n    <p>真事故用<b>事故指挥</b>(IC)机制：明确指挥/操作/沟通角色，先恢复后查因，对外沟通统一口径。事后<b>无责复盘</b>(blameless postmortem)：聚焦系统/流程缺陷而非指责个人，产出可执行改进项+负责人+期限，回灌到 SLO/降级/演练/门禁。可靠性是「目标→预算→演练→事故→改进」的持续经营闭环，不是几个熔断器。</p>\n    <div class=\"key\"><span class=\"tag\">一句话记住</span>价值不在从不故障，而在故障时关键旅程以可预期方式继续、且能证明恢复；复盘无责、改进有主。</div>\n    <div class=\"recap\"><b>收束：</b>GameDay 注入演练+事故指挥(先恢复)+无责复盘(改进有主)+回灌闭环。</div>\n  </section>\n\n  <section id=\"lab\">\n    <h2><span class=\"no\">动手</span>两场演练：永不故障vs预算经营、错误预算沙盒</h2>\n    <p>演练一看「承诺永不故障/堆熔断器」和「SLO+错误预算经营」的差别。演练二拖 SLO/已故障分钟，看错误预算剩余与是否烧光(烧光冻结高风险发布)，并切换「备份演练过」看恢复是否可信。</p>\n    <div class=\"lab\">\n      <div class=\"lab-head\"><b>演练一 · 两种可靠性观</b><span class=\"hint\">点按钮切换</span></div>\n      <div class=\"controls\"><div class=\"seg\" id=\"e1\"><button data-k=\"never\" class=\"on\">❌ 承诺永不故障</button><button data-k=\"budget\">✅ 预算经营</button></div></div>\n      <div class=\"lab-body\"><div><pre id=\"e1code\" style=\"margin:0;\"></pre></div><div class=\"logcat\"><div class=\"logcat-head\"><span>说明</span><span>live</span></div><div class=\"logcat-body\" id=\"e1log\"></div></div></div>\n      <div class=\"lab-foot\"><span class=\"hint\">同一个平台，两种命运</span></div>\n    </div>\n    <div class=\"lab\">\n      <div class=\"lab-head\"><b>演练二 · 错误预算沙盒</b><span class=\"hint\">拖 SLO/故障分钟+切演练</span></div>\n      <div class=\"controls\">\n        <div class=\"ctl\"><label>SLO(%)</label><input type=\"range\" id=\"g1slo\" min=\"9900\" max=\"9999\" value=\"9990\"><span class=\"val\" id=\"g1sloV\">99.90</span></div>\n        <div class=\"ctl\"><label>已故障(min)</label><input type=\"range\" id=\"g1used\" min=\"0\" max=\"120\" value=\"20\"><span class=\"val\" id=\"g1usedV\">20</span></div>\n        <div class=\"ctl\"><label><input type=\"checkbox\" id=\"g1drill\" checked> 备份/切换演练过</label></div>\n      </div>\n      <div class=\"lab-body\"><div><div class=\"stats\" id=\"g1stats\"></div><div class=\"chips\" id=\"g1chips\"></div><div class=\"key\" id=\"g1hint\"></div></div><div class=\"logcat\"><div class=\"logcat-head\"><span>推导过程</span><span>live</span></div><div class=\"logcat-body\" id=\"g1log\"></div></div></div>\n      <div class=\"lab-foot\"><span class=\"hint\">30 天窗口；预算烧光→冻结高风险发布；未演练→恢复不可信</span></div>\n    </div>\n    <div class=\"key\"><span class=\"tag\">看懂这两场演练</span>永不故障是谎言；预算把可靠性变成可经营额度。SLO 越高预算越少(99.99% 仅 4.3min)；备份没演练过，RTO/RPO 承诺就是空的。</div>\n  </section>\n\n  <section id=\"quiz\">\n    <h2><span class=\"no\">自测</span>六个问题</h2>\n    <div class=\"card\" id=\"quiz-box\"></div>\n    <p id=\"quiz-done\" style=\"display:none;font-weight:700;color:#1E7268;\">全对。你已经会把可靠性当经营而非口号。下一课守住安全与供应链底线。</p>\n  </section>\n\n  <section id=\"map\">\n    <h2><span class=\"no\">回顾</span>速查表</h2>\n    <table>\n      <tr><th>概念</th><th>大白话</th><th>要点</th></tr>\n      <tr><td>SLI/SLO/SLA</td><td>温度计/内部线/合同赔付</td><td>三者别混, SLA 需签字</td></tr>\n      <tr><td>错误预算</td><td>停电额度, 可花完</td><td>99.9%≈43.2min/月; 烧光冻结</td></tr>\n      <tr><td>旅程 SLI/Tier</td><td>按用户旅程而非组件</td><td>正确拒绝≠生成成功</td></tr>\n      <tr><td>降级矩阵</td><td>故障时谁限流/隔离/恢复</td><td>不是加熔断器就算可靠</td></tr>\n      <tr><td>RTO/RPO</td><td>多久恢复/能丢多少</td><td>业务损失倒推, 按 Tier 配档</td></tr>\n      <tr><td>演练恢复</td><td>真拉起过才算能恢复</td><td>备份存在≠能恢复</td></tr>\n      <tr><td>证据五档</td><td>observed/tested/declared/candidate/unknown</td><td>只升不降, 评审不升级</td></tr>\n      <tr><td>GameDay/复盘</td><td>主动注入演练/无责改进</td><td>闭环经营可靠性</td></tr>\n    </table>\n    <div class=\"note\"><span class=\"tag\">说明</span>本页为教学整理，SLO/分钟为课堂假设；沙盒为模拟计算。口径以高级 README 与第七篇底稿为准。</div>\n  </section>\n\n  <section id=\"refs\">\n    <h2><span class=\"no\">依据</span>参考链接</h2>\n    <div class=\"card refs\">\n      <h3 style=\"margin-top:0;\">原始底稿（本仓库）</h3>\n      <ul>\n        <li>《AI 后端开发：Java 实战》高级工程师 · 第七篇-SRE容灾与业务连续性 <span class=\"src\">— 本课重写底稿</span></li>\n        <li>高级工程师/README.md <span class=\"src\">— 责任模型与课程边界</span></li>\n      </ul>\n      <h3>方法与规范</h3>\n      <ul>\n        <li><a href=\"https://sre.google/sre-book/service-level-objectives/\" target=\"_blank\" rel=\"noopener\">Google SRE · SLO</a> <span class=\"src\">— SLI/SLO/错误预算定义</span></li>\n        <li><a href=\"https://sre.google/sre-book/embracing-risk/\" target=\"_blank\" rel=\"noopener\">Google SRE · Embracing Risk</a> <span class=\"src\">— 错误预算作为风险额度</span></li>\n        <li><a href=\"https://sre.google/sre-book/postmortem-culture/\" target=\"_blank\" rel=\"noopener\">Google SRE · Postmortem Culture</a> <span class=\"src\">— 无责复盘与改进闭环</span></li>\n      </ul>\n      <h3>下一课要用</h3>\n      <ul>\n        <li><a href=\"https://sre.google/sre-book/postmortem-culture/\" target=\"_blank\" rel=\"noopener\">无责复盘</a> <span class=\"src\">— A8 安全事件同样用无责复盘改进</span></li>\n      </ul>\n    </div>\n    \n    \n  </section>", "toc": [{"id":"a","title":"SLO/错误预算"},{"id":"b","title":"旅程与降级"},{"id":"c","title":"RTO/RPO"},{"id":"d","title":"演练与证据"},{"id":"e","title":"GameDay/复盘"},{"id":"lab","title":"两场演练"},{"id":"quiz","title":"本课自测"},{"id":"map","title":"速查表"},{"id":"refs","title":"参考链接"}], "scripts": "(function(){\n  var NEVER=\"// ❌ 承诺永不故障 / 堆熔断器\\n「我们加了熔断/限流, 所以可靠」\\n无 SLO/无预算/无演练\\n备份「存了一份」但没拉起过\\n出事不知道多久恢复/丢多少\\n复盘=找人背锅\";\n  var BUDGET=\"// ✅ SLO + 错误预算经营\\nSLI 测量 → SLO 内部线 → 错误预算额度\\n预算烧光 → 冻结高风险发布, 先还可靠性债\\nRTO/RPO 由业务损失倒推, 按 Tier 配灾备\\n备份/切换定期 GameDay 演练 = tested 证据\\n事故指挥先恢复 + 无责复盘改进有主\";\n  function show(k){document.getElementById(\"e1code\").textContent=(k===\"never\"?NEVER:BUDGET);document.getElementById(\"e1log\").innerHTML=\"<div><span class=\\\"\"+(k===\"never\"?\"err\":\"ok\")+\"\\\">\"+(k===\"never\"?\"口号+组件, 无法证明恢复\":\"目标→预算→演练→事故→改进 闭环\")+\"</span></div><div><span class=\\\"c\\\">// \"+(k===\"never\"?\"没演练的备份不算能恢复\":\"价值=故障时关键旅程可预期继续+证明恢复\")+\"</span></div>\";}\n  document.querySelectorAll(\"#e1 button\").forEach(function(b){b.addEventListener(\"click\",function(){document.querySelectorAll(\"#e1 button\").forEach(function(x){x.classList.remove(\"on\");});b.classList.add(\"on\");show(b.getAttribute(\"data-k\"));});});\n  show(\"never\");\n})();\n\n// 演练二：错误预算沙盒\n(function(){\n  function val(id){return parseInt(document.getElementById(id).value,10);}\n  function calc(){\n    var sloRaw=val('g1slo'), used=val('g1used');\n    var slo=sloRaw/100;\n    document.getElementById('g1sloV').textContent=slo.toFixed(2);\n    document.getElementById('g1usedV').textContent=used;\n    var drill=document.getElementById('g1drill').checked;\n    var windowMin=30*24*60;             // 30 天\n    var budget=windowMin*(1-slo);       // 错误预算分钟\n    var remain=budget-used;\n    var burned=remain<=0;\n    document.getElementById('g1stats').innerHTML=\n      '<div class=\"stat-box\"><b>'+budget.toFixed(1)+'</b><small>预算(min/月)</small></div>'+\n      '<div class=\"stat-box '+(burned?'bad':'good')+'\"><b>'+remain.toFixed(1)+'</b><small>剩余(min)</small></div>'+\n      '<div class=\"stat-box '+(drill?'good':'bad')+'\"><b>'+(drill?'tested':'candidate')+'</b><small>恢复证据</small></div>';\n    document.getElementById('g1chips').innerHTML=\n      '<span class=\"chip '+(burned?'bad':'on')+'\">预算 '+(burned?'烧光→冻结高风险发布':'尚可→可正常发布')+'</span>'+\n      '<span class=\"chip '+(drill?'on':'bad')+'\">恢复 '+(drill?'演练过=可信':'未演练=承诺为空')+'</span>';\n    document.getElementById('g1hint').innerHTML='<span class=\"tag\">'+(burned?'还债':'经营')+'</span>'+\n      'SLO '+slo.toFixed(2)+'% → 30 天预算 '+budget.toFixed(1)+' min；已用 '+used+' → 剩余 '+remain.toFixed(1)+'。'+(burned?'烧光: 停新项目/高风险变更, 先补可靠性。':'额度内: 可平衡速度与可靠性。')+(drill?'':' 备份/切换未演练, RTO/RPO 只是 candidate。');\n    document.getElementById('g1log').innerHTML=[\n      '<div><span class=\"api\">窗口 = 30×24×60 = '+windowMin+' min</span></div>',\n      '<div><span class=\"ok\">预算 = '+windowMin+' × (1-'+slo.toFixed(4)+') = '+budget.toFixed(1)+' min</span></div>',\n      '<div><span class=\"'+(burned?'err':'ok')+'\">剩余 = '+budget.toFixed(1)+' - '+used+' = '+remain.toFixed(1)+' min → '+(burned?'烧光':'未烧光')+'</span></div>',\n      '<div><span class=\"'+(drill?'ok':'warn')+'\">恢复证据 = '+(drill?'tested(演练过)':'candidate(未演练)')+'</span></div>',\n      '<div><span class=\"c\">// 可靠性=经营额度+演练证据, 不是永不故障口号</span></div>'\n    ].join('');\n  }\n  ['g1slo','g1used'].forEach(function(id){document.getElementById(id).addEventListener('input',calc);});\n  document.getElementById('g1drill').addEventListener('change',calc);\n  calc();\n})();\n\nconst QUIZ=[{\"q\":\"1. 月 SLO 99.9% 的错误预算约？\",\"opts\":[[\"43.2 分钟/30天\",true,\"对。窗口×(1-SLO)。\"],[\"0 分钟\",false,\"那是承诺永不故障。\"],[\"43.2 小时\",false,\"量级错。\"]]},{\"q\":\"2. SLO 与 SLA 的区别？\",\"opts\":[[\"SLO 内部线, SLA 合同赔付(可更低)\",true,\"对。SLA 需法务等签字。\"],[\"完全相同\",false,\"混用出事不知找谁。\"],[\"SLA 一定高于 SLO\",false,\"SLA 可低于 SLO。\"]]},{\"q\":\"3. 错误预算烧光应？\",\"opts\":[[\"冻结高风险发布, 先还可靠性债\",true,\"对。预算是经营额度。\"],[\"继续加速发布\",false,\"会突破 SLO。\"],[\"允许制造故障\",false,\"预算不是故障配额。\"]]},{\"q\":\"4. RTO/RPO 应由什么倒推？\",\"opts\":[[\"业务损失\",true,\"对。按 Tier 配灾备档。\"],[\"技术先进性\",false,\"不是炫耀。\"],[\"默认最高档\",false,\"离线分析配双活=浪费。\"]]},{\"q\":\"5. 「备份存了一份」等于能恢复吗？\",\"opts\":[[\"不等于, 需演练拉起证明\",true,\"对。没演练不算能恢复。\"],[\"等于\",false,\"candidate≠tested。\"],[\"看备份大小\",false,\"无关。\"]]},{\"q\":\"6. 无责复盘聚焦？\",\"opts\":[[\"系统/流程缺陷+改进有主有期限\",true,\"对。不指责个人。\"],[\"找责任人背锅\",false,\"会隐藏风险。\"],[\"只写事故时间线\",false,\"需可执行改进。\"]]}];" },
    "backend|java|零信任与供应链安全": { "body": "<p class=\"lead\">A7 经营可靠性，这一课经营安全：把风险判断/预防/检测/响应做成可持续控制——零信任每门查证、租户隔离与职责分离、数据分类与 AI 护栏、密钥治理、SBOM 让供应链出事能反查。</p>\n  \n  <div class=\"journey\">\n    <div class=\"j-step\"><span class=\"n\">1</span><span class=\"t\">每门查证</span><span class=\"s\">零信任</span></div>\n    <div class=\"j-step\"><span class=\"n\">2</span><span class=\"t\">建模</span><span class=\"s\">攻击路径</span></div>\n    <div class=\"j-step\"><span class=\"n\">3</span><span class=\"t\">隔离</span><span class=\"s\">租户/职责</span></div>\n    <div class=\"j-step\"><span class=\"n\">4</span><span class=\"t\">动手</span><span class=\"s\">两场演练</span></div>\n    <div class=\"j-step\"><span class=\"n\">5</span><span class=\"t\">自测</span><span class=\"s\">六个问题</span></div>\n  </div>\n\n  <section id=\"a\">\n    <h2><span class=\"no\">第 1 步</span>过了值机柜台≠能进驾驶舱；出事靠批次号反查</h2>\n    <p>先讲个故事。机场不会因为你过了值机柜台就免检进驾驶舱：<b>每一道门都重新查证</b>身份、权限、目的，全程留痕。食品厂也一样：出问题要凭批次号十分钟内查到「这批原料进了哪些产品、发去哪些门店」——靠配料表和批次记录(<span class=\"term\">SBOM</span>)，不是「我们检查过」。</p>\n    <p>星河的租户隔离、密钥吊销、AI 提示注入护栏、依赖供应链本质是同一件事：把风险判断/预防/检测/响应做成<b>可持续经营的控制</b>，而不是上线前扫一次交差。尤其紧急通道(<span class=\"term2\">break-glass</span>)要短期、可审计、有到期时间，否则慢慢变成人人皆知的永久后门。</p>\n    <div class=\"key\"><span class=\"tag\">一句话记住</span>安全不是上线前一次扫描，是「每一笔访问都能查证、每一次例外都能到期」。</div>\n    <div class=\"recap\"><b>收束：</b>零信任=每门查证；SBOM=批次反查；例外=限时可审计。</div>\n  </section>\n\n  <section id=\"b\">\n    <h2><span class=\"no\">第 2 步</span>威胁建模六步 + 零信任三原则</h2>\n    <p>威胁建模在需求/架构评审/重大依赖变更/事故复盘时更新，六步：<b>资产→主体→信任边界→攻击路径→控制→残余风险</b>。别把「内网」「已登录」「来自 CI」当天然可信。星河关键路径：外部请求经网关进租户上下文；服务用短期工作负载身份访问向量库；模型输出经策略层才能触发工具；CI 制品签名后才可部署；恢复从隔离备份账户读数据。</p>\n    <p>零信任三原则：<span class=\"term\">显式验证</span>(绑定身份/设备/令牌受众/上下文/风险信号,服务间也认证)、<span class=\"term\">最小授权</span>(默认拒绝,按租户/资源/动作/时间/目的,令牌不可跨服务复用)、<span class=\"term\">持续评估</span>(高风险操作重新鉴权,假定已被攻破)。分段限制爆炸半径：生产/预发/备份/构建/安全账户独立，部署身份不能读生产客户数据。每个控制要有所有者+运行手册+指标+审计证据。</p>\n    <figure>\n      <svg viewBox=\"0 0 760 180\" role=\"img\" aria-label=\"零信任每道门查证\">\n        <defs><marker id=\"ara8\" markerWidth=\"8\" markerHeight=\"8\" refX=\"6\" refY=\"3\" orient=\"auto\"><path d=\"M0,0 L6,3 L0,6 Z\" fill=\"#A39B8E\"/></marker></defs>\n        <rect x=\"8\" y=\"26\" width=\"160\" height=\"56\" rx=\"10\" fill=\"#ECF1FB\" stroke=\"#C9D8F2\"/><text x=\"88\" y=\"48\" text-anchor=\"middle\" font-size=\"12\" font-weight=\"bold\" fill=\"#2F58A8\">浏览器→网关</text><text x=\"88\" y=\"66\" text-anchor=\"middle\" font-size=\"11\" fill=\"#7C7166\">门1: 身份+受众</text>\n        <rect x=\"190\" y=\"26\" width=\"160\" height=\"56\" rx=\"10\" fill=\"#E9F4F2\" stroke=\"#BFE0DB\"/><text x=\"270\" y=\"48\" text-anchor=\"middle\" font-size=\"12\" font-weight=\"bold\" fill=\"#1E7268\">租户→共享服务</text><text x=\"270\" y=\"66\" text-anchor=\"middle\" font-size=\"11\" fill=\"#7C7166\">门2: 租户隔离</text>\n        <rect x=\"372\" y=\"26\" width=\"160\" height=\"56\" rx=\"10\" fill=\"#FBF3E4\" stroke=\"#EDD9B4\"/><text x=\"452\" y=\"48\" text-anchor=\"middle\" font-size=\"12\" font-weight=\"bold\" fill=\"#8A5510\">控制面→数据面</text><text x=\"452\" y=\"66\" text-anchor=\"middle\" font-size=\"11\" fill=\"#7C7166\">门3: 策略决策</text>\n        <rect x=\"554\" y=\"26\" width=\"198\" height=\"56\" rx=\"10\" fill=\"#FBEDE9\" stroke=\"#F0CFC6\"/><text x=\"653\" y=\"48\" text-anchor=\"middle\" font-size=\"12\" font-weight=\"bold\" fill=\"#B04A35\">生产→备份/CI→制品</text><text x=\"653\" y=\"66\" text-anchor=\"middle\" font-size=\"11\" fill=\"#7C7166\">门4: 签名+隔离账户</text>\n        <line x1=\"168\" y1=\"54\" x2=\"188\" y2=\"54\" stroke=\"#A39B8E\" stroke-width=\"2\" marker-end=\"url(#ara8)\"/>\n        <line x1=\"350\" y1=\"54\" x2=\"370\" y2=\"54\" stroke=\"#A39B8E\" stroke-width=\"2\" marker-end=\"url(#ara8)\"/>\n        <line x1=\"532\" y1=\"54\" x2=\"552\" y2=\"54\" stroke=\"#A39B8E\" stroke-width=\"2\" marker-end=\"url(#ara8)\"/>\n        <rect x=\"8\" y=\"104\" width=\"744\" height=\"48\" rx=\"10\" fill=\"#F4F2EC\" stroke=\"#EADFD3\"/>\n        <text x=\"380\" y=\"124\" text-anchor=\"middle\" font-size=\"12\" fill=\"#5B4A2F\">每道门重新查身份/权限/目的；「内网/已登录/来自CI」都不是天然可信</text>\n        <text x=\"380\" y=\"142\" text-anchor=\"middle\" font-size=\"11\" fill=\"#A39B8E\">残余风险要有接受人+期限+补偿控制, 不能由实施者自行永久接受</text>\n      </svg>\n      <figcaption>图 1 · 零信任：控制面/数据面/恢复面各算独立信任边界。</figcaption>\n    </figure>\n    <div class=\"key\"><span class=\"tag\">一句话记住</span>威胁建模六步产出风险卡(资产/主体/边界/路径/控制/残余)；残余风险接受有主有期限，超期自动升级。</div>\n    <div class=\"recap\"><b>收束：</b>六步建模+三原则+分段爆炸半径+控制有主有指标+风险卡限期。</div>\n  </section>\n\n  <section id=\"c\">\n    <h2><span class=\"no\">第 3 步</span>身份/租户/职责分离，break-glass 双人限时</h2>\n    <p>授权模型组合用：<span class=\"term\">RBAC</span>(岗位/审批,易审计但防角色膨胀)、<span class=\"term\">ABAC</span>(租户/地域/数据级别/时间窗,表达上下文)、<span class=\"term2\">ReBAC</span>(关系,如「文档属于租户」)。别用「管理员」承载全部例外。<b>租户隔离</b>：tenantId 来自可信身份不采信请求参数；跨租户读取 100% 拒绝且不泄露目标租户信息。<b>职责分离</b>：申请/批准/执行/观察分开，同一人不得既申请又批准。</p>\n    <p><b>break-glass</b> 默认双人批准、最小动作/资源/租户/地域/时间窗、全量实时审计、自动过期。单人激活仅限预定义极端场景(双人同灾不可达)，且<b>不可扩权</b>、不能关隔离/签名/审计、凭据不可续期、恢复双人能力后立即终止轮换。事后复核是额外控制，<b>不是双人批准的替代品</b>。安全与可靠性冲突时：恢复不能整体关闭安全控制。</p>\n    <div class=\"key\"><span class=\"tag\">一句话记住</span>例外通道=双人+限时+不可扩权+自动过期；否则紧急通道变永久后门。</div>\n    <div class=\"recap\"><b>收束：</b>RBAC/ABAC/ReBAC 组合+租户隔离+职责分离+break-glass 双人限时不可扩权。</div>\n  </section>\n\n  <section id=\"d\">\n    <h2><span class=\"no\">第 4 步</span>数据分类/驻留/生命周期 + AI 特有护栏</h2>\n    <p>数据先<b>分类</b>(公开/内部/敏感/受限)，再定<b>驻留</b>(不得进未批准地域/模型)、<b>保留/删除</b>期限、备份与加密。受限数据错误路由必须在离开受控边界前<b>阻断</b>(呼应 A2 S-01)，留可验证审计。日志/遥测<b>脱敏</b>：不含原始敏感 Prompt。</p>\n    <p>AI 特有风险的护栏：<span class=\"term\">提示注入</span>(用户/文档内容诱导模型越权)→模型输出经策略层才能触发工具、工具最小权限+人工复核高风险动作；<span class=\"term\">投毒 RAG</span>(恶意文档进知识库)→来源校验+内容过滤+引用溯源；<span class=\"term\">工具越权/数据外泄</span>→范围化令牌+出口阻断+审计。把模型输出当<b>不可信输入</b>对待，不直接执行。</p>\n    <div class=\"key\"><span class=\"tag\">一句话记住</span>数据分类→驻留→生命周期；模型输出=不可信输入，经策略层+最小权限+审计才能触工具/出口。</div>\n    <div class=\"recap\"><b>收束：</b>分类/驻留/保留删除/脱敏+注入/投毒/越权护栏+输出不可信。</div>\n  </section>\n\n  <section id=\"e\">\n    <h2><span class=\"no\">第 5 步</span>密钥治理 + SBOM：出事能反查、制品能验签</h2>\n    <p><b>密钥/凭据</b>：短期工作负载身份替代长期共享密钥；受众绑定、自动轮换、吊销快通道(全局≤5min, 呼应 A2 S-03)；密钥不进代码/日志；KMS 异常只用未过期短期凭据不启用长期共享密钥。量化指标：长期凭据比例、无受众令牌拒绝率、异常处置时间。</p>\n    <p><b>SBOM</b>(软件物料清单)=配料表+批次号：每个制品记录依赖清单+版本+来源；配合<b>签名</b>(如 SLSA 构建溯源)保证「CI 制品签名后才可部署」。漏洞爆发时凭 SBOM <b>十分钟反查</b>「受影响依赖进了哪些制品/发去哪些租户」，而不是「我们检查过」。供应商纳入治理：合同 SLA+数据处理条款+退出路径(呼应 A1 转移风险)。</p>\n    <div class=\"key\"><span class=\"tag\">一句话记住</span>短期凭据+受众绑定+吊销快通道；SBOM+签名让供应链可反查可验签；供应商有合同有退出。</div>\n    <div class=\"recap\"><b>收束：</b>密钥短期/轮换/吊销+SBOM 批次反查+制品签名验签+供应商合同退出。</div>\n  </section>\n\n  <section id=\"lab\">\n    <h2><span class=\"no\">动手</span>两场演练：内网可信vs零信任、SBOM 反查沙盒</h2>\n    <p>演练一看「内网/已登录天然可信」和「零信任每门查证」的差别。演练二模拟依赖漏洞爆发：切换 SBOM/签名开关、拖受影响制品数，看能否快速反查与阻断未签名部署。</p>\n    <div class=\"lab\">\n      <div class=\"lab-head\"><b>演练一 · 两种信任观</b><span class=\"hint\">点按钮切换</span></div>\n      <div class=\"controls\"><div class=\"seg\" id=\"e1\"><button data-k=\"trust\" class=\"on\">❌ 内网天然可信</button><button data-k=\"zero\">✅ 零信任每门查证</button></div></div>\n      <div class=\"lab-body\"><div><pre id=\"e1code\" style=\"margin:0;\"></pre></div><div class=\"logcat\"><div class=\"logcat-head\"><span>说明</span><span>live</span></div><div class=\"logcat-body\" id=\"e1log\"></div></div></div>\n      <div class=\"lab-foot\"><span class=\"hint\">同一个「已登录」，两种命运</span></div>\n    </div>\n    <div class=\"lab\">\n      <div class=\"lab-head\"><b>演练二 · SBOM 反查沙盒</b><span class=\"hint\">切 SBOM/签名+拖制品数</span></div>\n      <div class=\"controls\">\n        <div class=\"ctl\"><label>受影响制品数</label><input type=\"range\" id=\"g1art\" min=\"1\" max=\"200\" value=\"40\"><span class=\"val\" id=\"g1artV\">40</span></div>\n        <div class=\"ctl\"><label><input type=\"checkbox\" id=\"g1sbom\" checked> 有 SBOM</label></div>\n        <div class=\"ctl\"><label><input type=\"checkbox\" id=\"g1sign\" checked> 制品签名验签</label></div>\n      </div>\n      <div class=\"lab-body\"><div><div class=\"stats\" id=\"g1stats\"></div><div class=\"chips\" id=\"g1chips\"></div><div class=\"key\" id=\"g1hint\"></div></div><div class=\"logcat\"><div class=\"logcat-head\"><span>推导过程</span><span>live</span></div><div class=\"logcat-body\" id=\"g1log\"></div></div></div>\n      <div class=\"lab-foot\"><span class=\"hint\">目标：漏洞爆发 10 分钟内反查受影响制品/租户；未签名制品禁止部署</span></div>\n    </div>\n    <div class=\"key\"><span class=\"tag\">看懂这两场演练</span>内网可信让被盗会话跨租户长驱直入；零信任每门查证拦住。无 SBOM 时漏洞反查靠人肉翻仓库(小时级)，有 SBOM 十分钟定位批次。</div>\n  </section>\n\n  <section id=\"quiz\">\n    <h2><span class=\"no\">自测</span>六个问题</h2>\n    <div class=\"card\" id=\"quiz-box\"></div>\n    <p id=\"quiz-done\" style=\"display:none;font-weight:700;color:#1E7268;\">全对。你已经会把安全当持续经营而非一次扫描。下一课算成本账与技术演进。</p>\n  </section>\n\n  <section id=\"map\">\n    <h2><span class=\"no\">回顾</span>速查表</h2>\n    <table>\n      <tr><th>概念</th><th>大白话</th><th>要点</th></tr>\n      <tr><td>零信任</td><td>每道门重新查证</td><td>显式验证/最小授权/持续评估</td></tr>\n      <tr><td>威胁建模六步</td><td>资产→主体→边界→路径→控制→残余</td><td>风险卡有主有期限</td></tr>\n      <tr><td>RBAC/ABAC/ReBAC</td><td>岗位/上下文/关系</td><td>组合用, 防管理员承载一切</td></tr>\n      <tr><td>break-glass</td><td>紧急通道</td><td>双人+限时+不可扩权+自动过期</td></tr>\n      <tr><td>数据分类/驻留</td><td>分级+不得出境</td><td>错路由边界前阻断+脱敏</td></tr>\n      <tr><td>AI 护栏</td><td>输出=不可信输入</td><td>注入/投毒/越权→策略层+最小权限</td></tr>\n      <tr><td>密钥治理</td><td>短期+受众+轮换+吊销</td><td>不启用长期共享密钥</td></tr>\n      <tr><td>SBOM/签名</td><td>配料表批次号+验签</td><td>十分钟反查+未签名禁部署</td></tr>\n    </table>\n    <div class=\"note\"><span class=\"tag\">说明</span>本页为教学整理，反查时间为课程场景假设；沙盒为模拟推导。口径以高级 README 与第八篇底稿为准。</div>\n  </section>\n\n  <section id=\"refs\">\n    <h2><span class=\"no\">依据</span>参考链接</h2>\n    <div class=\"card refs\">\n      <h3 style=\"margin-top:0;\">原始底稿（本仓库）</h3>\n      <ul>\n        <li>《AI 后端开发：Java 实战》高级工程师 · 第八篇-安全合规与供应链治理 <span class=\"src\">— 本课重写底稿</span></li>\n        <li>高级工程师/README.md <span class=\"src\">— 责任模型与课程边界</span></li>\n      </ul>\n      <h3>方法与规范</h3>\n      <ul>\n        <li><a href=\"https://owasp.org/www-project-top-10-for-large-language-model-applications/\" target=\"_blank\" rel=\"noopener\">OWASP Top 10 for LLM</a> <span class=\"src\">— 提示注入/工具越权等 AI 风险</span></li>\n        <li><a href=\"https://slsa.dev/\" target=\"_blank\" rel=\"noopener\">SLSA</a> <span class=\"src\">— 构建溯源与制品签名</span></li>\n        <li><a href=\"https://www.cisa.gov/sbom\" target=\"_blank\" rel=\"noopener\">CISA · SBOM</a> <span class=\"src\">— 软件物料清单与反查</span></li>\n      </ul>\n      <h3>下一课要用</h3>\n      <ul>\n        <li><a href=\"https://slsa.dev/\" target=\"_blank\" rel=\"noopener\">SLSA 供应链</a> <span class=\"src\">— A9 成本/演进需权衡安全投入与退出成本</span></li>\n      </ul>\n    </div>\n    \n    \n  </section>", "toc": [{"id":"a","title":"零信任/SBOM"},{"id":"b","title":"建模三原则"},{"id":"c","title":"隔离/break-glass"},{"id":"d","title":"数据/AI护栏"},{"id":"e","title":"密钥/供应链"},{"id":"lab","title":"两场演练"},{"id":"quiz","title":"本课自测"},{"id":"map","title":"速查表"},{"id":"refs","title":"参考链接"}], "scripts": "(function(){\n  var TRUST=\"// ❌ 内网/已登录/来自CI 天然可信\\n过了值机柜台 → 免检进驾驶舱\\n被盗会话跨租户长驱直入\\n长期共享密钥到处复用\\nbreak-glass 口头批准 → 永久后门\\n出事: 「我们检查过」但查不到批次\";\n  var ZERO=\"// ✅ 零信任: 每道门重新查证\\n显式验证 + 最小授权 + 持续评估\\n租户隔离 + 职责分离(申请≠批准)\\nbreak-glass 双人+限时+不可扩权+自动过期\\n短期凭据+受众绑定+吊销快通道\\nSBOM+签名: 十分钟反查批次, 未签名禁部署\";\n  function show(k){document.getElementById(\"e1code\").textContent=(k===\"trust\"?TRUST:ZERO);document.getElementById(\"e1log\").innerHTML=\"<div><span class=\\\"\"+(k===\"trust\"?\"err\":\"ok\")+\"\\\">\"+(k===\"trust\"?\"一道门破=全线破, 例外变后门\":\"每门查证+例外限时, 爆炸半径受限\")+\"</span></div><div><span class=\\\"c\\\">// \"+(k===\"trust\"?\"安全=上线前扫一次\":\"安全=持续经营的控制闭环\")+\"</span></div>\";}\n  document.querySelectorAll(\"#e1 button\").forEach(function(b){b.addEventListener(\"click\",function(){document.querySelectorAll(\"#e1 button\").forEach(function(x){x.classList.remove(\"on\");});b.classList.add(\"on\");show(b.getAttribute(\"data-k\"));});});\n  show(\"trust\");\n})();\n\n// 演练二：SBOM 反查沙盒\n(function(){\n  function val(id){return parseInt(document.getElementById(id).value,10);}\n  function calc(){\n    var art=val('g1art');\n    document.getElementById('g1artV').textContent=art;\n    var sbom=document.getElementById('g1sbom').checked;\n    var sign=document.getElementById('g1sign').checked;\n    var locateMin = sbom ? 10 : art*3;   // 有SBOM 10min; 无则人肉翻仓库\n    var okLocate = locateMin<=10;\n    document.getElementById('g1stats').innerHTML=\n      '<div class=\"stat-box\"><b>'+art+'</b><small>受影响制品</small></div>'+\n      '<div class=\"stat-box '+(okLocate?'good':'bad')+'\"><b>'+locateMin+'</b><small>反查(min)</small></div>'+\n      '<div class=\"stat-box '+(sign?'good':'bad')+'\"><b>'+(sign?'阻断':'放行')+'</b><small>未签名部署</small></div>';\n    document.getElementById('g1chips').innerHTML=\n      '<span class=\"chip '+(sbom?'on':'bad')+'\">SBOM '+(sbom?'有:批次反查':'无:人肉翻仓库')+'</span>'+\n      '<span class=\"chip '+(sign?'on':'bad')+'\">验签 '+(sign?'开:未签名禁部署':'关:投毒制品可上线!')+'</span>'+\n      '<span class=\"chip '+(okLocate?'on':'bad')+'\">反查 '+(okLocate?'≤10min':'超10min')+'</span>';\n    document.getElementById('g1hint').innerHTML='<span class=\"tag\">'+(sbom?'反查':'陷阱')+'</span>'+\n      (sbom?'凭 SBOM 批次号 10min 定位 '+art+' 个受影响制品及去向租户。':'无 SBOM: 人肉翻 '+art+' 个制品仓库约 '+locateMin+'min, 漏洞窗口拉长。')+(sign?'':' 未验签: 被替换的 CI 依赖可直接部署(供应链投毒)。');\n    document.getElementById('g1log').innerHTML=[\n      '<div><span class=\"api\">漏洞爆发 → 受影响制品 '+art+' 个</span></div>',\n      '<div><span class=\"'+(sbom?'ok':'err')+'\">SBOM '+(sbom?'有 → 批次反查 10min':'无 → 人肉 '+locateMin+'min')+'</span></div>',\n      '<div><span class=\"'+(sign?'ok':'err')+'\">验签 '+(sign?'开 → 未签名制品阻断':'关 → 投毒制品放行')+'</span></div>',\n      '<div><span class=\"c\">// 供应链安全 = 可反查(SBOM) + 可验签(签名) + 供应商合同退出</span></div>'\n    ].join('');\n  }\n  document.getElementById('g1art').addEventListener('input',calc);\n  document.getElementById('g1sbom').addEventListener('change',calc);\n  document.getElementById('g1sign').addEventListener('change',calc);\n  calc();\n})();\n\nconst QUIZ=[{\"q\":\"1. 零信任的核心比喻是？\",\"opts\":[[\"每道门重新查证(过值机≠进驾驶舱)\",true,\"对。内网/已登录不天然可信。\"],[\"进了大门全畅通\",false,\"那是边界信任反模式。\"],[\"一次扫描管终身\",false,\"安全是持续经营。\"]]},{\"q\":\"2. 威胁建模六步顺序？\",\"opts\":[[\"资产→主体→边界→路径→控制→残余\",true,\"对。产出风险卡。\"],[\"先选安全产品再建模\",false,\"产品不是起点。\"],[\"只列漏洞清单\",false,\"缺资产/边界/责任。\"]]},{\"q\":\"3. break-glass 紧急通道必须？\",\"opts\":[[\"双人+限时+不可扩权+自动过期\",true,\"对。否则变永久后门。\"],[\"单人永久有效\",false,\"后门风险。\"],[\"可关闭审计以加快恢复\",false,\"恢复不能关安全控制。\"]]},{\"q\":\"4. 模型输出应被当作？\",\"opts\":[[\"不可信输入, 经策略层才触工具\",true,\"对。防注入/越权。\"],[\"可直接执行的指令\",false,\"提示注入风险。\"],[\"天然可信\",false,\"输出可能被诱导。\"]]},{\"q\":\"5. 密钥治理优先？\",\"opts\":[[\"短期工作负载身份+受众绑定+吊销快通道\",true,\"对。不启用长期共享密钥。\"],[\"长期共享密钥方便\",false,\"泄露面大。\"],[\"密钥写代码里\",false,\"严禁。\"]]},{\"q\":\"6. SBOM 的作用类比？\",\"opts\":[[\"配料表+批次号, 出事十分钟反查\",true,\"对。不是「我们检查过」。\"],[\"上线前一次扫描\",false,\"那是检查不是反查。\"],[\"性能优化清单\",false,\"无关。\"]]}];" },
    "backend|java|成本账与技术演进": { "body": "<p class=\"lead\">A8 守住安全底线，这一课在底线之上经营成本：完整成本树(Token 只是一支)、可审计归因链、单位经济连接业务结果、预算/分摊/异常闭环、Build/Buy/开源全生命周期比较、技术债当贷款排还款计划。</p>\n  \n  <div class=\"journey\">\n    <div class=\"j-step\"><span class=\"n\">1</span><span class=\"t\">算全账</span><span class=\"s\">成本树</span></div>\n    <div class=\"j-step\"><span class=\"n\">2</span><span class=\"t\">追到笔</span><span class=\"s\">归因链</span></div>\n    <div class=\"j-step\"><span class=\"n\">3</span><span class=\"t\">权衡</span><span class=\"s\">路由/预算</span></div>\n    <div class=\"j-step\"><span class=\"n\">4</span><span class=\"t\">动手</span><span class=\"s\">两场演练</span></div>\n    <div class=\"j-step\"><span class=\"n\">5</span><span class=\"t\">自测</span><span class=\"s\">六个问题</span></div>\n  </div>\n\n  <section id=\"a\">\n    <h2><span class=\"no\">第 1 步</span>连锁店不盯「面粉便宜两毛」，算一份餐的完整成本</h2>\n    <p>先讲个故事。开连锁店的人不算「这袋面粉便宜两毛」，他算一份餐的完整成本：食材、房租、人工、损耗、配送，再问「卖一份赚多少、哪步最烧钱、砍掉会不会砸口碑」。省钱也不等于关设备——把冷链省了，省下的钱会变成一次食安事故。</p>\n    <p>星河模型账单涨得比收入快，但真账单远不止 Token：<b>缓存/RAG、网络、存储、可观测、平台 6 人人力、容灾、安全</b>都在里面。只统计模型 API 发票会系统性低估成本。成本树分四层：直接消耗/共享平台/风险保障/人员投入；每个叶子有计量单位/价格来源/归因键/更新频率/责任人。还要区分可变/阶梯/固定/承诺/机会成本。</p>\n    <figure>\n      <svg viewBox=\"0 0 760 190\" role=\"img\" aria-label=\"完整成本树 Token 只是一支\">\n        <rect x=\"280\" y=\"14\" width=\"200\" height=\"44\" rx=\"10\" fill=\"#F4F2EC\" stroke=\"#EADFD3\"/><text x=\"380\" y=\"40\" text-anchor=\"middle\" font-size=\"12.5\" font-weight=\"bold\" fill=\"#5B4A2F\">AI 平台完全成本</text>\n        <rect x=\"8\" y=\"86\" width=\"110\" height=\"52\" rx=\"10\" fill=\"#ECF1FB\" stroke=\"#C9D8F2\"/><text x=\"63\" y=\"108\" text-anchor=\"middle\" font-size=\"11.5\" font-weight=\"bold\" fill=\"#2F58A8\">模型 Token</text><text x=\"63\" y=\"126\" text-anchor=\"middle\" font-size=\"10\" fill=\"#7C7166\">含重试/失败/工具循环</text>\n        <rect x=\"130\" y=\"86\" width=\"110\" height=\"52\" rx=\"10\" fill=\"#E9F4F2\" stroke=\"#BFE0DB\"/><text x=\"185\" y=\"108\" text-anchor=\"middle\" font-size=\"11.5\" font-weight=\"bold\" fill=\"#1E7268\">缓存/RAG</text><text x=\"185\" y=\"126\" text-anchor=\"middle\" font-size=\"10\" fill=\"#7C7166\">命中率/索引重建</text>\n        <rect x=\"252\" y=\"86\" width=\"110\" height=\"52\" rx=\"10\" fill=\"#FBF3E4\" stroke=\"#EDD9B4\"/><text x=\"307\" y=\"108\" text-anchor=\"middle\" font-size=\"11.5\" font-weight=\"bold\" fill=\"#8A5510\">网络/存储</text><text x=\"307\" y=\"126\" text-anchor=\"middle\" font-size=\"10\" fill=\"#7C7166\">跨域复制/保留期</text>\n        <rect x=\"374\" y=\"86\" width=\"110\" height=\"52\" rx=\"10\" fill=\"#ECF1FB\" stroke=\"#C9D8F2\"/><text x=\"429\" y=\"108\" text-anchor=\"middle\" font-size=\"11.5\" font-weight=\"bold\" fill=\"#2F58A8\">可观测</text><text x=\"429\" y=\"126\" text-anchor=\"middle\" font-size=\"10\" fill=\"#7C7166\">采样/高基数/保留</text>\n        <rect x=\"496\" y=\"86\" width=\"110\" height=\"52\" rx=\"10\" fill=\"#FBEDE9\" stroke=\"#F0CFC6\"/><text x=\"551\" y=\"108\" text-anchor=\"middle\" font-size=\"11.5\" font-weight=\"bold\" fill=\"#B04A35\">人力/容灾</text><text x=\"551\" y=\"126\" text-anchor=\"middle\" font-size=\"10\" fill=\"#7C7166\">值班/演练/预留</text>\n        <rect x=\"618\" y=\"86\" width=\"134\" height=\"52\" rx=\"10\" fill=\"#FBEDE9\" stroke=\"#F0CFC6\"/><text x=\"685\" y=\"108\" text-anchor=\"middle\" font-size=\"11.5\" font-weight=\"bold\" fill=\"#B04A35\">安全(基线)</text><text x=\"685\" y=\"126\" text-anchor=\"middle\" font-size=\"10\" fill=\"#7C7166\">隔离/审计/门禁不可砍</text>\n        <line x1=\"380\" y1=\"58\" x2=\"63\" y2=\"84\" stroke=\"#A39B8E\" stroke-width=\"1.5\"/>\n        <line x1=\"380\" y1=\"58\" x2=\"185\" y2=\"84\" stroke=\"#A39B8E\" stroke-width=\"1.5\"/>\n        <line x1=\"380\" y1=\"58\" x2=\"307\" y2=\"84\" stroke=\"#A39B8E\" stroke-width=\"1.5\"/>\n        <line x1=\"380\" y1=\"58\" x2=\"429\" y2=\"84\" stroke=\"#A39B8E\" stroke-width=\"1.5\"/>\n        <line x1=\"380\" y1=\"58\" x2=\"551\" y2=\"84\" stroke=\"#A39B8E\" stroke-width=\"1.5\"/>\n        <line x1=\"380\" y1=\"58\" x2=\"685\" y2=\"84\" stroke=\"#A39B8E\" stroke-width=\"1.5\"/>\n        <text x=\"380\" y=\"166\" text-anchor=\"middle\" font-size=\"12\" fill=\"#A39B8E\">每项优化先问：成本是消失了，还是被转移到别处/别部门/未来事故？</text>\n      </svg>\n      <figcaption>图 1 · Token 只是成本树一支；安全/容灾基线不可通过预算表隐藏削减。</figcaption>\n    </figure>\n    <div class=\"key\"><span class=\"tag\">一句话记住</span>先守安全与 SLO 底线再谈降本；把成本挪到别的部门/未来事故不算优化（绕审查/路由未批准境外模型/减审计保留=风险转移不是 FinOps）。</div>\n    <div class=\"recap\"><b>收束：</b>四层成本树+五类成本性态+禁止转移基线+成本事实时间口径(估算→实结调整不覆盖)。</div>\n  </section>\n\n  <section id=\"b\">\n    <h2><span class=\"no\">第 2 步</span>归因链追到一笔用量，单位经济连接业务结果</h2>\n    <p>一笔花费要能顺着 <span class=\"term\">Offering→Entitlement→Grant→Admission→UsageFact→RatedUsage→RateVersion</span> 追到「哪个租户/哪个能力/哪笔用量/按哪费率」，才知道找谁算。这就是 Cost Allocation Contract：每环有归因键+版本+审计。没有归因链，「降本」只能砍总数不知道砍谁。</p>\n    <p><span class=\"term2\">单位经济</span>=「一份餐赚不赚」：每个有效业务任务的收入−完全成本。看板四视图：<b>边际</b>(再处理一次新增多少,用于路由/限额)、<b>完全分摊</b>(含共享/人力/安全/容灾,用于产品单位经济)、<b>现金</b>(实际支付+承诺,用于预算)、<b>风险调整</b>(成本旁展示 SLO/安全/供应商集中度,不把高风险误标高收益)。</p>\n    <div class=\"key\"><span class=\"tag\">一句话记住</span>归因链让成本可追到笔；单位经济看完全分摊不是只看 Token；风险调整视图防「省钱=高收益」错觉。</div>\n    <div class=\"recap\"><b>收束：</b>归因链七环+单位经济+四视图(边际/完全/现金/风险调整)。</div>\n  </section>\n\n  <section id=\"c\">\n    <h2><span class=\"no\">第 3 步</span>模型路由：质量/延迟/成本权衡，底线之上才谈省</h2>\n    <p>模型路由是最大可变成本杠杆：标准任务路由到便宜模型、复杂任务留高价模型(呼应 A1 沙盒)。但权衡必须在<b>强制安全控制+地域/保留限制+批准供应商+质量/SLO 底线</b>之内：不能为省钱把受限数据路由到未批准境外模型、不能绕内容审查、不能降质量护栏。省下的钱若变成误答/人工转接/食安事故，是转移不是优化。</p>\n    <p>路由决策用边际成本+质量评测+P95 延迟+错误预算联合判断；做敏感性分析(流量比例/价格变化结论是否仍成立)；保留回退到上一版策略的能力(呼应 A2 E-01 单位成本护栏连续 3 天超 15% 告警回退)。</p>\n    <div class=\"key\"><span class=\"tag\">一句话记住</span>路由省钱的前提是底线不破；边际成本+质量+延迟+错误预算联合决策；超护栏可回退。</div>\n    <div class=\"recap\"><b>收束：</b>底线内路由+边际/质量/延迟/预算联合+敏感性分析+护栏回退。</div>\n  </section>\n\n  <section id=\"d\">\n    <h2><span class=\"no\">第 4 步</span>预算/分摊/异常闭环：showback 与 chargeback</h2>\n    <p><span class=\"term\">showback</span>=把成本展示给业务团队(知道花了多少)，<span class=\"term2\">chargeback</span>=实际计入业务预算(谁花谁负责)。两者让业务为 AI 成本承担预算责任(呼应 A1 根因「业务没承担预算责任」)。配合<b>预算预测</b>(按流量/价格/承诺预测)与<b>异常治理</b>(突增告警→归因→限额/回退→复盘)闭环。</p>\n    <p>异常控制不是「设个上限砍掉」——要先归因(重试重复扣费?上下文过长?试验用生产额度? 呼应 A1 问题树)，再针对性处理；限额要保 Tier1 关键旅程(呼应 A7 降级矩阵)。预算偏差率是护栏指标(呼应 A1)。</p>\n    <div class=\"key\"><span class=\"tag\">一句话记住</span>showback 知情、chargeback 负责；异常先归因再处理；限额保关键旅程；预算偏差是护栏。</div>\n    <div class=\"recap\"><b>收束：</b>showback/chargeback+预算预测+异常归因闭环+保 Tier1 限额+偏差护栏。</div>\n  </section>\n\n  <section id=\"e\">\n    <h2><span class=\"no\">第 5 步</span>Build/Buy/开源全生命周期，技术债是贷款要排还款</h2>\n    <p>比较 Build/Buy/开源看<b>全生命周期成本</b>：初始+集成+运维+人力+安全修复+退出/锁定成本+机会成本。免费开源模型可能把许可证费转成 GPU/数据治理/安全修复/平台人力(呼应 A1 复用/采购/自研)。退出难度(数据/合同/架构)是关键维度。</p>\n    <p><span class=\"term\">技术债</span>像高息贷款：有利息(持续拖慢交付/增加事故)和到期日，不是待办清单里一行字。建<b>技术债投资组合</b>：按利息(影响)+本金(修复成本)+风险排序，分配预算排还款计划；配<b>三阶段迁移</b>(影子/双轨→分级切→退役, 呼应 A4)与退出触发器。把排序后的组合+预算+退出触发+依赖+迁移窗口交 A10 组织交付。</p>\n    <div class=\"key\"><span class=\"tag\">一句话记住</span>Build/Buy 看全生命周期+退出成本；技术债=贷款有利息到期日，排还款计划而非无限挂账。</div>\n    <div class=\"recap\"><b>收束：</b>全生命周期比较+退出难度+技术债组合(利息/本金/风险)+三阶段迁移+交 A10。</div>\n  </section>\n\n  <section id=\"lab\">\n    <h2><span class=\"no\">动手</span>两场演练：只算Token vs 全账、单位经济沙盒</h2>\n    <p>演练一看「只统计 Token 发票」和「完整成本树」的差别。演练二拖单任务收入/Token 成本/共享分摊/安全容灾分摊，算单位毛利；切换「砍安全省钱」看它是优化还是风险转移。</p>\n    <div class=\"lab\">\n      <div class=\"lab-head\"><b>演练一 · 两种成本观</b><span class=\"hint\">点按钮切换</span></div>\n      <div class=\"controls\"><div class=\"seg\" id=\"e1\"><button data-k=\"token\" class=\"on\">❌ 只算 Token</button><button data-k=\"full\">✅ 完整成本树</button></div></div>\n      <div class=\"lab-body\"><div><pre id=\"e1code\" style=\"margin:0;\"></pre></div><div class=\"logcat\"><div class=\"logcat-head\"><span>说明</span><span>live</span></div><div class=\"logcat-body\" id=\"e1log\"></div></div></div>\n      <div class=\"lab-foot\"><span class=\"hint\">同一个「降本」，两种命运</span></div>\n    </div>\n    <div class=\"lab\">\n      <div class=\"lab-head\"><b>演练二 · 单位经济沙盒</b><span class=\"hint\">拖滑块+切砍安全</span></div>\n      <div class=\"controls\">\n        <div class=\"ctl\"><label>单任务收入(分)</label><input type=\"range\" id=\"g1rev\" min=\"10\" max=\"100\" value=\"50\"><span class=\"val\" id=\"g1revV\">50</span></div>\n        <div class=\"ctl\"><label>Token成本(分)</label><input type=\"range\" id=\"g1tok\" min=\"1\" max=\"60\" value=\"20\"><span class=\"val\" id=\"g1tokV\">20</span></div>\n        <div class=\"ctl\"><label>共享分摊(分)</label><input type=\"range\" id=\"g1sh\" min=\"0\" max=\"40\" value=\"10\"><span class=\"val\" id=\"g1shV\">10</span></div>\n        <div class=\"ctl\"><label>安全容灾(分)</label><input type=\"range\" id=\"g1sec\" min=\"0\" max=\"30\" value=\"8\"><span class=\"val\" id=\"g1secV\">8</span></div>\n        <div class=\"ctl\"><label><input type=\"checkbox\" id=\"g1cut\"> 砍安全省钱</label></div>\n      </div>\n      <div class=\"lab-body\"><div><div class=\"stats\" id=\"g1stats\"></div><div class=\"chips\" id=\"g1chips\"></div><div class=\"key\" id=\"g1hint\"></div></div><div class=\"logcat\"><div class=\"logcat-head\"><span>推导过程</span><span>live</span></div><div class=\"logcat-body\" id=\"g1log\"></div></div></div>\n      <div class=\"lab-foot\"><span class=\"hint\">单位毛利=收入−完全成本；砍安全=风险转移不算优化</span></div>\n    </div>\n    <div class=\"key\"><span class=\"tag\">看懂这两场演练</span>只算 Token 会以为赚钱，加上共享/人力/安全/容灾可能亏；砍安全让毛利变好看但把成本转成未来事故——风险调整视图会揭穿它。</div>\n  </section>\n\n  <section id=\"quiz\">\n    <h2><span class=\"no\">自测</span>六个问题</h2>\n    <div class=\"card\" id=\"quiz-box\"></div>\n    <p id=\"quiz-done\" style=\"display:none;font-weight:700;color:#1E7268;\">全对。你已经会算一份餐赚不赚、把技术债当贷款。下一课组织团队与 AI 协作交付。</p>\n  </section>\n\n  <section id=\"map\">\n    <h2><span class=\"no\">回顾</span>速查表</h2>\n    <table>\n      <tr><th>概念</th><th>大白话</th><th>要点</th></tr>\n      <tr><td>完整成本树</td><td>一份餐不只食材</td><td>Token/缓存/网络/存储/观测/人力/容灾/安全</td></tr>\n      <tr><td>禁止转移</td><td>省钱≠挪账/挪事故</td><td>安全/保留/批准供应商基线不可砍</td></tr>\n      <tr><td>归因链</td><td>追到一笔用量</td><td>Offering→…→RatedUsage→RateVersion</td></tr>\n      <tr><td>单位经济四视图</td><td>边际/完全/现金/风险调整</td><td>完全分摊看赚不赚</td></tr>\n      <tr><td>路由权衡</td><td>底线之上才谈省</td><td>质量/延迟/成本/错误预算联合</td></tr>\n      <tr><td>showback/chargeback</td><td>知情/负责</td><td>业务承担预算责任</td></tr>\n      <tr><td>Build/Buy/开源</td><td>全生命周期+退出成本</td><td>免费可能转成 GPU/人力/安全</td></tr>\n      <tr><td>技术债</td><td>高息贷款有到期日</td><td>组合排序+还款计划+三阶段迁移</td></tr>\n    </table>\n    <div class=\"note\"><span class=\"tag\">说明</span>本页为教学整理，金额/分摊为课程场景假设；沙盒为模拟计算。口径以高级 README 与第九篇底稿为准。</div>\n  </section>\n\n  <section id=\"refs\">\n    <h2><span class=\"no\">依据</span>参考链接</h2>\n    <div class=\"card refs\">\n      <h3 style=\"margin-top:0;\">原始底稿（本仓库）</h3>\n      <ul>\n        <li>《AI 后端开发：Java 实战》高级工程师 · 第九篇-成本FinOps与技术演进 <span class=\"src\">— 本课重写底稿</span></li>\n        <li>高级工程师/README.md <span class=\"src\">— 责任模型与课程边界</span></li>\n      </ul>\n      <h3>方法与规范</h3>\n      <ul>\n        <li><a href=\"https://www.finops.org/framework/\" target=\"_blank\" rel=\"noopener\">FinOps Framework</a> <span class=\"src\">— 成本归因/分摊/单位经济</span></li>\n        <li><a href=\"https://martinfowler.com/bliki/TechnicalDebt.html\" target=\"_blank\" rel=\"noopener\">Martin Fowler · Technical Debt</a> <span class=\"src\">— 技术债的利息与偿还</span></li>\n        <li><a href=\"https://aws.amazon.com/what-is/cloud-cost-management/\" target=\"_blank\" rel=\"noopener\">Cloud Cost Management</a> <span class=\"src\">— 预算/异常/承诺成本</span></li>\n      </ul>\n      <h3>下一课要用</h3>\n      <ul>\n        <li><a href=\"https://martinfowler.com/bliki/TechnicalDebt.html\" target=\"_blank\" rel=\"noopener\">技术债组合</a> <span class=\"src\">— A10 将把投资组合排进跨团队交付计划</span></li>\n      </ul>\n    </div>\n    \n    \n  </section>", "toc": [{"id":"a","title":"成本树"},{"id":"b","title":"归因/单位经济"},{"id":"c","title":"路由权衡"},{"id":"d","title":"预算闭环"},{"id":"e","title":"Build/技术债"},{"id":"lab","title":"两场演练"},{"id":"quiz","title":"本课自测"},{"id":"map","title":"速查表"},{"id":"refs","title":"参考链接"}], "scripts": "(function(){\n  var TOKEN=\"// ❌ 只算 Token 发票\\n成本 = 模型 API 账单\\n「降本」= 压单价/砍上下文\\n→ 误答↑ 人工转接↑ (成本转移)\\n→ 以为赚钱, 其实共享/人力/安全没算\\n→ 砍容灾/审计美化月账单 = 未来事故\";\n  var FULL=\"// ✅ 完整成本树 + 归因链\\nToken+缓存/RAG+网络+存储+观测+人力+容灾+安全\\n归因: Offering→Grant→Admission→UsageFact→RatedUsage\\n单位经济 = 收入 - 完全分摊\\n四视图: 边际/完全/现金/风险调整\\n安全/SLO 基线不可砍; 技术债排还款计划\";\n  function show(k){document.getElementById(\"e1code\").textContent=(k===\"token\"?TOKEN:FULL);document.getElementById(\"e1log\").innerHTML=\"<div><span class=\\\"\"+(k===\"token\"?\"err\":\"ok\")+\"\\\">\"+(k===\"token\"?\"系统性低估+成本转移\":\"可归因可预测可取舍的业务投资\")+\"</span></div><div><span class=\\\"c\\\">// \"+(k===\"token\"?\"把账藏起来不算优化\":\"先守底线再谈降本\")+\"</span></div>\";}\n  document.querySelectorAll(\"#e1 button\").forEach(function(b){b.addEventListener(\"click\",function(){document.querySelectorAll(\"#e1 button\").forEach(function(x){x.classList.remove(\"on\");});b.classList.add(\"on\");show(b.getAttribute(\"data-k\"));});});\n  show(\"token\");\n})();\n\n// 演练二：单位经济沙盒\n(function(){\n  function val(id){return parseInt(document.getElementById(id).value,10);}\n  function calc(){\n    var rev=val('g1rev'), tok=val('g1tok'), sh=val('g1sh'), sec=val('g1sec');\n    ['rev','tok','sh','sec'].forEach(function(k){document.getElementById('g1'+k+'V').textContent=val('g1'+k);});\n    var cut=document.getElementById('g1cut').checked;\n    var secEff = cut?0:sec;\n    var full = tok+sh+secEff;\n    var margin = rev-full;\n    var ok = margin>0;\n    document.getElementById('g1stats').innerHTML=\n      '<div class=\"stat-box\"><b>'+full+'</b><small>完全成本(分)</small></div>'+\n      '<div class=\"stat-box '+(ok?'good':'bad')+'\"><b>'+margin+'</b><small>单位毛利(分)</small></div>'+\n      '<div class=\"stat-box '+(cut?'bad':'good')+'\"><b>'+(cut?'转移':'优化')+'</b><small>砍安全性质</small></div>';\n    document.getElementById('g1chips').innerHTML=\n      '<span class=\"chip '+(ok?'on':'bad')+'\">单位经济 '+(ok?'赚钱':'亏钱')+'</span>'+\n      '<span class=\"chip '+(cut?'bad':'on')+'\">'+(cut?'砍安全=风险转移(不算优化)':'安全基线保留')+'</span>';\n    document.getElementById('g1hint').innerHTML='<span class=\"tag\">'+(cut?'陷阱':'推导')+'</span>'+\n      '收入 '+rev+' - (Token'+tok+'+共享'+sh+'+安全容灾'+secEff+') = 毛利 '+margin+' 分。'+(cut?'砍安全使毛利 +'+sec+' 但把成本转成未来食安/合规事故, 风险调整视图揭穿。':'安全/容灾是基线成本, 不可通过预算表隐藏削减。');\n    document.getElementById('g1log').innerHTML=[\n      '<div><span class=\"api\">完全成本 = '+tok+'+'+sh+'+'+secEff+' = '+full+' 分</span></div>',\n      '<div><span class=\"'+(ok?'ok':'err')+'\">单位毛利 = '+rev+' - '+full+' = '+margin+' 分 → '+(ok?'赚':'亏')+'</span></div>',\n      '<div><span class=\"'+(cut?'err':'ok')+'\">砍安全 '+(cut?'开 → 风险转移 +'+sec+' 分假收益':'关 → 基线保留')+'</span></div>',\n      '<div><span class=\"c\">// FinOps = 底线之上把每元变成可归因可取舍的投资</span></div>'\n    ].join('');\n  }\n  ['g1rev','g1tok','g1sh','g1sec'].forEach(function(id){document.getElementById(id).addEventListener('input',calc);});\n  document.getElementById('g1cut').addEventListener('change',calc);\n  calc();\n})();\n\nconst QUIZ=[{\"q\":\"1. 只统计模型 Token 发票会？\",\"opts\":[[\"系统性低估 AI 产品成本\",true,\"对。共享/人力/安全/容灾没算。\"],[\"准确反映完全成本\",false,\"遗漏多支。\"],[\"高估成本\",false,\"是低估。\"]]},{\"q\":\"2. 「把受限数据路由到更便宜未批准境外模型」算？\",\"opts\":[[\"风险转移, 不是 FinOps 优化\",true,\"对。违反约束基线。\"],[\"正常降本\",false,\"那是违规。\"],[\"单位经济优化\",false,\"底线破了。\"]]},{\"q\":\"3. 成本归因链要追到？\",\"opts\":[[\"具体一笔用量+费率版本\",true,\"对。Offering→…→RateVersion。\"],[\"部门总账单\",false,\"不知道砍谁。\"],[\"云厂商发票总额\",false,\"无法归因。\"]]},{\"q\":\"4. 单位经济应看哪个视图？\",\"opts\":[[\"完全分摊(含共享/人力/安全/容灾)\",true,\"对。不是只看 Token 边际。\"],[\"只看边际 Token\",false,\"会误判赚钱。\"],[\"只看现金\",false,\"现金用于预算非单位经济。\"]]},{\"q\":\"5. chargeback 与 showback 区别？\",\"opts\":[[\"chargeback 计入业务预算(谁花谁负责)\",true,\"对。showback 仅展示知情。\"],[\"完全相同\",false,\"一个知情一个负责。\"],[\"showback 更强制\",false,\"chargeback 才强制。\"]]},{\"q\":\"6. 技术债应被当作？\",\"opts\":[[\"高息贷款: 有利息到期日, 排还款计划\",true,\"对。不是待办一行字。\"],[\"免费待办清单\",false,\"利息会滚。\"],[\"无需管理\",false,\"会锁住工程能力。\"]]}];" },
    "backend|java|带团队与带 AI 交付": { "body": "<p class=\"lead\">A9 排好了投资组合，这一课把它变成跨团队+Agent 的可交付计划：愿景/原则/委托决策权缩短决策路径，单向门升级评审、双向门授权现场，Team API 与依赖图组织协作，Agent 当受限实习生由独立人验收证据。</p>\n  \n  <div class=\"journey\">\n    <div class=\"j-step\"><span class=\"n\">1</span><span class=\"t\">给谱子</span><span class=\"s\">愿景/原则</span></div>\n    <div class=\"j-step\"><span class=\"n\">2</span><span class=\"t\">分门</span><span class=\"s\">授权/评审</span></div>\n    <div class=\"j-step\"><span class=\"n\">3</span><span class=\"t\">协作</span><span class=\"s\">Team API</span></div>\n    <div class=\"j-step\"><span class=\"n\">4</span><span class=\"t\">动手</span><span class=\"s\">两场演练</span></div>\n    <div class=\"j-step\"><span class=\"n\">5</span><span class=\"t\">自测</span><span class=\"s\">六个问题</span></div>\n  </div>\n\n  <section id=\"a\">\n    <h2><span class=\"no\">第 1 步</span>指挥给谱子和速度，不替每个人拉琴</h2>\n    <p>先讲个故事。交响乐团指挥不替每个人拉琴，也不在小提琴每个音上点头。他给谱子和速度、写清谁在哪小节进、授权首席处理现场细节，只对「换曲目、改配器」这类不可逆决定召集讨论。演出后听录音复盘，找配合问题，不是找谁拉错一个音来罚。</p>\n    <p>高级工程师的杠杆同理：60 研发+18 团队+一批 Agent，若每个决定都等同一场评审会交付必堵死；若全放权对外契约/数据模型又被随手改。所以<b>分清单向门/双向门</b>：可回退的写进授权表给离现场最近的人，不可逆的留给 RFC+决策日志。<b>Agent 像实习生</b>：给最小上下文包、明确边界和停止条件，但由独立的人验收证据——它不能自己批准自己的作业。</p>\n    <div class=\"key\"><span class=\"tag\">一句话记住</span>杠杆=清晰方向+授权边界+协作契约+证据闭环；Agent 不是责任主体，不相信「我做完了」只验收可追溯产物。</div>\n    <div class=\"recap\"><b>收束：</b>指挥式领导：给谱子(愿景)+授权现场(双向门)+不可逆召集(单向门)+复盘找配合问题。</div>\n  </section>\n\n  <section id=\"b\">\n    <h2><span class=\"no\">第 2 步</span>愿景能筛选决策，原则带例外，门分单双向</h2>\n    <p>口号愿景「打造先进智能统一平台」无法指导取舍。有效愿景回答：服务谁/改善什么结果/统一什么/允许什么差异/守哪些边界/如何知道产生价值。<b>原则是带例外机制的默认决策</b>：契约先于实现、租户边界端到端、可逆优先、证据高于完成声明、责任随权限同行、Golden Path、Agent 最小权限——每条写清默认行为+允许例外+所需证据。冲突时回到质量属性/投资组合，不按口号投票。</p>\n    <p><span class=\"term\">双向门</span>=易撤销影响有限(测试库/内部类/可删适配器/单租户影子)→委托决策权 delegated authority，记录假设/预算/停止条件即可，不召集委员会。<span class=\"term2\">单向门</span>=难回退(删历史账单/改租户标识语义/不兼容事件版本/跨域复制受限数据/长期独家合同/暴露公共 API)→扩大评审。判断不看代码行数，问四问：能否按时恢复？是否影响外部消费者/历史数据/合规/Tier1？回退是否需他队同步？错误是否长期不可见/不可逆？</p>\n    <figure>\n      <svg viewBox=\"0 0 760 180\" role=\"img\" aria-label=\"单向门与双向门\">\n        <rect x=\"8\" y=\"26\" width=\"350\" height=\"70\" rx=\"10\" fill=\"#E9F4F2\" stroke=\"#BFE0DB\"/><text x=\"183\" y=\"52\" text-anchor=\"middle\" font-size=\"12.5\" font-weight=\"bold\" fill=\"#1E7268\">双向门 · 可来回走</text><text x=\"183\" y=\"72\" text-anchor=\"middle\" font-size=\"11\" fill=\"#7C7166\">内部实现/测试库/可删适配器/影子实验</text><text x=\"183\" y=\"88\" text-anchor=\"middle\" font-size=\"11\" fill=\"#7C7166\">→ 委托现场, 记假设/预算/停止条件</text>\n        <rect x=\"402\" y=\"26\" width=\"350\" height=\"70\" rx=\"10\" fill=\"#FBEDE9\" stroke=\"#F0CFC6\"/><text x=\"577\" y=\"52\" text-anchor=\"middle\" font-size=\"12.5\" font-weight=\"bold\" fill=\"#B04A35\">单向门 · 推开锁死</text><text x=\"577\" y=\"72\" text-anchor=\"middle\" font-size=\"11\" fill=\"#7C7166\">对外契约/数据模型/删历史/独家合同</text><text x=\"577\" y=\"88\" text-anchor=\"middle\" font-size=\"11\" fill=\"#7C7166\">→ RFC+扩大评审+决策日志+回滚方案</text>\n        <rect x=\"8\" y=\"116\" width=\"744\" height=\"44\" rx=\"10\" fill=\"#F4F2EC\" stroke=\"#EADFD3\"/>\n        <text x=\"380\" y=\"134\" text-anchor=\"middle\" font-size=\"12\" fill=\"#5B4A2F\">指挥的价值=让大部分门由离现场最近的人推开；只把不可逆的留给自己召集</text>\n        <text x=\"380\" y=\"150\" text-anchor=\"middle\" font-size=\"11\" fill=\"#A39B8E\">两类混在一起: 要么处处卡审批, 要么到处埋雷</text>\n      </svg>\n      <figcaption>图 1 · 可回退的授权给团队，不可逆的才升级评审。</figcaption>\n    </figure>\n    <div class=\"key\"><span class=\"tag\">一句话记住</span>愿景筛选决策、原则带例外、门分单双向；授权=责任随权限同行+有时限+事后复核。</div>\n    <div class=\"recap\"><b>收束：</b>有效愿景六问+原则(默认/例外/证据)+四问判门+委托授权表。</div>\n  </section>\n\n  <section id=\"c\">\n    <h2><span class=\"no\">第 3 步</span>RFC/ADR/决策日志：防委员会瓶颈与口头失忆</h2>\n    <p>单向门走 <span class=\"term\">RFC</span>(请求评论)：写背景/备选/取舍/影响/迁移/回滚→异步评论→限期决策→记录。<span class=\"term2\">ADR</span> 记最终决定与理由(呼应 A2)。两者+<b>决策日志</b>防止「口头决策失忆」(六个月后没人记得为什么)和「委员会瓶颈」(事事等会)。紧急决策走预定义紧急通道(有时限+事后补 RFC+复核)，不是绕过机制。</p>\n    <p>评审要<b>异步优先、限期决策、明确决策人</b>(呼应 A1 RACI 的 A 唯一)。评审不是盖章：允许质疑业务优先级、要求备选与负面后果。决策日志记录：决定/备选/理由/证据/决策人/日期/复审触发——让新人和 Agent 能读懂历史而不靠群聊考古。</p>\n    <div class=\"key\"><span class=\"tag\">一句话记住</span>RFC 异步限期+ADR 记理由+决策日志防失忆；紧急通道有时限事后补；评审允许质疑不是盖章。</div>\n    <div class=\"recap\"><b>收束：</b>RFC/ADR/决策日志三件套+异步限期+唯一决策人+紧急通道事后复核。</div>\n  </section>\n\n  <section id=\"d\">\n    <h2><span class=\"no\">第 4 步</span>Team API、依赖图、里程碑与责任移交</h2>\n    <p>跨团队交付靠<span class=\"term\">Team API</span>：每个团队对外暴露「我提供什么契约/怎么找我/我的 SLO/升级路径」，像服务接口一样清晰(呼应 A5 平台即产品、A3 Team Topologies)。配<b>依赖图</b>标谁阻塞谁、<b>关键路径</b>定里程碑、<b>升级路径</b>定卡住找谁、<b>责任移交</b>定上线后谁运营。避免「平台替业务写配置」的中央瓶颈。</p>\n    <p>把 A9 投资组合变成<b>可调整可停止的阶段计划</b>：每阶段有业务结果+技术产出+指标目标+依赖风险+继续/调整/停止条件(呼应 A1 决策门)。计划携带 source/approval_status/evidence_status——<b>未批准只能称假设/估算/待决策</b>，不得反向声称「上篇已批准」。条件变化(预算/供应商/团队)时能解释、调整、停止，而非死守原计划。</p>\n    <div class=\"key\"><span class=\"tag\">一句话记住</span>Team API 让协作像调服务；阶段计划可调整可停止；未批准=假设不是事实；责任移交清楚。</div>\n    <div class=\"recap\"><b>收束：</b>Team API+依赖图+关键路径+升级+移交；阶段计划带批准/证据状态+决策门。</div>\n  </section>\n\n  <section id=\"e\">\n    <h2><span class=\"no\">第 5 步</span>Agent 是受限实习生：最小上下文、边界、停止、独立验收</h2>\n    <p>把 Agent 当<b>受限执行者</b>而非责任主体：给<span class=\"term\">最小上下文包</span>(只读必要信息)、<span class=\"term\">文件/契约边界</span>(只改明确文件,不碰对外契约/数据模型)、<span class=\"term\">预算</span>(token/工具调用/时间上限)、<span class=\"term\">停止条件</span>(越界/不确定/超预算即停并上报)。<b>不持生产凭据</b>、无生产写权限例外；工具调用与 diff 全审计。</p>\n    <p>验收靠<b>独立的人+可追溯证据</b>：测试/扫描/评审原始结果决定验收，可追溯到提交/环境/执行者；<b>Agent 不能自己批准自己的作业</b>。高风险动作(删数据/改契约/生产发布)必须人审批。冲突/辅导/反馈聚焦系统改进；复盘无责(呼应 A7)，找配合问题不找替罪者。Agent 产出纳入同一证据闭环，不享受「AI 做的所以免验」。</p>\n    <div class=\"key\"><span class=\"tag\">一句话记住</span>Agent=实习生：最小上下文+边界+预算+停止条件+独立验收；不相信「我做完了」只认可追溯产物；责任仍在人。</div>\n    <div class=\"recap\"><b>收束：</b>受限执行者四件套+无生产凭据+独立证据验收+高风险人审+无责复盘。</div>\n  </section>\n\n  <section id=\"lab\">\n    <h2><span class=\"no\">动手</span>两场演练：事事评审 vs 授权分级、门类型判定沙盒</h2>\n    <p>演练一看「所有决定等中央评审」和「双向门授权+单向门评审」的差别。演练二勾选决策四个属性，判定它是单向门(走 RFC)还是双向门(委托现场)。</p>\n    <div class=\"lab\">\n      <div class=\"lab-head\"><b>演练一 · 两种决策组织</b><span class=\"hint\">点按钮切换</span></div>\n      <div class=\"controls\"><div class=\"seg\" id=\"e1\"><button data-k=\"central\" class=\"on\">❌ 事事中央评审</button><button data-k=\"deleg\">✅ 授权分级</button></div></div>\n      <div class=\"lab-body\"><div><pre id=\"e1code\" style=\"margin:0;\"></pre></div><div class=\"logcat\"><div class=\"logcat-head\"><span>说明</span><span>live</span></div><div class=\"logcat-body\" id=\"e1log\"></div></div></div>\n      <div class=\"lab-foot\"><span class=\"hint\">同一个团队，两种命运</span></div>\n    </div>\n    <div class=\"lab\">\n      <div class=\"lab-head\"><b>演练二 · 门类型判定沙盒</b><span class=\"hint\">勾选四个属性</span></div>\n      <div class=\"controls\">\n        <div class=\"ctl\"><label><input type=\"checkbox\" id=\"g1rec\" checked> 能按时恢复原状态</label></div>\n        <div class=\"ctl\"><label><input type=\"checkbox\" id=\"g1ext\"> 影响外部消费者/历史/合规</label></div>\n        <div class=\"ctl\"><label><input type=\"checkbox\" id=\"g1sync\"> 回退需他队同步</label></div>\n        <div class=\"ctl\"><label><input type=\"checkbox\" id=\"g1irr\"> 错误不可逆/长期不可见</label></div>\n      </div>\n      <div class=\"lab-body\"><div><div class=\"stats\" id=\"g1stats\"></div><div class=\"chips\" id=\"g1chips\"></div><div class=\"key\" id=\"g1hint\"></div></div><div class=\"logcat\"><div class=\"logcat-head\"><span>推导过程</span><span>live</span></div><div class=\"logcat-body\" id=\"g1log\"></div></div></div>\n      <div class=\"lab-foot\"><span class=\"hint\">任一「不可恢复/影响外部/需同步/不可逆」成立→单向门走 RFC</span></div>\n    </div>\n    <div class=\"key\"><span class=\"tag\">看懂这两场演练</span>事事评审堵死交付、全放权埋雷；按门分级让大部分决定由现场推开。改内部类=双向门委托；改对外事件字段=单向门 RFC。</div>\n  </section>\n\n  <section id=\"quiz\">\n    <h2><span class=\"no\">自测</span>六个问题</h2>\n    <div class=\"card\" id=\"quiz-box\"></div>\n    <p id=\"quiz-done\" style=\"display:none;font-weight:700;color:#1E7268;\">全对。你已经会当指挥而非首席小提琴。下一课毕业整合：把全部能力分阶段交付上线。</p>\n  </section>\n\n  <section id=\"map\">\n    <h2><span class=\"no\">回顾</span>速查表</h2>\n    <table>\n      <tr><th>概念</th><th>大白话</th><th>要点</th></tr>\n      <tr><td>指挥式杠杆</td><td>给谱子不替拉琴</td><td>方向+授权+契约+证据闭环</td></tr>\n      <tr><td>有效愿景</td><td>能筛选决策</td><td>服务谁/结果/统一/差异/边界/价值</td></tr>\n      <tr><td>原则带例外</td><td>默认决策+例外+证据</td><td>冲突回质量属性不投票</td></tr>\n      <tr><td>单向门/双向门</td><td>推开锁死/可来回走</td><td>四问判定; 委托 vs RFC</td></tr>\n      <tr><td>RFC/ADR/决策日志</td><td>异步限期/记理由/防失忆</td><td>唯一决策人+紧急事后补</td></tr>\n      <tr><td>Team API</td><td>团队像服务接口</td><td>契约/SLO/升级/移交</td></tr>\n      <tr><td>阶段计划</td><td>可调整可停止</td><td>带批准/证据状态+决策门</td></tr>\n      <tr><td>Agent 受限验收</td><td>实习生不能自批作业</td><td>最小上下文/边界/预算/停止/独立证据</td></tr>\n    </table>\n    <div class=\"note\"><span class=\"tag\">说明</span>本页为教学整理，12 周/预算为场景假设(待批准)；沙盒为启发式判定。口径以高级 README 与第十篇底稿为准。</div>\n  </section>\n\n  <section id=\"refs\">\n    <h2><span class=\"no\">依据</span>参考链接</h2>\n    <div class=\"card refs\">\n      <h3 style=\"margin-top:0;\">原始底稿（本仓库）</h3>\n      <ul>\n        <li>《AI 后端开发：Java 实战》高级工程师 · 第十篇-技术领导力与人机协作交付 <span class=\"src\">— 本课重写底稿</span></li>\n        <li>高级工程师/README.md <span class=\"src\">— 责任模型与课程边界</span></li>\n      </ul>\n      <h3>方法与规范</h3>\n      <ul>\n        <li><a href=\"https://adr.github.io/\" target=\"_blank\" rel=\"noopener\">ADR</a> <span class=\"src\">— 决策记录与理由</span></li>\n        <li><a href=\"https://teamtopologies.com/\" target=\"_blank\" rel=\"noopener\">Team Topologies</a> <span class=\"src\">— 团队接口与认知负载</span></li>\n        <li><a href=\"https://owasp.org/www-project-top-10-for-large-language-model-applications/\" target=\"_blank\" rel=\"noopener\">OWASP Top 10 for LLM</a> <span class=\"src\">— Agent 越权/过度代理风险</span></li>\n      </ul>\n      <h3>下一课要用</h3>\n      <ul>\n        <li><a href=\"https://adr.github.io/\" target=\"_blank\" rel=\"noopener\">ADR 组合</a> <span class=\"src\">— A11 毕业将汇总全部 ADR/证据成 Portfolio</span></li>\n      </ul>\n    </div>\n    \n    \n  </section>", "toc": [{"id":"a","title":"指挥式杠杆"},{"id":"b","title":"愿景/门"},{"id":"c","title":"RFC/决策日志"},{"id":"d","title":"Team API/计划"},{"id":"e","title":"Agent 验收"},{"id":"lab","title":"两场演练"},{"id":"quiz","title":"本课自测"},{"id":"map","title":"速查表"},{"id":"refs","title":"参考链接"}], "scripts": "(function(){\n  var CENTRAL=\"// ❌ 事事中央评审 / 或全放权\\n每个决定等同一场评审会 → 交付堵死\\n或全放权 → 对外契约/数据模型被随手改\\n口头决策 → 六个月后没人记得为什么\\nAgent「我做完了」→ 自己批准自己作业\";\n  var DELEG=\"// ✅ 授权分级 + 证据闭环\\n双向门 → 委托现场(记假设/预算/停止)\\n单向门 → RFC+ADR+决策日志+回滚\\nTeam API + 依赖图 + 里程碑 + 移交\\nAgent = 受限实习生: 最小上下文/边界/预算/停止\\n独立人验收可追溯证据, 责任仍在人\";\n  function show(k){document.getElementById(\"e1code\").textContent=(k===\"central\"?CENTRAL:DELEG);document.getElementById(\"e1log\").innerHTML=\"<div><span class=\\\"\"+(k===\"central\"?\"err\":\"ok\")+\"\\\">\"+(k===\"central\"?\"要么堵死要么埋雷+失忆\":\"大部分门由现场推开, 不可逆才召集\")+\"</span></div><div><span class=\\\"c\\\">// \"+(k===\"central\"?\"指挥替每个人拉琴\":\"指挥给谱子+授权首席+复盘配合\")+\"</span></div>\";}\n  document.querySelectorAll(\"#e1 button\").forEach(function(b){b.addEventListener(\"click\",function(){document.querySelectorAll(\"#e1 button\").forEach(function(x){x.classList.remove(\"on\");});b.classList.add(\"on\");show(b.getAttribute(\"data-k\"));});});\n  show(\"central\");\n})();\n\n// 演练二：门类型判定沙盒\n(function(){\n  function chk(id){return document.getElementById(id).checked;}\n  function calc(){\n    var rec=chk('g1rec'), ext=chk('g1ext'), sync=chk('g1sync'), irr=chk('g1irr');\n    var oneWay = (!rec)||ext||sync||irr;\n    document.getElementById('g1stats').innerHTML=\n      '<div class=\"stat-box '+(oneWay?'bad':'good')+'\"><b>'+(oneWay?'单向门':'双向门')+'</b><small>判定</small></div>'+\n      '<div class=\"stat-box\"><b>'+(oneWay?'RFC+评审':'委托现场')+'</b><small>决策路径</small></div>'+\n      '<div class=\"stat-box\"><b>'+(oneWay?'扩大':'限期')+'</b><small>评审范围</small></div>';\n    document.getElementById('g1chips').innerHTML=\n      '<span class=\"chip '+(rec?'on':'bad')+'\">可恢复 '+(rec?'是':'否')+'</span>'+\n      '<span class=\"chip '+(ext?'bad':'on')+'\">影响外部 '+(ext?'是':'否')+'</span>'+\n      '<span class=\"chip '+(sync?'bad':'on')+'\">需他队同步 '+(sync?'是':'否')+'</span>'+\n      '<span class=\"chip '+(irr?'bad':'on')+'\">不可逆 '+(irr?'是':'否')+'</span>';\n    document.getElementById('g1hint').innerHTML='<span class=\"tag\">判定</span>'+\n      (oneWay?'存在不可恢复/影响外部/需同步/不可逆之一 → 单向门: 走 RFC+扩大评审+决策日志+回滚方案。':'四问皆「可回退且局部」→ 双向门: 委托现场, 记录假设/预算/停止条件即可, 不召集委员会。');\n    document.getElementById('g1log').innerHTML=[\n      '<div><span class=\"api\">四问: 可恢复='+rec+' 影响外部='+ext+' 需同步='+sync+' 不可逆='+irr+'</span></div>',\n      '<div><span class=\"'+(oneWay?'err':'ok')+'\">单向门 = (!可恢复)||影响外部||需同步||不可逆 = '+oneWay+'</span></div>',\n      '<div><span class=\"c\">// 路径 = '+(oneWay?'RFC+扩大评审':'委托现场+记录')+'（不看代码行数）</span></div>'\n    ].join('');\n  }\n  ['g1rec','g1ext','g1sync','g1irr'].forEach(function(id){document.getElementById(id).addEventListener('change',calc);});\n  calc();\n})();\n\nconst QUIZ=[{\"q\":\"1. 高级工程师的杠杆是？\",\"opts\":[[\"方向+授权边界+协作契约+证据闭环\",true,\"对。不替所有人做决定。\"],[\"替每个人拉琴\",false,\"那是首席不是指挥。\"],[\"让 Agent 写更多代码\",false,\"量不是杠杆。\"]]},{\"q\":\"2. 改对外事件字段属于？\",\"opts\":[[\"单向门: RFC+扩大评审\",true,\"对。一堆人依赖, 难回退。\"],[\"双向门: 委托现场\",false,\"影响外部消费者。\"],[\"无需决策\",false,\"恰恰最该评审。\"]]},{\"q\":\"3. 决策日志防什么？\",\"opts\":[[\"口头决策失忆+委员会瓶颈\",true,\"对。新人/Agent 能读历史。\"],[\"代码编译错误\",false,\"无关。\"],[\"测试覆盖率\",false,\"无关。\"]]},{\"q\":\"4. Team API 类比？\",\"opts\":[[\"团队像服务接口: 契约/SLO/升级/移交\",true,\"对。协作像调服务。\"],[\"内部类图\",false,\"那是实现。\"],[\"组织架构图\",false,\"那是汇报线非接口。\"]]},{\"q\":\"5. Agent 验收应？\",\"opts\":[[\"独立的人+可追溯证据, 不能自批作业\",true,\"对。Agent 非责任主体。\"],[\"相信「我做完了」\",false,\"只认可追溯产物。\"],[\"Agent 自己批准自己\",false,\"越权反模式。\"]]},{\"q\":\"6. 未批准的计划输入应称？\",\"opts\":[[\"假设/估算/待决策\",true,\"对。不得反向声称已批准。\"],[\"已批准事实\",false,\"approval_status!=approved。\"],[\"生产承诺\",false,\"candidate 不是承诺。\"]]}];" },
    "backend|java|毕业：平台分阶段交付": { "body": "<p class=\"lead\">毕业课不再讲新理论，而是把 A1–A10 的战略/架构/边界/一致性/平台/弹性/SRE/安全/成本/协作收敛成一套可评审、可追溯、可灰度、可回滚、可经营复盘的交付组合 Portfolio，并在条件突变时重算、在多角色委员会前答辩。</p>\n  \n  <div class=\"journey\">\n    <div class=\"j-step\"><span class=\"n\">1</span><span class=\"t\">收敛</span><span class=\"s\">Portfolio</span></div>\n    <div class=\"j-step\"><span class=\"n\">2</span><span class=\"t\">索引</span><span class=\"s\">Manifest</span></div>\n    <div class=\"j-step\"><span class=\"n\">3</span><span class=\"t\">门禁</span><span class=\"s\">阶段/重算</span></div>\n    <div class=\"j-step\"><span class=\"n\">4</span><span class=\"t\">动手</span><span class=\"s\">两场演练</span></div>\n    <div class=\"j-step\"><span class=\"n\">5</span><span class=\"t\">自测</span><span class=\"s\">六个问题</span></div>\n  </div>\n\n  <section id=\"a\">\n    <h2><span class=\"no\">第 1 步</span>新城交付=竣工验收+分期付款+预算答辩</h2>\n    <p>先讲个故事。一座新城交付不是把一摞图纸交给市长就算完。验收逐项对：第一批住户能否按期入住、水电消防是否达标、预算花在哪、出事故谁指挥。更考验人的是答辩——委员会当场把预算砍 30%、换掉供应商、加一条新数据驻留法规，你还必须<b>重新算一遍</b>，说清哪段继续投、哪段暂停、哪段退出。</p>\n    <p>星河毕业任务同理：交付物<b>不是平台代码仓库</b>，而是一套能让架构委员会做投资/上线/暂停/退出决定的 <span class=\"term\">Portfolio</span>。战略/架构/契约/运行/安全/成本/协作产出收敛成带 Owner/版本/证据状态/复审时间的 <span class=\"term2\">Manifest</span>；每阶段能证明业务价值+质量+成本结果，且随时能回滚。现状痛点正是 A1 的：各维护身份/配额/用量/告警、谁拥有数据/谁负责事故理解不一、成本涨快于收入、只有演示没有运行证据。</p>\n    <div class=\"key\"><span class=\"tag\">一句话记住</span>能被质询、能在条件变化时重算、能证明价值与退出条件，才叫「对整个系统负责」。</div>\n    <div class=\"recap\"><b>收束：</b>毕业=竣工验收+分期付款节点+预算答辩；Portfolio 是随时可被质询可重算的城建档案。</div>\n  </section>\n\n  <section id=\"b\">\n    <h2><span class=\"no\">第 2 步</span>Manifest 六问 + 证据等级只升不降</h2>\n    <p>一摞文档不等于 Portfolio。每个产出至少回答<b>六问</b>：支持哪个业务目标/阶段门禁？哪位 Owner 负责？当前版本+基于什么假设？证据来自候选/PoC/试点/生产哪级？最近验证何时+结果？残余风险+何时复审/停投？Manifest 是索引+状态机，每次评审/门禁/复盘更新，记录「决策是否仍然成立」。</p>\n    <p>证据等级<span class=\"term\">candidate→PoC→pilot→production</span>只升不降：候选分析不能冒充生产证据；「只有演示」=candidate，必须补可复现运行证据才能升级。每个 claim 带 evidence_level/evidence_refs/last_verified_at/status/residual_risks/review_date。这把 A7 的证据五档、A8 的风险卡、A9 的归因链、A10 的批准状态串成一条<b>可追溯业务决策链</b>。</p>\n    <figure>\n      <svg viewBox=\"0 0 760 190\" role=\"img\" aria-label=\"Portfolio 决策链与三面架构\">\n        <defs><marker id=\"ara11\" markerWidth=\"8\" markerHeight=\"8\" refX=\"6\" refY=\"3\" orient=\"auto\"><path d=\"M0,0 L6,3 L0,6 Z\" fill=\"#A39B8E\"/></marker></defs>\n        <rect x=\"8\" y=\"14\" width=\"180\" height=\"40\" rx=\"10\" fill=\"#ECF1FB\" stroke=\"#C9D8F2\"/><text x=\"98\" y=\"38\" text-anchor=\"middle\" font-size=\"12\" font-weight=\"bold\" fill=\"#2F58A8\">业务目标与约束</text>\n        <rect x=\"212\" y=\"14\" width=\"200\" height=\"40\" rx=\"10\" fill=\"#E9F4F2\" stroke=\"#BFE0DB\"/><text x=\"312\" y=\"38\" text-anchor=\"middle\" font-size=\"12\" font-weight=\"bold\" fill=\"#1E7268\">Manifest(Owner/版本/证据/复审)</text>\n        <rect x=\"436\" y=\"14\" width=\"150\" height=\"40\" rx=\"10\" fill=\"#FBF3E4\" stroke=\"#EDD9B4\"/><text x=\"511\" y=\"38\" text-anchor=\"middle\" font-size=\"12\" font-weight=\"bold\" fill=\"#8A5510\">候选→PoC→试点→生产</text>\n        <rect x=\"610\" y=\"14\" width=\"142\" height=\"40\" rx=\"10\" fill=\"#FBEDE9\" stroke=\"#F0CFC6\"/><text x=\"681\" y=\"38\" text-anchor=\"middle\" font-size=\"12\" font-weight=\"bold\" fill=\"#B04A35\">门禁→灰度回滚→复盘</text>\n        <line x1=\"188\" y1=\"34\" x2=\"210\" y2=\"34\" stroke=\"#A39B8E\" stroke-width=\"2\" marker-end=\"url(#ara11)\"/>\n        <line x1=\"412\" y1=\"34\" x2=\"434\" y2=\"34\" stroke=\"#A39B8E\" stroke-width=\"2\" marker-end=\"url(#ara11)\"/>\n        <line x1=\"586\" y1=\"34\" x2=\"608\" y2=\"34\" stroke=\"#A39B8E\" stroke-width=\"2\" marker-end=\"url(#ara11)\"/>\n        <rect x=\"8\" y=\"76\" width=\"230\" height=\"44\" rx=\"10\" fill=\"#ECF1FB\" stroke=\"#C9D8F2\"/><text x=\"123\" y=\"94\" text-anchor=\"middle\" font-size=\"11.5\" font-weight=\"bold\" fill=\"#2F58A8\">Control Plane</text><text x=\"123\" y=\"110\" text-anchor=\"middle\" font-size=\"10\" fill=\"#7C7166\">目录/身份/策略/Admission/契约</text>\n        <rect x=\"262\" y=\"76\" width=\"230\" height=\"44\" rx=\"10\" fill=\"#E9F4F2\" stroke=\"#BFE0DB\"/><text x=\"377\" y=\"94\" text-anchor=\"middle\" font-size=\"11.5\" font-weight=\"bold\" fill=\"#1E7268\">Data Plane</text><text x=\"377\" y=\"110\" text-anchor=\"middle\" font-size=\"10\" fill=\"#7C7166\">Runtime/模型工具/RAG/租户隔离</text>\n        <rect x=\"516\" y=\"76\" width=\"236\" height=\"44\" rx=\"10\" fill=\"#FBF3E4\" stroke=\"#EDD9B4\"/><text x=\"634\" y=\"94\" text-anchor=\"middle\" font-size=\"11.5\" font-weight=\"bold\" fill=\"#8A5510\">Governance Plane</text><text x=\"634\" y=\"110\" text-anchor=\"middle\" font-size=\"10\" fill=\"#7C7166\">审计/风险/合规/证据/委员会</text>\n        <rect x=\"8\" y=\"136\" width=\"360\" height=\"40\" rx=\"10\" fill=\"#F4F2EC\" stroke=\"#EADFD3\"/><text x=\"188\" y=\"160\" text-anchor=\"middle\" font-size=\"11.5\" fill=\"#5B4A2F\">Data Platform: 事件/UsageFact/RatedUsage/Ledger/Invoice</text>\n        <rect x=\"392\" y=\"136\" width=\"360\" height=\"40\" rx=\"10\" fill=\"#F4F2EC\" stroke=\"#EADFD3\"/><text x=\"572\" y=\"160\" text-anchor=\"middle\" font-size=\"11.5\" fill=\"#5B4A2F\">Platform Ops: SLO/容量/发布/灾备/告警/成本/事故</text>\n      </svg>\n      <figcaption>图 1 · 三个面+横向支撑；毕业交付的是 Portfolio 决策链而不是代码仓库。</figcaption>\n    </figure>\n    <div class=\"key\"><span class=\"tag\">一句话记住</span>Manifest 六问让每项产出可问责；证据只升不降；演示≠生产证据。</div>\n    <div class=\"recap\"><b>收束：</b>六问+证据四级+claim 状态机+串起 A7 证据/A8 风险卡/A9 归因/A10 批准状态。</div>\n  </section>\n\n  <section id=\"c\">\n    <h2><span class=\"no\">第 3 步</span>三面统一架构 + 统一词汇：把十课拼成一张图</h2>\n    <p>统一目标架构=<b>Control Plane</b>(目录/身份/策略/Admission/Offering/Entitlement/Grant/契约配置，A5/A8)+<b>Data Plane</b>(Runtime/模型工具调用/RAG/Workflow/租户隔离/流式，A4/A6)+<b>Governance Plane</b>(审计/风险/合规/策略评估/证据/例外/委员会，A8/A10)，横向支撑 <b>Data Platform</b>(事件/UsageFact/RatedUsage/Ledger/Invoice，A9)与 <b>Platform Operations</b>(SLO/容量/发布/灾备/告警/成本/事故，A6/A7)。</p>\n    <p>统一词汇消除「谁拥有数据/谁负责事故」分歧：<span class=\"term\">Offering</span>=能力产品、<span class=\"term\">Entitlement</span>=商业权益、<span class=\"term\">Grant</span>=可撤销有期限授权快照(≠权益)、<span class=\"term\">Admission</span>=单次允许/拒绝(独立 admissionId)、<span class=\"term2\">UsageRecorded</span>=版本化事件信封、<span class=\"term2\">UsageFact</span>=不可变用量事实(不带价格)、<span class=\"term2\">RatedUsage</span>=按 RateVersion 计费结果、<span class=\"term2\">Ledger</span>=不可变追加账本、<span class=\"term2\">Invoice</span>=账单/分摊。每个概念有唯一责任边界(呼应 A3 数据权威)。</p>\n    <div class=\"key\"><span class=\"tag\">一句话记住</span>三面+两横向支撑=十课拼图；统一词汇+唯一责任边界消除「谁拥有/谁负责」分歧。</div>\n    <div class=\"recap\"><b>收束：</b>Control/Data/Governance 三面+Data Platform/Platform Ops 横向+九概念统一词汇+责任边界。</div>\n  </section>\n\n  <section id=\"d\">\n    <h2><span class=\"no\">第 4 步</span>六个月阶段门禁 + 条件突变重算</h2>\n    <p>六个月分阶段：阶段1 最小兼容链路(第6周两试点受控接入+归因≥95%)→阶段2 灰度扩量+生产归因≥99%+SLO/成本/安全达标→阶段3 经营复盘+退役旧路径。每阶段<b>门禁</b>=业务价值+质量+成本三结果齐备才放行；不达标则调整/暂停/退出，而非硬推。灰度+回滚能力贯穿(呼应 A4 Strangler、A6 弹性)。</p>\n    <p><b>动态条件重算</b>是毕业核心能力：委员会砍预算 30%→重算单位经济/技术债组合，保 Tier1 与安全基线、暂停低价值段；换供应商→重算退出成本/兼容/驻留(呼应 A1/A9)；新驻留法规→重算路由/复制拓扑(呼应 A2/A8 硬约束)。每次重算输出「继续/暂停/退出」+理由+证据+新复审日，<b>不悄悄改愿景</b>(呼应 A10)。受限数据不跨域、不阻塞现有应用交付是全程硬约束。</p>\n    <div class=\"key\"><span class=\"tag\">一句话记住</span>阶段门禁看三结果；条件突变(砍预算/换供应商/新法规)必须重算并给继续/暂停/退出；硬约束全程不破。</div>\n    <div class=\"recap\"><b>收束：</b>三阶段门禁+灰度回滚+三类突变重算+继续/暂停/退出决策+硬约束不破。</div>\n  </section>\n\n  <section id=\"e\">\n    <h2><span class=\"no\">第 5 步</span>多角色委员会答辩 + 毕业 Rubric：十课能力链</h2>\n    <p>毕业演练接受<b>多角色委员会</b>追问：业务问价值与时间、SRE 问 SLO/RTO/错误预算、安全问隔离/驻留/供应链、FinOps 问单位经济/归因/预算、平台问契约/接入周期、架构问取舍/ADR/退出。每个追问都要用<b>可追溯证据</b>回答，而非「我觉得」。答辩失败=某 claim 证据不足或硬约束被破，回去补证据/重算，不是口头过关。</p>\n    <p>毕业 Rubric 串起十课能力链：A1 战略(问题树/北极星/护栏)→A2 取舍(质量属性/ADR/沙盒)→A3 边界(上下文/数据权威/Strangler)→A4 一致性(不变量/Outbox/Saga/对账)→A5 平台(契约/Golden Path/门禁)→A6 弹性(形态/背压/复杂度上限)→A7 连续(SLO/错误预算/RTO-RPO/演练)→A8 安全(零信任/护栏/SBOM)→A9 成本(成本树/归因/单位经济/技术债)→A10 协作(授权/RFC/Team API/Agent 验收)→A11 整合(Portfolio/门禁/重算/答辩)。<b>对整个系统负责</b>=这十一环都能被质询、被重算、被证明。</p>\n    <div class=\"key\"><span class=\"tag\">一句话记住</span>答辩用证据不用感觉；Rubric=十一环能力链；毕业=能对投资/上线/暂停/退出负责并随时重算。</div>\n    <div class=\"recap\"><b>收束：</b>多角色追问+证据回答+Rubric 十一环+「对整个系统负责」的定义。</div>\n  </section>\n\n  <section id=\"lab\">\n    <h2><span class=\"no\">动手</span>两场演练：交仓库 vs 交 Portfolio、条件突变重算沙盒</h2>\n    <p>演练一看「交代码仓库+一摞文档」和「交可质询可重算 Portfolio」的差别。演练二勾选条件突变(砍预算30%/换供应商/新驻留法规)+拖当前阶段，看各段继续/暂停/退出与所需证据等级。</p>\n    <div class=\"lab\">\n      <div class=\"lab-head\"><b>演练一 · 两种毕业交付</b><span class=\"hint\">点按钮切换</span></div>\n      <div class=\"controls\"><div class=\"seg\" id=\"e1\"><button data-k=\"repo\" class=\"on\">❌ 交代码仓库</button><button data-k=\"port\">✅ 交 Portfolio</button></div></div>\n      <div class=\"lab-body\"><div><pre id=\"e1code\" style=\"margin:0;\"></pre></div><div class=\"logcat\"><div class=\"logcat-head\"><span>说明</span><span>live</span></div><div class=\"logcat-body\" id=\"e1log\"></div></div></div>\n      <div class=\"lab-foot\"><span class=\"hint\">同一个平台，两种命运</span></div>\n    </div>\n    <div class=\"lab\">\n      <div class=\"lab-head\"><b>演练二 · 条件突变重算沙盒</b><span class=\"hint\">勾突变+拖阶段</span></div>\n      <div class=\"controls\">\n        <div class=\"ctl\"><label>当前阶段</label><input type=\"range\" id=\"g1st\" min=\"1\" max=\"3\" value=\"2\"><span class=\"val\" id=\"g1stV\">2</span></div>\n        <div class=\"ctl\"><label><input type=\"checkbox\" id=\"g1cut\"> 预算砍30%</label></div>\n        <div class=\"ctl\"><label><input type=\"checkbox\" id=\"g1sup\"> 换供应商</label></div>\n        <div class=\"ctl\"><label><input type=\"checkbox\" id=\"g1law\"> 新驻留法规</label></div>\n      </div>\n      <div class=\"lab-body\"><div><div class=\"stats\" id=\"g1stats\"></div><div class=\"chips\" id=\"g1chips\"></div><div class=\"key\" id=\"g1hint\"></div></div><div class=\"logcat\"><div class=\"logcat-head\"><span>推导过程</span><span>live</span></div><div class=\"logcat-body\" id=\"g1log\"></div></div></div>\n      <div class=\"lab-foot\"><span class=\"hint\">硬约束(驻留/隔离/Tier1)不破；突变→重算→继续/暂停/退出+证据</span></div>\n    </div>\n    <div class=\"key\"><span class=\"tag\">看懂这两场演练</span>交仓库无法回答「砍预算后哪段停」；Portfolio 能重算。新驻留法规下跨域复制段必须暂停/改路由，而不是继续投。</div>\n  </section>\n\n  <section id=\"quiz\">\n    <h2><span class=\"no\">自测</span>六个问题</h2>\n    <div class=\"card\" id=\"quiz-box\"></div>\n    <p id=\"quiz-done\" style=\"display:none;font-weight:700;color:#1E7268;\">全对。恭喜毕业：你已经能把十一环能力收敛成可质询、可重算、可证明价值的 Portfolio，对整个系统负责。</p>\n  </section>\n\n  <section id=\"map\">\n    <h2><span class=\"no\">回顾</span>速查表</h2>\n    <table>\n      <tr><th>概念</th><th>大白话</th><th>要点</th></tr>\n      <tr><td>Portfolio</td><td>可质询可重算的城建档案</td><td>非代码仓库; 投资/上线/暂停/退出</td></tr>\n      <tr><td>Manifest 六问</td><td>目标/Owner/版本/证据/验证/复审</td><td>索引+状态机, 每次门禁更新</td></tr>\n      <tr><td>证据四级</td><td>候选→PoC→试点→生产</td><td>只升不降; 演示≠生产证据</td></tr>\n      <tr><td>三面+横向</td><td>Control/Data/Governance+Data/Ops</td><td>十课拼图</td></tr>\n      <tr><td>统一词汇</td><td>Offering…Invoice 九概念</td><td>唯一责任边界消除分歧</td></tr>\n      <tr><td>阶段门禁</td><td>业务+质量+成本三结果</td><td>不达标调整/暂停/退出</td></tr>\n      <tr><td>条件重算</td><td>砍预算/换供应商/新法规</td><td>继续/暂停/退出+证据+复审日</td></tr>\n      <tr><td>委员会答辩</td><td>多角色用证据回答</td><td>Rubric 十一环能力链</td></tr>\n    </table>\n    <div class=\"note\"><span class=\"tag\">说明</span>本页为教学整理，六个月/归因阈值为毕业场景假设；沙盒为启发式重算。口径以高级 README 与毕业篇底稿为准。</div>\n  </section>\n\n  <section id=\"refs\">\n    <h2><span class=\"no\">依据</span>参考链接</h2>\n    <div class=\"card refs\">\n      <h3 style=\"margin-top:0;\">原始底稿（本仓库）</h3>\n      <ul>\n        <li>《AI 后端开发：Java 实战》高级工程师 · 毕业篇-企业AI平台架构与分阶段交付 <span class=\"src\">— 本课重写底稿</span></li>\n        <li>高级工程师/README.md <span class=\"src\">— 毕业 Rubric 与责任模型</span></li>\n      </ul>\n      <h3>方法与规范</h3>\n      <ul>\n        <li><a href=\"https://adr.github.io/\" target=\"_blank\" rel=\"noopener\">ADR</a> <span class=\"src\">— 取舍与决策追溯</span></li>\n        <li><a href=\"https://c4model.com/\" target=\"_blank\" rel=\"noopener\">C4 Model</a> <span class=\"src\">— 三面架构表达</span></li>\n        <li><a href=\"https://sre.google/sre-book/service-level-objectives/\" target=\"_blank\" rel=\"noopener\">Google SRE · SLO</a> <span class=\"src\">— 阶段质量门禁</span></li>\n        <li><a href=\"https://www.finops.org/framework/\" target=\"_blank\" rel=\"noopener\">FinOps Framework</a> <span class=\"src\">— 阶段成本门禁与重算</span></li>\n      </ul>\n      <h3>课程完结</h3>\n      <ul>\n        <li>高级 A1–A11 能力链 <span class=\"src\">— 战略→取舍→边界→一致性→平台→弹性→连续→安全→成本→协作→整合</span></li>\n      </ul>\n    </div>\n    \n    \n  </section>", "toc": [{"id":"a","title":"Portfolio 故事"},{"id":"b","title":"Manifest/证据"},{"id":"c","title":"三面/词汇"},{"id":"d","title":"门禁/重算"},{"id":"e","title":"答辩/Rubric"},{"id":"lab","title":"两场演练"},{"id":"quiz","title":"本课自测"},{"id":"map","title":"速查表"},{"id":"refs","title":"参考链接"}], "scripts": "(function(){\n  var REPO=\"// ❌ 交代码仓库 + 一摞文档\\n委员会问: 砍预算30%后哪段停? → 答不出\\n问: 这结论谁负责/证据到哪级? → 没有 Owner\\n问: 新驻留法规下跨域复制还投吗? → 没重算\\n只有演示, 没有可复现运行证据\\n「我觉得可以上线」→ 口头过关\";\n  var PORT=\"// ✅ 交 Portfolio (Manifest + 决策链)\\n每项产出: 目标/Owner/版本/证据/验证/复审 六问\\n证据 candidate→PoC→pilot→production 只升不降\\n阶段门禁: 业务+质量+成本三结果\\n突变(砍预算/换供应商/新法规) → 重算 → 继续/暂停/退出\\n多角色委员会用可追溯证据答辩\";\n  function show(k){document.getElementById(\"e1code\").textContent=(k===\"repo\"?REPO:PORT);document.getElementById(\"e1log\").innerHTML=\"<div><span class=\\\"\"+(k===\"repo\"?\"err\":\"ok\")+\"\\\">\"+(k===\"repo\"?\"无法被质询/重算/证明\":\"可质询可重算可证明价值与退出\")+\"</span></div><div><span class=\\\"c\\\">// \"+(k===\"repo\"?\"交图纸不算竣工验收\":\"对整个系统负责\")+\"</span></div>\";}\n  document.querySelectorAll(\"#e1 button\").forEach(function(b){b.addEventListener(\"click\",function(){document.querySelectorAll(\"#e1 button\").forEach(function(x){x.classList.remove(\"on\");});b.classList.add(\"on\");show(b.getAttribute(\"data-k\"));});});\n  show(\"repo\");\n})();\n\n// 演练二：条件突变重算沙盒\n(function(){\n  function val(id){return parseInt(document.getElementById(id).value,10);}\n  function chk(id){return document.getElementById(id).checked;}\n  function calc(){\n    var st=val('g1st'); document.getElementById('g1stV').textContent=st;\n    var cut=chk('g1cut'), sup=chk('g1sup'), law=chk('g1law');\n    var mutations=(cut?1:0)+(sup?1:0)+(law?1:0);\n    // 各段决策\n    var core = '继续';                       // Tier1/安全基线始终继续\n    var low  = cut? '暂停':'继续';           // 低价值段砍预算则暂停\n    var cross= law? '暂停/改路由':'继续';    // 跨域复制段新法规暂停\n    var vend = sup? '重算退出成本':'继续';\n    var needEv = st>=3?'production':(st===2?'pilot':'PoC');\n    document.getElementById('g1stats').innerHTML=\n      '<div class=\"stat-box\"><b>'+mutations+'</b><small>条件突变数</small></div>'+\n      '<div class=\"stat-box '+(mutations?'bad':'good')+'\"><b>'+(mutations?'重算':'维持')+'</b><small>是否重算</small></div>'+\n      '<div class=\"stat-box\"><b>'+needEv+'</b><small>阶段所需证据</small></div>';\n    document.getElementById('g1chips').innerHTML=\n      '<span class=\"chip on\">Tier1/安全基线: '+core+'</span>'+\n      '<span class=\"chip '+(cut?'bad':'on')+'\">低价值段: '+low+'</span>'+\n      '<span class=\"chip '+(law?'bad':'on')+'\">跨域复制段: '+cross+'</span>'+\n      '<span class=\"chip '+(sup?'warn':'on')+'\">供应商段: '+vend+'</span>';\n    document.getElementById('g1hint').innerHTML='<span class=\"tag\">重算</span>'+\n      (mutations?'存在 '+mutations+' 项突变 → 重算单位经济/退出成本/驻留拓扑, 输出继续/暂停/退出+理由+证据+新复审日; 硬约束(驻留/隔离/Tier1)不破。':'无突变 → 维持原计划, 但仍按阶段门禁校验三结果。')+' 阶段'+st+' 需 '+needEv+' 级证据。';\n    document.getElementById('g1log').innerHTML=[\n      '<div><span class=\"api\">突变: 砍预算='+cut+' 换供应商='+sup+' 新法规='+law+' (共'+mutations+')</span></div>',\n      '<div><span class=\"'+(mutations?'err':'ok')+'\">重算 = '+(mutations?'是 → 继续/暂停/退出':'否 → 维持')+'</span></div>',\n      '<div><span class=\"ok\">硬约束: 受限数据不跨域 / 租户隔离 / Tier1 SLO 全程不破</span></div>',\n      '<div><span class=\"c\">// 阶段'+st+' 证据门槛='+needEv+'; 不悄悄改愿景</span></div>'\n    ].join('');\n  }\n  document.getElementById('g1st').addEventListener('input',calc);\n  ['g1cut','g1sup','g1law'].forEach(function(id){document.getElementById(id).addEventListener('change',calc);});\n  calc();\n})();\n\nconst QUIZ=[{\"q\":\"1. 毕业交付物是？\",\"opts\":[[\"可质询可重算可证明价值的 Portfolio\",true,\"对。不是代码仓库。\"],[\"平台代码仓库\",false,\"那是实现非决策组合。\"],[\"一摞设计文档\",false,\"文档≠Portfolio。\"]]},{\"q\":\"2. Manifest 每项产出至少回答？\",\"opts\":[[\"目标/Owner/版本/证据/验证/复审 六问\",true,\"对。可问责可追溯。\"],[\"只列文件名\",false,\"无责任无证据。\"],[\"只写结论\",false,\"缺假设与复审。\"]]},{\"q\":\"3. 证据等级顺序与规则？\",\"opts\":[[\"candidate→PoC→pilot→production, 只升不降\",true,\"对。演示≠生产证据。\"],[\"可随意降级\",false,\"只升不降。\"],[\"production 可冒充 candidate\",false,\"方向反了。\"]]},{\"q\":\"4. 新驻留法规下跨域复制段应？\",\"opts\":[[\"暂停/改路由, 重算后决策\",true,\"对。硬约束不破。\"],[\"继续投不管法规\",false,\"违反驻留。\"],[\"悄悄改愿景绕过\",false,\"A10 禁止。\"]]},{\"q\":\"5. 阶段门禁放行条件？\",\"opts\":[[\"业务价值+质量+成本三结果齐备\",true,\"对。不达标调整/暂停/退出。\"],[\"只看代码完成\",false,\"缺业务/成本。\"],[\"只看演示\",false,\"演示=candidate。\"]]},{\"q\":\"6. 委员会答辩应靠？\",\"opts\":[[\"可追溯证据, 而非「我觉得」\",true,\"对。证据不足回去补。\"],[\"口头保证\",false,\"无法质询。\"],[\"Agent 自证\",false,\"Agent 非责任主体。\"]]}];" }
  };
  return { get: function (t, s, l) { var k = t + "|" + s + "|" + l; return data[k] || (prev ? prev.get(t, s, l) : null); } };
})(window.QZ_CONTENT);
